  ui_story_5020_50200101_107_dialog_content = "Hã?!",
  ui_story_5020_50200101_108_dialog_content = "P-Por que vocês estão jogando feijão em mim?!",
  ui_story_5020_50200101_109_dialog_content = "Os feijões são para afastar fantasmas malignos que podem ter se infiltrado na celebração. É outra tradição nossa.",
