  ui_story_5020_50200101_112_dialog_content = "Ah, eu vejo.",
  ui_story_5020_50200101_113_dialog_content = "Ah, me desculpe por isso! As crianças podem ficar um pouco fora de controle às vezes.",
  ui_story_5020_50200101_114_dialog_content = "Está bem! É tudo uma parte das festividades, certo?",
  ui_story_5020_50200101_115_dialog_content = "Isso mesmo! Eles estão fazendo isso para nos proteger, então não há mal nenhum.",
  ui_story_5020_50200101_116_dialog_content = "Aqui, você pode ter este saco de feijão! Agora você também pode proteger os outros!",
  ui_story_5020_50200101_117_dialog_content = "Diga comigo! Espíritos se foram, que venha a felicidade!",
