  ui_story_5020_50200101_137_dialog_content = "Pai, olhe para lá! Suas máscaras parecem tão legais!",
  ui_story_5020_50200101_138_dialog_content = "Isso...",
  ui_story_5020_50200101_139_dialog_content = "<anim type=Shake><size=45>Graaaa!!</size></anim>",
  ui_story_5020_50200101_140_dialog_content = "É um fantasma! Os fantasmas estão aqui!",
  ui_story_5020_50200101_141_dialog_content = "Fantasmas! Fantasmas na cidade!",
  ui_story_5020_50200101_142_dialog_content = "Corram!",
  ui_story_5020_50200101_143_dialog_content = "Ajude-nos!!",
  ui_story_5020_50200101_144_dialog_content = "?!",
  ui_story_5020_50200101_145_dialog_content = "PlayerName! O inimigo está chegando! Prepare-se para a batalha!",
  ui_story_5020_50200202_1_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_5020_50200202_2_dialog_content = "Ahh! S-Fique longe de mim!",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5020_50200202_4_dialog_content = "Está ferida?",
  ui_story_5020_50200202_5_dialog_content = "N-Não... *Sniff* Estou bem. Obrigada.",
  ui_story_5020_50200202_6_dialog_content = "<anim type=Shake>Gra, ga...</anim>",
  ui_story_5020_50200202_7_dialog_content = "Droga... Não há fim para eles...",
  ui_story_5020_50200202_8_dialog_content = "O que nós vamos fazer?",
  ui_story_5020_50200202_9_dialog_content = "Corra para lá o mais rápido que puder e não olhe para trás.",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>Uraaagh...</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName? O que você está fazendo?",
  ui_story_5020_50200202_12_dialog_content = "Você tem murmurado estranhamente para si mesmo por um tempo agora.",
  ui_story_5020_50200202_13_dialog_content = "Eu tenho jogado feijões nos fantasmas... Sacos e sacos deles.",
  ui_story_5020_50200202_14_dialog_content = "Todo o tempo, eu tenho gritado:",
  ui_story_5020_50200202_15_option_content = "Espíritos se foram, que venha a felicidade!",
  ui_story_5020_50200202_16_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5020_50200202_17_option_content = "Espíritos se foram, que venha a felicidade!!",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5020_50200202_19_option_content = "Thpirith se foi!! May feliz venha!!",
  ui_story_5020_50200202_20_dialog_content = "Ai... gritei tanto que mordi a língua.",
  ui_story_5020_50200202_21_dialog_content = "Está funcionando?",
  ui_story_5020_50200202_22_dialog_content = "Bem, como você pode ver... provavelmente vamos precisar das habilidades de combate de todos para lidar com as coisas aqui.",
  ui_story_5020_50200202_23_dialog_content = "<size=45>Aaaahhhh!</size>",
  ui_story_5020_50200202_24_dialog_content = "Voltem, todos vocês! Não se aproxime...!",
  ui_story_5020_50200202_25_dialog_content = "Torrente Rápida!",
  ui_story_5020_50200202_26_dialog_content = "Como eles entraram em Sakai? Onde estão os guardas da cidade do general?",
  ui_story_5020_50200202_27_dialog_content = "Eles não podem estar todos guardando os portões da cidade, certo?",
  ui_story_5020_50200202_28_dialog_content = "De jeito nenhum... Nossa fuga não deveria merecer tanta atenção.",
  ui_story_5020_50200202_29_dialog_content = "Este lugar não é seguro. Precisamos encontrar uma maneira de ajudar os moradores da cidade a evacuar.",
  ui_story_5020_50200202_30_dialog_content = "PlayerName, leve as pessoas para fora daqui primeiro.",
  ui_story_5020_50200202_31_dialog_content = "Desta forma, todos! Me siga!",
  ui_story_5020_50200202_32_dialog_content = "Ei... Essa não é a sacerdotisa?",
  ui_story_5020_50200202_33_dialog_content = "Além de um bando de forasteiros também.",
  ui_story_5020_50200202_34_dialog_content = "Devemos ir com eles?",
  ui_story_5020_50200202_35_dialog_content = "Eles não parecem confiar em nós... O que devemos fazer?",
  ui_story_5020_50200202_36_dialog_content = "Por que você está hesitando?! Esta é uma situação de vida ou morte!",
  ui_story_5020_50200202_37_dialog_content = "<size=45>O que todos esses fantasmas estão fazendo aqui?!</size>",
  ui_story_5020_50200202_38_dialog_content = "Ei! PlayerName! Por que você e os outros ainda não escaparam?",
  ui_story_5020_50200202_39_dialog_content = "Eles estão virando todas as barracas! Retiro! Retiro!",
  ui_story_5020_50200202_40_dialog_content = "Esperar! Voltem aqui, vocês dois!",
  ui_story_5020_50200202_41_dialog_content = "Momo! Anzu! Nós realmente poderíamos usar sua ajuda agora!",
  ui_story_5020_50200202_42_dialog_content = "Tenho certeza que podemos conversar mais tarde, certo!?",
  ui_story_5020_50200202_43_dialog_content = "Isso mesmo! Neste momento, o mais importante é correr!!",
  ui_story_5020_50200202_44_dialog_content = "É o bastante! Calma, vocês dois!",
  ui_story_5020_50200202_45_dialog_content = "Vocês querem manter os negócios crescendo, certo?",
  ui_story_5020_50200202_46_dialog_content = "<size=45>Isso!</size>",
  ui_story_5020_50200202_47_dialog_content = "Você quer ser o melhor dono de restaurante de toda Cloud Island, certo?",
  ui_story_5020_50200202_48_dialog_content = "<size=45>Isso!</size>",
  ui_story_5020_50200202_49_dialog_content = "Bem, então, use seu habitual... ahem... fervor para levar todas essas pessoas para um lugar seguro.",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>Por aqui, todos! Venha, rápido!!!</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "Ai meus ouvidos...",
  ui_story_5020_50200301_1_dialog_content = "Kubou-sama, há vários mercadores esperando do lado de fora do castelo principal. Eles procuram o seu público.",
  ui_story_5020_50200301_2_dialog_content = "Agora, de todos os tempos? Eles não deveriam estar vendendo suas mercadorias nas ruas esta noite?",
  ui_story_5020_50200301_3_dialog_content = "Muito bem, deixe-os entrar.",
  ui_story_5020_50200301_4_dialog_content = "Kubou-sama! Você deve nos salvar!",
  ui_story_5020_50200301_5_dialog_content = "Dispense com as formalidades e diga-me o que aconteceu.",
  ui_story_5020_50200301_6_dialog_content = "Meu senhor, você não deve ter ouvido ainda! Sakai está sob ataque de fantasmas!",
  ui_story_5020_50200301_7_dialog_content = "Isso mesmo! Isso mesmo!",
  ui_story_5020_50200301_8_dialog_content = "Nossas barracas estão em pedaços! Todos nós perdemos muito dinheiro esta noite...",
  ui_story_5020_50200301_9_dialog_content = "O Festival Kasuga não será o mesmo este ano...",
  ui_story_5020_50200301_10_dialog_content = "*Limpa a garganta* Este é realmente o momento para suas queixas mesquinhas, pessoal? Calem-se, todos vocês!",
  ui_story_5020_50200301_11_dialog_content = "Perdoe-nos, Kubou-sama, mas viemos lhe contar assim que pudemos.",
  ui_story_5020_50200301_12_dialog_content = "Isso é verdade?",
  ui_story_5020_50200301_13_dialog_content = "Perdoe-me, Kubou-sama, mas os guardiões estão atualmente—",
  ui_story_5020_50200301_14_dialog_content = "Envie-os para Sakai, agora!",
  ui_story_5020_50200301_15_dialog_content = "E se houver mais contratempos, considere suas vidas perdidas!",
  ui_story_5020_50200301_16_dialog_content = "Sim!",
  ui_story_5020_50200301_17_dialog_content = "Somos eternamente gratos, meu senhor!",
  ui_story_5020_50200301_18_dialog_content = "As falhas de meus subordinados são de minha responsabilidade. Se alguma coisa, eu deveria estar me desculpando com todos vocês.",
  ui_story_5020_50200301_19_dialog_content = "Não mesmo!",
  ui_story_5020_50200301_20_dialog_content = "Na verdade, lembro-me claramente de ter visto Rinne-sama na cidade, evacuando as pessoas para um local seguro.",
  ui_story_5020_50200301_21_dialog_content = "Oh? Rinne está na cidade?",
  ui_story_5020_50200301_22_dialog_content = "Sim! Rinne-sama deve ter se preparado para as festividades da noite, para ela ter respondido ao ataque tão rapidamente.",
  ui_story_5020_50200301_23_dialog_content = "Sua presença heróica tocou a todos nós!",
  ui_story_5020_50200301_24_dialog_content = "Tanto que sentimos que devíamos ajudar.",
  ui_story_5020_50200301_25_dialog_content = "Ocupada como ela estava defendendo a todos nós, supomos que ela não tinha como dar a notícia a você. Por essa razão, decidimos vir e dizer-lhe nós mesmos. Por favor, nos perdoe, Kubou-sama!",
  ui_story_5020_50200301_26_dialog_content = "Não há nada para perdoar. Vocês estavam certos em fazer isso, todos vocês.",
  ui_story_5020_50200301_27_dialog_content = "Acredito que as forças rebeldes são as culpadas por levar os fantasmas para a cidade. Eles devem procurar usar o caos para promover seus planos, mesmo às custas da segurança das pessoas.",
  ui_story_5020_50200301_28_dialog_content = "Mas não tenha medo. Os guardiões estão a caminho, e sua segurança está praticamente garantida.",
  ui_story_5020_50200301_29_dialog_content = "A Ilha das Nuvens é abençoada por ter você, Kubou-sama!",
  ui_story_5020_50200301_30_dialog_content = "Vamos nos despedir agora.",
  ui_story_5020_50200301_31_dialog_content = "O povo de Cloud Island não entende o significado de paz... tudo o que eles sabem é fazer exigências infinitas.",
  ui_story_5020_50200301_32_dialog_content = "Para realizar seus desejos, certos sacrifícios devem ser feitos.",
  ui_story_5020_50200301_33_dialog_content = "Mais surpreendente, porém, é que a <color=#FFB400>Wisp</color> ainda não deu um passo.",
  ui_story_5020_50200301_34_dialog_content = "Nagi foi encontrado?",
  ui_story_5020_50200301_35_dialog_content = "Ainda não.",
  ui_story_5020_50200301_36_dialog_content = "<size=45>Tolos inúteis!</size>",
  ui_story_5020_50200301_37_dialog_content = "Minhas desculpas, Kubou-sama.",
  ui_story_5020_50200301_38_dialog_content = "Traga o exército fantasma para Sakai. Isso deve atraí-los.",
  ui_story_5020_50200301_39_dialog_content = "Temos que acabar com isso hoje, de uma vez por todas.",
  ui_story_5020_50200301_40_dialog_content = "O Festival Kasuga deve prosseguir sem incidentes.",
  ui_story_5020_50200301_41_dialog_content = "Entendi.",
  ui_story_5020_50200301_42_dialog_content = "Às vezes, Rinne é muito parecido com você.",
  ui_story_5020_50200301_43_dialog_content = "Se você ainda estivesse aqui... Tenho certeza que você gostaria muito dela.",
  ui_story_5020_50200301_44_dialog_content = "Desde o dia em que você partiu, coloquei todas as minhas esperanças em criar uma nova sacerdotisa.",
  ui_story_5020_50200301_45_dialog_content = "Mas não importa como eu veja, todos os meus esforços foram, sem dúvida, em vão.",
  ui_story_5020_50200301_46_dialog_content = "Você é o especial, afinal.",
  ui_story_5020_50200301_47_dialog_content = "Mas tenha certeza, vou cumprir minha promessa para você.",
  ui_story_5020_50200301_48_dialog_content = "Este é o seu desejo... E o meu também.",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>Graah!</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "Há muitos deles!",
  ui_story_5020_50200301_51_dialog_content = "O general Fujikumo realmente pretende ficar parado e assistir as pessoas morrerem?",
  ui_story_5020_50200301_52_dialog_content = "Torrente Rápida...",
  ui_story_5020_50200301_53_dialog_content = "Esses fantasmas estão ficando mais fortes...",
  ui_story_5020_50200301_54_dialog_content = "Tenho que focar... Nossa prioridade é tirar os civis daqui.",
  ui_story_5020_50200301_55_dialog_content = "Rinne... Vice... Só aguente mais um pouco!",
  ui_story_5020_50200302_1_dialog_content = "Espero que Momo e Anzu estejam melhor do lado deles...",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName!</size>",
  ui_story_5020_50200302_3_dialog_content = "Alguém chamou meu nome agora mesmo?",
  ui_story_5020_50200302_4_dialog_content = "Huh? Eu não ouvi nada.",
  ui_story_5020_50200302_5_dialog_content = "PlayerName!!",
  ui_story_5020_50200302_6_dialog_content = "Espere, acho que ouvi agora.",
  ui_story_5020_50200302_7_dialog_content = "Parece que alguém está tentando chegar até nós!",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName!!!</size>",
  ui_story_5020_50200302_9_option_content = "Momo?!",
  ui_story_5020_50200302_10_dialog_content = "Você não deveria estar evacuando os civis com Anzu?",
  ui_story_5020_50200302_11_option_content = "Anzu?!",
  ui_story_5020_50200302_12_dialog_content = "Você não deveria estar evacuando os civis com Momo?",
  ui_story_5020_50200302_13_dialog_content = "Não, PlayerName! Eu sou Momo!",
  ui_story_5020_50200302_14_dialog_content = "Oh! S-Desculpe por isso... É só que vocês dois parecem muito parecidos.",
  ui_story_5020_50200302_15_dialog_content = "O que você está fazendo aqui? Onde estão Anzu e os civis?",
  ui_story_5020_50200302_16_dialog_content = "Eu estou bem aqui!",
  ui_story_5020_50200302_17_dialog_content = "Por que vocês dois trouxeram todas as pessoas de volta?!",
  ui_story_5020_50200302_18_dialog_content = "Nós nunca saímos! Enquanto vocês estavam cobrindo nossa retaguarda, mais fantasmas apareceram na nossa frente!",
  ui_story_5020_50200302_19_dialog_content = "Estamos completamente cercados!",
  ui_story_5020_50200302_20_dialog_content = "\"Nestes tempos difíceis, todos devemos abrir nosso próprio caminho para a vitória!\"",
  ui_story_5020_50200302_21_dialog_content = "Por que isso soa tão familiar?",
  ui_story_5020_50200302_22_dialog_content = "Será?",
  ui_story_5020_50200302_23_dialog_content = "Eu folheei o Guia de Viagem da Ilha Nuvem de Yao algum tempo atrás.",
  ui_story_5020_50200302_24_dialog_content = "Este foi um dos slogans usados na seção de Moda da brochura.",
  ui_story_5020_50200302_25_dialog_content = "Para te dizer a verdade, Rinne... Não acho que seja muito o seu estilo...",
  ui_story_5020_50200302_26_dialog_content = "Mesmo? Achei que ficou muito legal!",
  ui_story_5020_50200302_27_dialog_content = "É que por algum motivo estranho...",
  ui_story_5020_50200302_28_dialog_content = "não consigo a imagem Sinsa vestido como um samurai rebelde da Ilha das Nuvens da minha cabeça.",
  ui_story_5020_50200302_29_dialog_content = "Agora que você mencionou... Eu vejo agora também.",
  ui_story_5020_50200302_30_dialog_content = "Tudo bem! Hora de cortar nosso próprio caminho para a vitória!",
  ui_story_5020_50200302_31_dialog_content = "Vamos pegá-los, soldados!",
  ui_story_5020_50200302_32_dialog_content = "Carregar!!!",
  ui_story_5020_50200302_33_dialog_content = "O-o que...?!",
  ui_story_5020_50200302_34_dialog_content = "Esta é realmente toda a ajuda que o General Fujikumo poderia dispensar?",
  ui_story_5020_50200302_35_dialog_content = "A julgar por suas roupas, acho que são pessoas normais.",
  ui_story_5020_50200302_36_dialog_content = "Eles são os rebeldes.",
  ui_story_5020_50200302_37_dialog_content = "Isso é <color=#FFB400>Wisp</color> para você, muito obrigado!",
  ui_story_5020_50200302_38_dialog_content = "Agora quem é você?",
  ui_story_5020_50200302_39_dialog_content = "Estavam...",
  ui_story_5020_50200302_40_dialog_content = "Uma sacerdotisa e um casal de forasteiros, hein?",
  ui_story_5020_50200302_41_dialog_content = "Agarre-os!",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>Achoo!</anim>",
  ui_story_5020_50200401_2_dialog_content = "Ugh... Alguém deve estar falando mal de mim agora.",
  ui_story_5020_50200401_3_dialog_content = "Minhas pernas estão dormentes de tanto agachar... Mas parece bem seguro lá fora agora.",
  ui_story_5020_50200401_4_dialog_content = "Ahhh muito melhor! Um pouco de alongamento sempre resolve!",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50200401_6_dialog_content = "Como diabos esses fantasmas conseguiram entrar no castelo principal?",
  ui_story_5020_50200401_7_dialog_content = "<size=45>Hoo-ah!</size>",
  ui_story_5020_50200401_8_dialog_content = "O que há de errado com aquele velho? Ele não poderia pelo menos proteger o castelo principal?",
  ui_story_5020_50200401_9_dialog_content = "E agora meu penteado está todo arruinado! Maldições... Você sabe quanto tempo leva para amarrar assim?!",
  ui_story_5020_50200401_10_dialog_content = "Também... Onde estou agora?",
  ui_story_5020_50200401_11_dialog_content = "Este castelo é muito grande... E por que parece que todos os andares são exatamente iguais?",
  ui_story_5020_50200401_12_dialog_content = "Eu já estive neste corredor?",
  ui_story_5020_50200401_13_dialog_content = "Ugh, não é bom... Eu preciso deixar marcadores ou algo assim.",
  ui_story_5020_50200401_14_dialog_content = "Uau, este é um fantasma robusto... Você deve ter conseguido muito o que comer em seu tempo, hein?",
  ui_story_5020_50200401_15_dialog_content = "Agora, se eu ficar assim... Ponha seu braço assim... E faça seus dedos apontarem para aquele lado...",
  ui_story_5020_50200401_16_dialog_content = "Voilá! Agora eu sei para que lado estou indo!",
  ui_story_5020_50200401_17_dialog_content = "Exceto... Ugh, isso realmente fede.",
  ui_story_5020_50200401_18_dialog_content = "... Onde é a saída?! Não quero mais tocar em fantasmas!!",
  ui_story_5020_50200401_19_dialog_content = "Argh, isso é tão nojento! Juro, vou tomar pelo menos dez banhos assim que voltar!",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>Gongo...!</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>Gongo, Gongo...!</color>",
  ui_story_5020_50200401_22_dialog_content = "Merda... É esse o som dos tambores taiko Rinne estava falando antes?",
  ui_story_5020_50200401_23_dialog_content = "Há quanto tempo estou preso aqui?!",
  ui_story_5020_50200401_24_dialog_content = "Grr... Junte-se, Yao! Vamos, cérebro, temos que descobrir alguma coisa!",
  ui_story_5020_50200401_25_dialog_content = "PlayerName sempre diz para confiar na minha intuição.",
  ui_story_5020_50200401_26_dialog_content = "E minha intuição diz para ir por aqui...",
  ui_story_5020_50200401_27_dialog_content = "Agora diz para virar à esquerda...",
  ui_story_5020_50200401_28_dialog_content = "J-Só tenho que continuar virando à direita! Tenho certeza que nunca fui assim antes...",
  ui_story_5020_50200401_29_dialog_content = "...",
  ui_story_5020_50200401_30_dialog_content = "PlayerName, seu mentiroso! Minha intuição é completamente inútil!!",
  ui_story_5020_50200401_31_dialog_content = "Ah, esqueça.",
  ui_story_5020_50200401_32_dialog_content = "Ao invés de bater minha cabeça contra a parede assim, eu deveria fazer o que o mestre fez e simplesmente pular do Cloud Pavilion.",
  ui_story_5020_50200401_33_dialog_content = "Tudo bem! Soa como um plano sólido para mim!",
  ui_story_5020_50200401_34_dialog_content = "Sim... quero dizer, daqui de cima...",
  ui_story_5020_50200401_35_dialog_content = "Nem parece tão alto!",
  ui_story_5020_50200401_36_dialog_content = "O Mestre provavelmente usou aquela cerejeira para amortecer sua queda... certo?",
  ui_story_5020_50200401_37_dialog_content = "Pronto, cerejeira... Pronto ou não, aí vou eu!",
  ui_story_5020_50200401_38_dialog_content = "...",
  ui_story_5020_50200401_39_dialog_content = "Eu... eu não posso fazer isso!!",
  ui_story_5020_50200401_40_dialog_content = "Não sei como o mestre fez isso, mas com certeza não consigo!",
  ui_story_5020_50200401_41_dialog_content = "Quero dizer, olha o quão alto eu estou...",
  ui_story_5020_50200401_41X1_dialog_content = "Um verdadeiro guerreiro nunca faria nada que não tenha certeza!",
  ui_story_5020_50200401_41X2_dialog_content = "Vou ver se há uma corda ou algo para me ajudar a descer...",
  ui_story_5020_50200401_41X3_dialog_content = "Ahh... O único lugar para esconder algo nesta sala deveria ser...",
  ui_story_5020_50200401_41X4_dialog_content = "O armário!",
  ui_story_5020_50200401_41X5_dialog_content = "Hum?",
  ui_story_5020_50200401_41X6_dialog_content = "O que foi isso?",
  ui_story_5020_50200401_41X7_dialog_content = "Por que esse sentimento é tão <color=#FFB400>familiar</color>?",
  ui_story_5020_50200401_41X8_dialog_content = "Deixa pra lá! Vou abrir o guarda-roupa e procurar uma corda primeiro!",
  ui_story_5020_50200401_42_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_44_dialog_content = "Hã?!",
  ui_story_5020_50200401_45_dialog_content = "Um sino Kagura?",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding!</color>",
  ui_story_5020_50200401_47_dialog_content = "Ah... Um <color=#FFB400>carrilhão de vento</color> No guarda roupa?",
  ui_story_5020_50200401_48_dialog_content = "Estranho... Por que soa tanto como um Kagura Bell?",
  ui_story_5020_50200401_49_dialog_content = "Espere... Isso é...",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>Dez anos atrás.</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_52_dialog_content = "Shh! Quieto, Yao! Fique dentro de casa e não faça barulho!",
  ui_story_5020_50200401_53_dialog_content = "O que está acontecendo lá fora, Tsuki? Eu estou assustado...",
  ui_story_5020_50200401_54_dialog_content = "Você não vai me deixar aqui sozinho, vai?",
  ui_story_5020_50200401_55_dialog_content = "Por favor, Tsuki...",
  ui_story_5020_50200401_56_dialog_content = "Apenas durma um pouco dentro disso <color=#FFB400>guarda roupa</color>, e tudo ficará bem quando você acordar. Eu prometo.",
  ui_story_5020_50200401_57_dialog_content = "Tsuki...",
  ui_story_5020_50200401_58_dialog_content = "<size=45>Abra!</size>",
  ui_story_5020_50200401_58X1_dialog_content = "(Alguém está tentando invadir!)",
  ui_story_5020_50200401_58X2_dialog_content = "Venha! Guarde o portão! Não deixe nenhuma presença vil entrar aqui!",
  ui_story_5020_50200401_58X3_dialog_content = "\"Uma ode aos mortos e aos vivos. May essa música guia suas almas de volta aos seus devidos lugares...\"",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_58X5_dialog_content = "(É um canto Kagura Bell que exorciza fantasmas...!)",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5020_50200401_59_dialog_content = "Pare! Quem é Você?! Você não pode...",
  ui_story_5020_50200401_60_dialog_content = "<size=45>Cai fora!</size>",
  ui_story_5020_50200401_61_dialog_content = "(Aquela voz... Mestre?)",
  ui_story_5020_50200401_62_dialog_content = "Nagi?",
  ui_story_5020_50200401_63_dialog_content = "Não ouse me chamar assim, <color=#FFB400>Senhora Sacerdotisa</color>.",
  ui_story_5020_50200401_64_dialog_content = "Você não merece.",
  ui_story_5020_50200401_65_dialog_content = "Diga-me... Por que convenceu o Wisp a se render?",
  ui_story_5020_50200401_66_dialog_content = "Você me prometeu que se tornaria uma sacerdotisa pelo bem do povo! Para trazer prosperidade a todos na Cloud Island!",
  ui_story_5020_50200401_67_dialog_content = "...",
  ui_story_5020_50200401_68_dialog_content = "Eu lhe fiz uma pergunta!",
  ui_story_5020_50200401_69_dialog_content = "?!",
  ui_story_5020_50200401_70_dialog_content = "Tsuki!",
  ui_story_5020_50200401_71_dialog_content = "Você perdeu a cabeça, Nagi?!",
  ui_story_5020_50200401_72_dialog_content = "Ela é sua irmã!",
  ui_story_5020_50200401_73_dialog_content = "Guardas! Mate-a agora!",
  ui_story_5020_50200401_74_dialog_content = "Não...!",
  ui_story_5020_50200401_75_dialog_content = "Por favor, Kubou-sama... Não faça isso...",
  ui_story_5020_50200401_76_dialog_content = "O rio sob nossos pés passa pelas fazendas de arroz a oeste da cidade...",
  ui_story_5020_50200401_77_dialog_content = "O jardim que fica no sopé ocidental... As flores de cerejeira brancas devem estar em plena floração agora...",
  ui_story_5020_50200401_78_dialog_content = "Por favor, não manche suas belas pétalas com a cor do sangue...",
  ui_story_5020_50200401_79_dialog_content = "Quando eu me for... Deite-me para descansar sob aquelas flores de cerejeira brancas...",
  ui_story_5020_50200401_80_dialog_content = "Prometa-me... Certo?",
  ui_story_5020_50200401_81_dialog_content = "Apenas espere, Tsuki! Eu prometo, eu vou...",
  ui_story_5020_50200401_82_dialog_content = "\"Uma ode... aos mortos e aos vivos...\"",
  ui_story_5020_50200401_83_dialog_content = "Espere... O que você está fazendo?!",
  ui_story_5020_50200401_84_dialog_content = "Tsuki, não! Seu corpo não vai suportar isso agora!",
  ui_story_5020_50200401_85_dialog_content = "\"May esta canção...\"",
  ui_story_5020_50200401_86_dialog_content = "\"Guia minha alma de volta ao seu devido lugar.\"",
  ui_story_5020_50200401_87_dialog_content = "Urgh...!",
  ui_story_5020_50200401_88_dialog_content = "...",
  ui_story_5020_50200401_89_dialog_content = "...",
  ui_story_5020_50200401_90_dialog_content = "Mesmo depois de tudo o que aconteceu, você ainda deseja protegê-la...?",
  ui_story_5020_50200401_91_dialog_content = "Guardas...",
  ui_story_5020_50200401_92_dialog_content = "Deste dia em diante, o exército fantasma guardará esses terrenos para sempre.",
  ui_story_5020_50200401_93_dialog_content = "Tranque esta mulher pelo resto de sua vida miserável, para que ela nunca mais veja a luz do dia com seus próprios olhos!",
  ui_story_5020_50200401_94_dialog_content = "Sim!",
  ui_story_5020_50200401_95_dialog_content = "O resto... Deve ser feito de acordo com os desejos de Tsuki.",
  ui_story_5020_50200401_96_dialog_content = "Como você manda.",
  ui_story_5020_50200401_97_dialog_content = "Como por você...",
  ui_story_5020_50200401_98_dialog_content = "Tudo o que ela queria era proteger você, e você a assassinou em troca... Você não tem vergonha? Você não tem coração?!",
  ui_story_5020_50200401_99_dialog_content = "Eu nunca precisei de sua proteção, e você vai morrer em minhas mãos, assim como ela.",
  ui_story_5020_50200401_100_dialog_content = "Você esteve cego para a verdade todo esse tempo, Nagi...",
  ui_story_5020_50200401_101_dialog_content = "Cego para a razão por trás de sua decisão de ficar ao meu lado.",
  ui_story_5020_50200401_102_dialog_content = "Foi precisamente porque eu lhe dei uma espécie de aprovação silenciosa, que ela soube de coisas que nunca deveria saber.",
  ui_story_5020_50200401_103_dialog_content = "A diferença entre exorcizar fantasmas e controlá-los não é tão grande quanto parece, mas as leis e costumes da Ilha das Nuvens podem ser entendidos através dessa distinção.",
  ui_story_5020_50200401_104_dialog_content = "Preservar a paz em Cloud Island é um esforço para toda a vida. Ela entendeu isso, assim como minha posição, e obedientemente depositou sua confiança em mim.",
  ui_story_5020_50200401_105_dialog_content = "E sabendo o que ela sabia, ela escolheu protegê-lo apesar de sua ignorância violenta.",
  ui_story_5020_50200401_106_dialog_content = "Não... Você está errado!",
  ui_story_5020_50200401_107_dialog_content = "Mas o que mais poderia ser, então?",
  ui_story_5020_50200401_108_dialog_content = "Os laços de irmandade que você rompeu completamente?!",
  ui_story_5020_50200401_109_dialog_content = "Ela tinha a mesma idade que você, mas seus olhos estavam sempre cheios de compaixão e compreensão, de uma sabedoria muito além de seus anos...",
  ui_story_5020_50200401_110_dialog_content = "E ainda... Você a assassinou!!!",
  ui_story_5020_50200401_111_dialog_content = "Você tirou a vida dela, e suas esperanças e sonhos para a Ilha das Nuvens com ela!!!",
  ui_story_5020_50200401_112_dialog_content = "Que direito você tem de viver mais neste mundo?!?!",
  ui_story_5020_50200401_113_dialog_content = "...",
  ui_story_5020_50200401_114_dialog_content = "<size=33>Por que ela escolheu protegê-lo, mesmo ao custo de sua própria vida...?!</size>",
  ui_story_5020_50200401_115_dialog_content = "Que honra para mim poder ouvir um discurso tão grandioso!",
  ui_story_5020_50200401_116_dialog_content = "Torcendo a narrativa de sua exploração dela, em uma história de confiança e compreensão...",
  ui_story_5020_50200401_117_dialog_content = "Foi assim que você a enganou?!",
  ui_story_5020_50200401_118_dialog_content = "Ela era uma pessoa de extraordinária sabedoria.",
  ui_story_5020_50200401_119_dialog_content = "Em seu coração, ela sabia que nossos objetivos eram proteger este lugar a todo custo. Como tal, a palavra exploração não existia entre nós.",
  ui_story_5020_50200401_120_dialog_content = "... Eu vejo. O selo que ela colocou em você é exatamente o castigo que você merece.",
  ui_story_5020_50200401_121_dialog_content = "May você passa o resto de seus dias aqui, com nada além de seu ódio e raiva para lhe fazer companhia.",
  ui_story_5020_50200401_122_dialog_content = "Eu juro que vou te matar um dia!",
  ui_story_5020_50200401_123_dialog_content = "Veremos se esse dia chegará.",
  ui_story_5020_50200401_124_dialog_content = "Tsuki...?",
  ui_story_5020_50200401_125_dialog_content = "Meu mestre... Foi quem <size=45>matou a sacerdotisa?!</size>",
  ui_story_5020_50200401_126_dialog_content = "Mas meu mestre não é esse tipo de pessoa...",
  ui_story_5020_50200401_127_dialog_content = "Você a usou assim no passado, também?",
  ui_story_5020_50200401_128_dialog_content = "Garotinha... Você não passa de uma substituta.",
  ui_story_5020_50200401_129_dialog_content = "Você sabe o que aconteceu com a última sacerdotisa?",
  ui_story_5020_50200401_130_dialog_content = "Cala a sua boca!",
  ui_story_5020_50200401_131_dialog_content = "Guardas, prendam-na!",
  ui_story_5020_50200401_132_dialog_content = "Não... Deve haver algum tipo de engano.",
  ui_story_5020_50200401_133_dialog_content = "Urgh... Minha cabeça...",
  ui_story_5020_50200401_134_dialog_content = "Eu preciso me juntar PlayerName, e diga-lhes tudo isso!",
  ui_story_5020_50200501_1_dialog_content = "Ei! Vamos! Não podemos apenas usar nossas palavras?",
  ui_story_5020_50200501_2_dialog_content = "Isso mesmo! Deve haver algum mal-entendido!",
  ui_story_5020_50200501_3_dialog_content = "...",
  ui_story_5020_50200501_4_dialog_content = "Deve ser seguro aqui, por enquanto.",
  ui_story_5020_50200501_5_dialog_content = "Vá ajudar as pessoas a se instalarem.",
  ui_story_5020_50200501_6_dialog_content = "Sim!",
  ui_story_5020_50200501_7_dialog_content = "Quanto a esses falantes...",
  ui_story_5020_50200501_8_dialog_content = "Amarre-os em um poste em algum lugar.",
  ui_story_5020_50200501_9_dialog_content = "Quê?!",
  ui_story_5020_50200501_10_dialog_content = "Sim!",
  ui_story_5020_50200501_11_dialog_content = "Ei! Pare de se contorcer!",
  ui_story_5020_50200501_12_dialog_content = "Ah... esses caras...",
  ui_story_5020_50200501_13_dialog_content = "Espere um minuto, há algo que eu não entendo!",
  ui_story_5020_50200501_14_dialog_content = "Vocês estão protegendo os civis, certo? Nós também! Isso não significa que estamos na mesma página?",
  ui_story_5020_50200501_15_dialog_content = "Não mesmo.",
  ui_story_5020_50200501_16_dialog_content = "Você está com a sacerdotisa, o que significa que andamos juntos tão bem quanto água e fogo.",
  ui_story_5020_50200501_17_dialog_content = "A sacerdotisa? O que ela tem a ver com isso...?",
  ui_story_5020_50200501_18_dialog_content = "Sim, eu sei.",
  ui_story_5020_50200501_19_dialog_content = "Se não estou errado, Amemori é um de vocês, correto?",
  ui_story_5020_50200501_20_dialog_content = "Lembre-se do seu lugar, sacerdotisa.",
  ui_story_5020_50200501_21_dialog_content = "Você não está em posição de nos fazer perguntas.",
  ui_story_5020_50200501_22_dialog_content = "Heh... Parece que falei fora de hora.",
  ui_story_5020_50200501_23_dialog_content = "Talvez devêssemos esperar que você se apresentasse?",
  ui_story_5020_50200501_24_dialog_content = "Ou talvez até deixá-lo fazer seu discurso de recrutamento...?",
  ui_story_5020_50200501_25_dialog_content = "Hahahaha! Então a sacerdotisa tem senso de humor, hein?",
  ui_story_5020_50200501_26_dialog_content = "Quem diria que chegaria o dia em que uma sacerdotisa da Ilha das Nuvens nem saberia quem são os Wisp.",
  ui_story_5020_50200501_27_dialog_content = "Quem sabe, talvez em algumas gerações, até a própria Cloud Island seja esquecida!",
  ui_story_5020_50200501_28_dialog_content = "No final, não é como se nada disso importasse para você.",
  ui_story_5020_50200501_29_dialog_content = "Como uma sacerdotisa, você só precisa ficar em seu grande e confortável castelo e passar seus dias preocupando sua linda cabecinha com aquele seu Kubou-sama.",
  ui_story_5020_50200501_30_dialog_content = "...",
  ui_story_5020_50200501_31_dialog_content = "Isso é demais!",
  ui_story_5020_50200501_32_dialog_content = "Rinne tem protegido o povo de Koufu-jou o tempo todo! Vocês mesmos viram!",
  ui_story_5020_50200501_33_dialog_content = "Protegendo? Poupe-nos dos altos eufemismos, forasteiro.",
  ui_story_5020_50200501_34_dialog_content = "Ela nada mais é do que uma gata doméstica, perseguindo e matando ratos criados em casa.",
  ui_story_5020_50200501_35_dialog_content = "Isso não é proteção. É um desempenho.",
  ui_story_5020_50200501_36_dialog_content = "Uma performance? O que isso deveria significar...?",
  ui_story_5020_50200501_37_dialog_content = "Deixe-me perguntar uma coisa, de onde você acha que todos esses fantasmas vieram?",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_39_dialog_content = "Você é uma especialista no assunto, não é, sacerdotisa? Importa-se de explicar?",
  ui_story_5020_50200501_40_dialog_content = "... Quando há uma abundância de energia Yin, as almas dos mortos não podem descansar e, em vez disso, retornam como fantasmas vingativos.",
  ui_story_5020_50200501_41_dialog_content = "Então diga-nos, de onde veio essa abundância de energia Yin? A partir do nada?",
  ui_story_5020_50200501_42_dialog_content = "...",
  ui_story_5020_50200501_43_dialog_content = "Ficar em silêncio, hein? Não se preocupe, eu já sei a resposta: <color=#FFB400>alguém</color> está por trás disso.",
  ui_story_5020_50200501_44_dialog_content = "Desde os tempos antigos, Cloud Island foi o lar de três <color=#FFB400>artefatos espirituais</color>.",
  ui_story_5020_50200501_45_dialog_content = "<color=#FFB400>Pedaço de céu</color>, a espada matadora de fantasmas e fonte de energia Yang, está atualmente desaparecida.",
  ui_story_5020_50200501_46_dialog_content = "<color=#FFB400>Rebelião e Ryojin</color>, o jade que equilibra Yin e Yang, está na posse de Wisp.",
  ui_story_5020_50200501_47_dialog_content = "E a <color=#FFB400>Espelho de nuvem</color>, a fonte de energia Yin, sempre esteve nas mãos do general.",
  ui_story_5020_50200501_48_dialog_content = "Esse foi o espelho que o general roubou Rinne mais cedo...",
  ui_story_5020_50200501_49_dialog_content = "\"Assim como nuvens escuras obscurecem o sol, os habitantes do inferno cruzam para o mundo dos vivos.\"",
  ui_story_5020_50200501_50_dialog_content = "A única coisa que poderia convocar tantos fantasmas para enlouquecer na cidade... <color=#FFB400>Espelho de nuvem</color>.",
  ui_story_5020_50200501_51_dialog_content = "Então me diga, quem você acha que é o cérebro por trás de tudo isso? Tenho certeza que você pode adivinhar agora!",
  ui_story_5020_50200501_52_dialog_content = "... Para ser honesto, também chegamos a uma conclusão semelhante.",
  ui_story_5020_50200501_53_dialog_content = "Mas ainda há algo que não consigo descobrir.",
  ui_story_5020_50200501_54_dialog_content = "Se Fujikumo pode controlar fantasmas à sua vontade, por que ele continua criando e treinando sacerdotisas para exorcizá-los?",
  ui_story_5020_50200501_55_dialog_content = "Eu já não te disse? Não passa de uma performance.",
  ui_story_5020_50200501_56_dialog_content = "Os fantasmas estão aqui porque estão fazendo o que ele manda. A sacerdotisa é apenas uma figura de proa usada para conquistar as pessoas e mantê-las sob controle.",
  ui_story_5020_50200501_57_dialog_content = "Mantê-los sob controle?",
  ui_story_5020_50200501_58_dialog_content = "O general controla os fantasmas, que ele usa para plantar medo nos corações dos civis de Cloud Island.",
  ui_story_5020_50200501_59_dialog_content = "Mas o medo não é maneira de governar a Ilha das Nuvens. Qualquer líder de verdade poderia lhe dizer isso.",
  ui_story_5020_50200501_60_dialog_content = "É aí que a sacerdotisa entra em cena. Eles são treinados para enfrentar esse medo pelo bem do povo.",
  ui_story_5020_50200501_61_dialog_content = "O povo passa a confiar na sacerdotisa, e a sacerdotisa obedece ao general e somente a ele. Este é o seu método de governar sobre todos nós.",
  ui_story_5020_50200501_62_dialog_content = "Infelizmente para ele, ele se superestimou.",
  ui_story_5020_50200501_63_dialog_content = "As pessoas de Cloud Island não são estúpidas. Não seremos enganados por um ato de desorientação de dois bits como este.",
  ui_story_5020_50200501_64_dialog_content = "Vocês, sacerdotisas, afirmam que exorcizando fantasmas, estão devolvendo o equilíbrio à terra... E, no entanto, como é que a ameaça de fantasmas nunca diminuiu depois de todo esse tempo?",
  ui_story_5020_50200501_65_dialog_content = "...",
  ui_story_5020_50200501_66_dialog_content = "Este lugar nem sempre foi chamado Koufu-jou. Isso, nós não esquecemos.",
  ui_story_5020_50200501_67_dialog_content = "Não importa quantos castelos eles construam, ou quanta riqueza eles tragam...",
  ui_story_5020_50200501_68_dialog_content = "Eles sempre serão invasores para nós.",
  ui_story_5020_50200501_69_dialog_content = "Os Wisp são os únicos verdadeiros guardiões da Cloud Island.",
  ui_story_5020_50200501_70_dialog_content = "Porque só nós somos nativos desta terra.",
  ui_story_5020_50200501_71_dialog_content = "Invasores? É assim que você vê as pessoas na ilha principal...?",
  ui_story_5020_50200501_72_dialog_content = "Imagino que vocês não tenham aprendido muito sobre a história de Cloud Island.",
  ui_story_5020_50200501_73_dialog_content = "E isso faz sentido. Quero dizer, onde você poderia ter aprendido sobre isso?",
  ui_story_5020_50200501_74_dialog_content = "(Eu aprendi um pouco da história de Cloud Island com Anzu e Momo...)",
  ui_story_5020_50200501_75_dialog_content = "(Mas a versão do Wisp pode ter algumas diferenças importantes?)",
  ui_story_5020_50200501_76_dialog_content = "Você está certo. Não sabemos muito sobre a Ilha das Nuvens, já que somos de algum lugar distante.",
  ui_story_5020_50200501_77_dialog_content = "Eu imaginei. Deixe-me preenchê-lo em alguns dos pontos mais importantes. Considere isso um pequeno ato de misericórdia.",
  ui_story_5020_50200501_78_dialog_content = "Anos e anos atrás, antes que os samurais da ilha principal pisassem na Ilha das Nuvens, era um lugar muito mais bonito do que é agora.",
  ui_story_5020_50200501_79_dialog_content = "Um lugar generoso, livre de conflitos, onde fantasmas raramente apareciam para aterrorizar a terra.",
  ui_story_5020_50200501_80_dialog_content = "As origens do Wisp podem ser rastreadas até aquela época. Naquela época, era nossa missão sagrada lutar contra os fantasmas e garantir a paz em Cloud Island.",
  ui_story_5020_50200501_81_dialog_content = "Mas quem acabou arruinando essa paz não foram os fantasmas, mas os vivos.",
  ui_story_5020_50200501_82_dialog_content = "Nunca satisfeitos com as terras que já ocupavam, a ilha principal enviou seu primeiro general para conquistar este lugar.",
  ui_story_5020_50200501_83_dialog_content = "Wisp nunca havia travado uma guerra contra os vivos antes, mas eles colocaram suas vidas em risco, mesmo assim.",
  ui_story_5020_50200501_84_dialog_content = "O general lançou campanhas contra a Ilha das Nuvens, mas nunca conseguiu nos anexar inteiramente.",
  ui_story_5020_50200501_85_dialog_content = "Mas um dia, eles planejaram sua trama mais desprezível até agora. Eles começaram a aprender a controlar fantasmas, para que pudessem usar sua força maligna na batalha.",
  ui_story_5020_50200501_86_dialog_content = "Naqueles anos, não havia escassez de fantasmas selvagens vagando pela terra.",
  ui_story_5020_50200501_87_dialog_content = "Estávamos desmoronados sob a ameaça fantasmagórica, junto com a soberania da Ilha das Nuvens. Logo depois, o general construiu Koufu-jou ao longo do oceano e o designou como sua sede do poder.",
  ui_story_5020_50200501_88_dialog_content = "Sem outra escolha, os remanescentes de Wisp foram forçados a se esconder, abrigando sua fúria contra seus invasores e passando esse ódio de geração em geração.",
  ui_story_5020_50200501_89_dialog_content = "Se a guerra nos ensinou uma coisa, é esperar pela oportunidade perfeita. Então, e só então, a Ilha das Nuvens recuperará o que perdeu há tantos anos.",
  ui_story_5020_50200501_90_dialog_content = "(Então foi assim que surgiu o conflito na Ilha das Nuvens...?)",
  ui_story_5020_50200501_91_dialog_content = "(Na superfície, foi uma batalha entre pessoas e fantasmas, mas na realidade... foi uma guerra entre duas nações diferentes...)",
  ui_story_5020_50200501_92_dialog_content = "E esta oportunidade...",
  ui_story_5020_50200501_93_dialog_content = "Pode estar sobre nós em breve.",
  ui_story_5020_50200501_94_dialog_content = "As pessoas estão seguras agora, senhor.",
  ui_story_5020_50200501_95_dialog_content = "A seguir, precisamos...",
  ui_story_5020_50200501_96_dialog_content = "Entendo. Vamos conversar por lá.",
  ui_story_5020_50200501_97_dialog_content = "...",
  ui_story_5020_50200501_98_dialog_content = "Você acha que ele estava dizendo a verdade sobre a história de Cloud Island?",
  ui_story_5020_50200501_99_dialog_content = "Não sei... Ele falou tanto, ainda não digeri tudo...",
  ui_story_5020_50200501_100_dialog_content = "Sempre pensei que estava obedecendo à ordem mais simples.",
  ui_story_5020_50200501_101_dialog_content = "Obedecer ao meu pai adotivo e proteger o povo de Koufu-jou.",
  ui_story_5020_50200501_102_dialog_content = "Mas se o que ele diz é verdade...",
  ui_story_5020_50200501_103_dialog_content = "Então há um paradoxo entre esses dois comandos.",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_105_dialog_content = "Tudo o que eu fiz... Realmente não passou de uma performance?",
  ui_story_5020_50200501_106_dialog_content = "N-Nós não precisamos acreditar em tudo que ele disse, certo?",
  ui_story_5020_50200501_107_dialog_content = "Quer dizer, ele nem sabe a diferença entre amigo e inimigo. Veja como ele nos amarrou!",
  ui_story_5020_50200501_108_dialog_content = "Certo, PlayerName?",
  ui_story_5020_50200501_109_dialog_content = "Por que você parece que está se afastando?",
  ui_story_5020_50200501_110_dialog_content = "Xiu!",
  ui_story_5020_50200501_111_dialog_content = "Estou tentando escutar a conversa deles...",
  ui_story_5020_50200501_112_dialog_content = "Escutar?!",
  ui_story_5020_50200501_113_dialog_content = "Parece divertido! Eu também quero participar!",
  ui_story_5020_50200501_114_dialog_content = "Tudo bem, aproxime-se então.",
  ui_story_5020_50200501_115_dialog_content = "Hum-hum!",
  ui_story_5020_50200501_116_dialog_content = "Não há outro lugar para irmos, senhor.",
  ui_story_5020_50200501_117_dialog_content = "As ruas estão cheias de fantasmas. Não conseguimos entrar em contato com nenhum de nossos funcionários estacionados em outros lugares...",
  ui_story_5020_50200501_118_dialog_content = "Entendo. Não vamos a lugar nenhum e defenderemos este lugar com nossas vidas.",
  ui_story_5020_50200501_119_dialog_content = "Senhor, você mencionou que Amemori-sama conseguiu resgatar o comandante, sim?",
  ui_story_5020_50200501_120_dialog_content = "Você acha que... eles virão nos ajudar?",
  ui_story_5020_50200501_121_dialog_content = "Não há razão para ter medo. Enquanto a Espada do Submundo estiver viva e bem, o que são mais alguns fantasmas?",
  ui_story_5020_50200501_122_dialog_content = "(Então Amemori está do lado deles, afinal!)",
  ui_story_5020_50200501_123_dialog_content = "(Sim... E pelo que parece, ela ocupa uma posição bem alta dentro do Wisp.)",
  ui_story_5020_50200501_124_dialog_content = "Ouça aqui, garoto. Wisp nunca precisou da ajuda de ninguém quando se trata de batalha.",
  ui_story_5020_50200501_125_dialog_content = "Mesmo se você for o último de pé, você deve lutar até o amargo fim.",
  ui_story_5020_50200501_126_dialog_content = "Isso significa que eles...",
  ui_story_5020_50200501_127_dialog_content = "O comandante e Amemori-sama tem outros assuntos para tratar.",
  ui_story_5020_50200501_128_dialog_content = "Não estou nem um pouco preocupado, e você também não deveria estar.",
  ui_story_5020_50200501_129_dialog_content = "(Ah, certo... eu me pergunto como Amemori está fazendo agora...)",
  ui_story_5020_50200501_130_dialog_content = "(Relaxe, tenho certeza de que ela está perfeitamente bem. Ela é incrivelmente forte, afinal.)",
  ui_story_5020_50200501_131_dialog_content = "...",
  ui_story_5020_50200501_132_dialog_content = "Todos ficam aliviados ao saber que o comandante está bem, senhor.",
  ui_story_5020_50200501_133_dialog_content = "É só que... Nenhum de nós jamais viu o rosto do comandante.",
  ui_story_5020_50200501_134_dialog_content = "Alguns de nosso povo estão começando a se perguntar se as notícias são verdadeiras ou não.",
  ui_story_5020_50200501_135_dialog_content = "Alguns até dizem...",
  ui_story_5020_50200501_136_dialog_content = "Que depois de dez anos, ela praticamente se esqueceu de Wisp...",
  ui_story_5020_50200501_137_dialog_content = "...",
  ui_story_5020_50200501_138_dialog_content = "Já chega.",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50200501_140_dialog_content = "(?!)",
  ui_story_5020_50200501_141_dialog_content = "O que foi?",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50200501_143_dialog_content = "(Está perto! Parece que está vindo do outro lado da parede!)",
  ui_story_5020_50200501_144_dialog_content = "Prepare-se para a batalha!",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>Graaaa!!</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "Como eles nos encontraram tão rapidamente...?",
  ui_story_5020_50200501_148_dialog_content = "Ah, era apenas uma questão de tempo, suponho.",
  ui_story_5020_50200501_149_dialog_content = "Irmãos do Wisp!",
  ui_story_5020_50200501_150_dialog_content = "Sim senhor!!!",
  ui_story_5020_50200501_151_dialog_content = "Reúna sua coragem!",
  ui_story_5020_50200501_152_dialog_content = "Estamos enviando cada um desses fantasmas de volta para o subsolo!",
  ui_story_5020_50200501_153_dialog_content = "Isso não é bom... Os fantasmas nos encontraram!",
  ui_story_5020_50200501_154_dialog_content = "Eu sei! O que devemos fazer agora?!",
  ui_story_5020_50200501_155_dialog_content = "Não podemos fazer nada enquanto estamos amarrados!",
  ui_story_5020_50200501_156_dialog_content = "<size=45>Ei! Apresse-se e deixe-nos ir!!!</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>Nós podemos ajudá-lo a combatê-los!!!</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_159_dialog_content = "Uh... Você está mesmo ouvindo?",
  ui_story_5020_50200501_160_dialog_content = "Que tal usar suas habilidades psíquicas?",
  ui_story_5020_50200501_161_dialog_content = "Oh, certo! EU...",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50200501_164_dialog_content = "Ah não! Em um momento como esse também...",
  ui_story_5020_50200501_165_dialog_content = "Está se aproximando!",
  ui_story_5020_50200501_166_dialog_content = "Mesmo se eu chamar um lutador Wisp... Será que eles chegarão a tempo?",
  ui_story_5020_50200501_167_dialog_content = "Diz-me tu!",
  ui_story_5020_50200501_168_dialog_content = "Heh... Só precisamos encontrar alguém para nos libertar, certo?",
  ui_story_5020_50200501_169_dialog_content = "Se Wisp não estiver disposto a ajudar, teremos que nos contentar com isso.",
  ui_story_5020_50200501_170_dialog_content = "Aquela coisa? Espere, você não quer dizer...",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "Deixar para o fantasma cortar a corda?! Acho que vamos ser picados primeiro!",
  ui_story_5020_50200501_170X3_dialog_content = "Bem, então você deve ficar abaixado por um momento.",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>Uraaagh...</anim>",
  ui_story_5020_50200501_173_dialog_content = "Viu?",
  ui_story_5020_50200501_174_dialog_content = "Os fantasmas às vezes podem ser mais obedientes do que as pessoas.",
  ui_story_5020_50200502_1_dialog_content = "Senhor! Os fantasmas estão vindo de todas as direções!",
  ui_story_5020_50200502_2_dialog_content = "Estamos cercados!",
  ui_story_5020_50200502_3_dialog_content = "O ataque surpresa deles agora foi para ganhar tempo para montar o cerco...",
  ui_story_5020_50200502_4_dialog_content = "Com táticas como essa, algo deve estar acontecendo nos bastidores.",
  ui_story_5020_50200502_5_dialog_content = "O que você quer dizer, senhor...?",
  ui_story_5020_50200502_6_dialog_content = "Em todos os nossos anos lutando contra fantasmas, Wisp já foi encurralado por eles?",
  ui_story_5020_50200502_7_dialog_content = "Fantasmas não são as criaturas mais perceptivas. Eles são atraídos para o combate, sim, mas nunca tão rapidamente.",
  ui_story_5020_50200502_8_dialog_content = "E para nos colocar em uma situação como esta... Eles tiveram que discernir nossa localização primeiro, então se unir e nos cercar antes de finalmente atacar todos de uma vez.",
  ui_story_5020_50200502_9_dialog_content = "Alguém tem que estar controlando suas ações.",
  ui_story_5020_50200502_10_dialog_content = "Parece que o general... está finalmente fazendo sua jogada.",
  ui_story_5020_50200502_11_dialog_content = "O que devemos fazer então, senhor?",
  ui_story_5020_50200502_12_dialog_content = "Precisamos nos informar sobre a situação primeiro, para que possamos procurar um caminho através de suas fileiras.",
  ui_story_5020_50200502_13_dialog_content = "No mínimo, precisamos tirar os civis com segurança de Koufu-jou...",
  ui_story_5020_50200502_14_dialog_content = "(Cuidado, atrás de você!)",
  ui_story_5020_50200502_15_dialog_content = "?!",
  ui_story_5020_50200502_16_dialog_content = "Quem disse isso agora?!",
  ui_story_5020_50200502_17_dialog_content = "(Sou eu! Um dos estranhos que você amarrou antes!)",
  ui_story_5020_50200502_18_dialog_content = "Como você escapou?",
  ui_story_5020_50200502_19_dialog_content = "Se você for corajoso o suficiente para falar comigo, então pare de se esgueirar e se mostre!",
  ui_story_5020_50200502_20_dialog_content = "(Er... eu não estou realmente perto de você agora.)",
  ui_story_5020_50200502_21_dialog_content = "(Estou usando minha habilidade psíquica para me comunicar com você.)",
  ui_story_5020_50200502_22_dialog_content = "Como assim?",
  ui_story_5020_50200502_23_dialog_content = "(Bem, é... Uh, não importa. Não é importante.)",
  ui_story_5020_50200502_24_dialog_content = "(O importante é que meus amigos e eu podemos ajudá-lo!)",
  ui_story_5020_50200502_25_dialog_content = "Ajuda? Ah! Wisp nunca pede ajuda, especialmente de prisioneiros como você!",
  ui_story_5020_50200502_26_dialog_content = "(Com todos os fantasmas atacando aqui, é realmente a hora de agir alto e poderoso?)",
  ui_story_5020_50200502_27_dialog_content = "Você...!",
  ui_story_5020_50200502_28_dialog_content = "(Fantasmas estão se aproximando da rua à sua direita!)",
  ui_story_5020_50200502_29_dialog_content = "Da direita?",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50200502_31_dialog_content = "Você está falando a verdade...",
  ui_story_5020_50200502_32_dialog_content = "Olhos à direita! Soldados, ataquem!",
  ui_story_5020_50200502_33_dialog_content = "(Uh, na verdade... Eles estão vindo da esquerda também.)",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50200502_35_dialog_content = "Mas que... Por que você não me contou antes?!",
  ui_story_5020_50200502_36_dialog_content = "(Porque podemos lidar com as coisas deste lado.)",
  ui_story_5020_50200502_37_dialog_content = "De nada!",
  ui_story_5020_50200502_38_dialog_content = "Por que você está nos ajudando?",
  ui_story_5020_50200502_39_dialog_content = "O general não levantará um dedo contra você, enquanto você estiver com a sacerdotisa.",
  ui_story_5020_50200502_40_dialog_content = "(É uma longa história, mas não estamos exatamente nos melhores termos com o general agora...)",
  ui_story_5020_50200502_41_dialog_content = "Como assim?",
  ui_story_5020_50200502_42_dialog_content = "(Nós meio que brigamos um com o outro não muito tempo atrás... É difícil de explicar.)",
  ui_story_5020_50200502_43_dialog_content = "(Depois de ouvir sua história, percebi que a história de Cloud Island é muito mais complicada do que eu pensava.)",
  ui_story_5020_50200502_44_dialog_content = "(Como pessoas de fora, não temos o direito de tomar uma posição sobre seus problemas.)",
  ui_story_5020_50200502_45_dialog_content = "(Mas lutar contra fantasmas para proteger os outros nunca é a escolha errada.)",
  ui_story_5020_50200502_46_dialog_content = "(É por isso que, pelo menos por enquanto, precisamos trabalhar juntos e derrotá-los!)",
  ui_story_5020_50200502_47_dialog_content = "...",
  ui_story_5020_50200502_48_dialog_content = "Tá bom.",
  ui_story_5020_50200502_49_dialog_content = "Vou aceitá-lo como aliado em nossa batalha, pelo menos por enquanto.",
  ui_story_5020_50200502_50_dialog_content = "Rinne! Você está bem?",
  ui_story_5020_50200502_51_dialog_content = "... Sim, obrigado.",
  ui_story_5020_50200502_52_dialog_content = "Você está ferido, Rinne?",
  ui_story_5020_50200502_53_dialog_content = "Normalmente, você já teria exorcizado todos esses fantasmas.",
  ui_story_5020_50200502_54_dialog_content = "...",
  ui_story_5020_50200502_55_dialog_content = "Perdoe-me por preocupá-lo.",
  ui_story_5020_50200502_56_dialog_content = "Eu só... năo estou no estado de espírito certo.",
  ui_story_5020_50200502_57_dialog_content = "É por causa da história daquele cara Wisp?",
  ui_story_5020_50200502_58_dialog_content = "... Sim.",
  ui_story_5020_50200502_59_dialog_content = "Não consigo tirar essa palavra da cabeça... \"Desempenho\"...",
  ui_story_5020_50200502_60_dialog_content = "Isso continua atormentando meus pensamentos, e sou incapaz de lutar com todo o meu poder.",
  ui_story_5020_50200502_61_dialog_content = "Eu... sinto como se tivesse perdido a razão de lutar.",
  ui_story_5020_50200502_62_dialog_content = "Mas eu pensei que você já tinha descoberto, depois da nossa briga com o general no castelo principal...",
  ui_story_5020_50200502_63_dialog_content = "Só fiquei com raiva na hora. não entendi bem as coisas...",
  ui_story_5020_50200502_64_dialog_content = "Mas agora, acho que entendi.",
  ui_story_5020_50200502_65_dialog_content = "Entender o quê?",
  ui_story_5020_50200502_66_dialog_content = "Desde o início, ele nunca quis que eu exorcizasse fantasmas.",
  ui_story_5020_50200502_67_dialog_content = "Em vez disso, ele queria me usar... Para me forçar a usar um traje de sacerdotisa, para que eu pudesse enganar os civis no palco que ele montou.",
  ui_story_5020_50200502_68_dialog_content = "Todos esses anos eu estava vivendo no meu papel, orgulhosa de ser a sacerdotisa que poderia dissipar todo o medo.",
  ui_story_5020_50200502_69_dialog_content = "Mas agora que não estou mais me apresentando no palco, de repente estou ouvindo minha própria história, pela boca dos outros.",
  ui_story_5020_50200502_70_dialog_content = "Eu... eu realmente não sei mais quem eu sou...",
  ui_story_5020_50200502_71_dialog_content = "Devo ser a pessoa que deveria ser, ou a pessoa que deveria ser...?",
  ui_story_5020_50200601_1_dialog_content = "Todos, venham comigo!",
  ui_story_5020_50200601_2_dialog_content = "O que, estamos saindo de novo? Onde estamos indo para este momento?",
  ui_story_5020_50200601_3_dialog_content = "Estamos cada vez mais longe de Sakai!",
  ui_story_5020_50200601_4_dialog_content = "Isso é porque estamos deixando Koufu-jou completamente.",
  ui_story_5020_50200601_5_dialog_content = "Que? Por que?!",
  ui_story_5020_50200601_6_dialog_content = "Como vamos fazer negócios no meio do nada?",
  ui_story_5020_50200601_7_dialog_content = "Os fantasmas estão invadindo a cidade sob suas ordens. Neste momento, qualquer lugar fora da cidade é mais seguro do que dentro dela.",
  ui_story_5020_50200601_8_dialog_content = "Ai...",
  ui_story_5020_50200601_9_dialog_content = "Momo... Ele está dizendo que o general é quem convocou os fantasmas?",
  ui_story_5020_50200601_10_dialog_content = "Acho que sim, Anzu. Mas por que?",
  ui_story_5020_50200601_11_dialog_content = "O general está tentando... *Gulp* Matar todo mundo...?",
  ui_story_5020_50200601_12_dialog_content = "Acho que não... Ele é o governante de Koufu-jou, afinal.",
  ui_story_5020_50200601_13_dialog_content = "Quem ele governaria se matasse todos os seus súditos?",
  ui_story_5020_50200601_14_dialog_content = "Talvez ele... queira dominar os fantasmas?",
  ui_story_5020_50200601_15_dialog_content = "D-Não diga isso! Você está me enlouquecendo!",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50200601_17_dialog_content = "?!",
  ui_story_5020_50200601_18_dialog_content = "<size=45>Ei, você muito! Pare aí mesmo!</size>",
  ui_story_5020_50200601_19_dialog_content = "!!!",
  ui_story_5020_50200601_20_dialog_content = "Droga...",
  ui_story_5020_50200601_21_dialog_content = "É o meio da noite. Onde você pensa que está indo?",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>Os telhados sobre as ruas de Koufu-jou</color>",
  ui_story_5020_50200601_21X2_dialog_content = "E-É tão alto! Devagar, pessoal!",
  ui_story_5020_50200601_21X3_dialog_content = "Só um pouco mais. Os telhados são a única saída rápida e segura agora.",
  ui_story_5020_50200601_22_dialog_content = "É um beco sem saída, PlayerName!",
  ui_story_5020_50200601_23_dialog_content = "O que deveríamos fazer?",
  ui_story_5020_50200601_24_dialog_content = "Parece que não temos escolha...",
  ui_story_5020_50200601_25_dialog_content = "Vamos pular?",
  ui_story_5020_50200601_26_dialog_content = "Sim...",
  ui_story_5020_50200601_27_dialog_content = "Maravilha!",
  ui_story_5020_50200601_28_dialog_content = "Ei! Não pule assim!",
  ui_story_5020_50200601_29_dialog_content = "Agora quem vai me ajudar...?",
  ui_story_5020_50200601_30_dialog_content = "Se apresse, PlayerName!",
  ui_story_5020_50200601_31_dialog_content = "Você não poderá pular se os fantasmas o pegarem!",
  ui_story_5020_50200601_32_dialog_content = "Eu sei que!",
  ui_story_5020_50200601_33_dialog_content = "Ufa...",
  ui_story_5020_50200601_34_dialog_content = "Aqui vai!!!",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>Aaaaaah!</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5020_50200601_37_dialog_content = "Estou... Ainda estou vivo?",
  ui_story_5020_50200601_38_dialog_content = "É impossível encontrar um espaço seguro para pousar com os olhos fechados, você sabe.",
  ui_story_5020_50200601_39_dialog_content = "Ainda bem que eu estava lá para te pegar!",
  ui_story_5020_50200601_40_dialog_content = "Você é o melhor, Vice...",
  ui_story_5020_50200601_41_dialog_content = "Claro, mas... Você poderia ficar sozinho agora?",
  ui_story_5020_50200601_42_dialog_content = "O-Ah, desculpe...",
  ui_story_5020_50200601_43_dialog_content = "Agora...",
  ui_story_5020_50200601_44_dialog_content = "Nos encontramos novamente, forasteiros.",
  ui_story_5020_50200601_45_dialog_content = "Então, você esteve escondido nos telhados o tempo todo?",
  ui_story_5020_50200601_46_dialog_content = "Hum...",
  ui_story_5020_50200601_47_dialog_content = "Eu sei que é melhor mantermos alguma distância um do outro...",
  ui_story_5020_50200601_48_dialog_content = "Mas acho que não podemos nos dar ao luxo da distância neste momento.",
  ui_story_5020_50200601_49_dialog_content = "Você está nos pedindo para vir em seu socorro agora?",
  ui_story_5020_50200601_50_dialog_content = "Este realmente não é o momento para sua atitude...",
  ui_story_5020_50200601_51_dialog_content = "Não estou tentando causar mais problemas para você.",
  ui_story_5020_50200601_52_dialog_content = "Estou apenas tentando salientar que os fantasmas estarão aqui em cima muito em breve.",
  ui_story_5020_50200601_53_dialog_content = "Se você e seu pessoal estiverem prontos para desistir, gostaríamos de continuar correndo.",
  ui_story_5020_50200601_54_dialog_content = "E se você ainda quiser lutar contra os fantasmas, também ficaremos felizes em ajudar.",
  ui_story_5020_50200601_55_dialog_content = "Tch, você é espirituoso, não é...",
  ui_story_5020_50200601_56_dialog_content = "Vamos ver se você consegue falar em uma luta.",
  ui_story_5020_50200601_57_dialog_content = "Você verá por si mesmo em um pouco!",
  ui_story_5020_50200601_58_dialog_content = "Uma última coisa, no entanto. Mantenha essa mulher longe de nós.",
  ui_story_5020_50200601_59_dialog_content = "Não queremos lutar ao lado da sacerdotisa. Nem agora, nem nunca.",
  ui_story_5020_50200601_60_dialog_content = "...",
  ui_story_5020_50200601_61_dialog_content = "É... Na verdade, Rinne é...",
  ui_story_5020_50200601_62_dialog_content = "Eu estou bem com isso.",
  ui_story_5020_50200601_63_dialog_content = "Vendo como você e seus homens estão dispostos a enfrentar a situação.",
  ui_story_5020_50200601_64_dialog_content = "Estou mais do que feliz em obrigar.",
  ui_story_5020_50200601_65_dialog_content = "Você...",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50200601_68_dialog_content = "Tch... Esqueça.",
  ui_story_5020_50200601_69_dialog_content = "Wisp! Prepare-se para a batalha!",
  ui_story_5020_50200602_1_dialog_content = "Quantos ficam?",
  ui_story_5020_50200602_2_dialog_content = "Está quase acabando... Posso sentir que a energia ao nosso redor enfraqueceu.",
  ui_story_5020_50200602_3_dialog_content = "Vice!",
  ui_story_5020_50200602_4_dialog_content = "Entendido!",
  ui_story_5020_50200602_5_dialog_content = "Você ainda pode lutar?",
  ui_story_5020_50200602_6_dialog_content = "Com quem você pensa que está falando, garoto?",
  ui_story_5020_50200602_7_dialog_content = "Apenas se preocupe consigo mesmo por enquanto.",
  ui_story_5020_50200602_8_dialog_content = "Eu posso sentir isso... Seu corpo está no limite.",
  ui_story_5020_50200602_9_dialog_content = "Se você for tão intuitivo quanto pensa que é, saberá que meu espírito está ansioso para partir.",
  ui_story_5020_50200602_10_dialog_content = "Mas de que lhe servirá seu espírito se seu corpo cair de exaustão?",
  ui_story_5020_50200602_11_dialog_content = "Dê uma boa olhada, garoto. Essas coisas contra as quais estamos lutando nem têm corpos, mas continuam vindo até nós!",
  ui_story_5020_50200602_12_dialog_content = "É porque eles ainda têm um pouco de seus espíritos neles.",
  ui_story_5020_50200602_13_dialog_content = "Nós aqui acreditamos que o espírito é muito mais importante do que o corpo físico.",
  ui_story_5020_50200602_14_dialog_content = "Podemos perder a batalha, e até nossas vidas, mas nunca nos renderemos.",
  ui_story_5020_50200602_15_dialog_content = "Essa é uma convicção bastante assustadora que vocês têm...",
  ui_story_5020_50200602_16_dialog_content = "Mas não será necessário desta vez.",
  ui_story_5020_50200602_17_dialog_content = "Vai acabar em breve.",
  ui_story_5020_50200602_18_dialog_content = "Hunf...",
  ui_story_5020_50200602_19_dialog_content = "Este é o último!",
  ui_story_5020_50200602_20_dialog_content = "Ufa... estou exausto.",
  ui_story_5020_50200602_21_dialog_content = "Qual caminho a seguir, garoto?",
  ui_story_5020_50200602_22_dialog_content = "Precisamos nos apressar e nos encontrar com o resto dos civis.",
  ui_story_5020_50200602_23_dialog_content = "Espere... Não baixe a guarda ainda!",
  ui_story_5020_50200602_24_dialog_content = "Um grupo de pessoas se aproxima...",
  ui_story_5020_50200602_25_dialog_content = "Pessoas? Que tipo de gente?",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>Pisque, pise, pise...</color>",
  ui_story_5020_50200602_27_dialog_content = "Se eu não estiver errado, eu não acho que eles são pessoas que você vai ficar muito feliz em ver...",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>Pisque, pise, pise...</color>",
  ui_story_5020_50200602_29_dialog_content = "Escumalha rebelde!",
  ui_story_5020_50200602_30_dialog_content = "Flagelo de todos os Koufu-jou!",
  ui_story_5020_50200602_31_dialog_content = "Hoje...",
  ui_story_5020_50200602_32_dialog_content = "<size=40>Vamos livrar nossa cidade de sua presença de uma vez por todas!</size>",
  ui_story_5020_50200602_33_dialog_content = "Samurai? E muitos!!",
  ui_story_5020_50200602_34_dialog_content = "Hmph, os cachorrinhos do general adoram correr em bandos.",
  ui_story_5020_50200602_35_dialog_content = "Seu latido é sempre muito pior do que sua mordida.",
  ui_story_5020_50200602_36_dialog_content = "Às armas, homens!",
  ui_story_5020_50200602_37_dialog_content = "Espere!",
  ui_story_5020_50200602_38_dialog_content = "Há outros atrás deles...",
  ui_story_5020_50200602_39_dialog_content = "Outras?",
  ui_story_5020_50200602_40_dialog_content = "Uau! Vice! PlayerName!",
  ui_story_5020_50200602_41_dialog_content = "Vocês estão bem?",
  ui_story_5020_50200602_42_dialog_content = "Anzu? Momo??",
  ui_story_5020_50200602_43_dialog_content = "Você não deveria estar com os civis?",
  ui_story_5020_50200602_44_dialog_content = "Papai...",
  ui_story_5020_50200602_45_dialog_content = "Silêncio",
  ui_story_5020_50200602_46_dialog_content = "H-Que desprezível!",
  ui_story_5020_50200602_47_dialog_content = "Como você ousa capturar civis inocentes!",
  ui_story_5020_50200602_48_dialog_content = "Eu deveria ser o único a dizer isso!",
  ui_story_5020_50200602_49_dialog_content = "Sua escória Wisp estava planejando fugir com nossos habitantes da cidade como reféns!",
  ui_story_5020_50200602_50_dialog_content = "Essa é a sua primeira transgressão.",
  ui_story_5020_50200602_51_dialog_content = "Reféns? Você está louco?!",
  ui_story_5020_50200602_52_dialog_content = "Onde você estava quando as ruas estavam cheias de fantasmas? E agora você acha que pode interpretar os heróis?!",
  ui_story_5020_50200602_53_dialog_content = "Desobedecer ao general e formar uma facção rebelde em segredo...",
  ui_story_5020_50200602_54_dialog_content = "Essa é a sua segunda transgressão.",
  ui_story_5020_50200602_55_dialog_content = "Você...!",
  ui_story_5020_50200602_56_dialog_content = "E apesar de sua tentativa fracassada de derrubar o governo do general...",
  ui_story_5020_50200602_57_dialog_content = "Você se interessou pelas artes proibidas e convocou fantasmas para a cidade para semear a discórdia.",
  ui_story_5020_50200602_58_dialog_content = "Essa é a sua terceira transgressão.",
  ui_story_5020_50200602_59_dialog_content = "Do que você está falando?!",
  ui_story_5020_50200602_60_dialog_content = "Os Wisps lutaram contra os fantasmas esse tempo todo!",
  ui_story_5020_50200602_61_dialog_content = "Hum...",
  ui_story_5020_50200602_62_dialog_content = "Acho que ele está dizendo tudo isso para o povo da cidade ouvir.",
  ui_story_5020_50200602_63_dialog_content = "Mestre Samurai, isso é verdade?",
  ui_story_5020_50200602_64_dialog_content = "O Wisp realmente convocou os fantasmas?",
  ui_story_5020_50200602_65_dialog_content = "Mas foram eles que nos salvaram agora...",
  ui_story_5020_50200602_66_dialog_content = "Claro, mas quem sabe o que realmente está acontecendo nos bastidores!",
  ui_story_5020_50200602_67_dialog_content = "Isso é verdade. Somos apenas um bando de civis indefesos, o que saberíamos...",
  ui_story_5020_50200602_68_dialog_content = "Eu digo que apenas confiamos naqueles que podem nos proteger melhor...",
  ui_story_5020_50200602_69_dialog_content = "...",
  ui_story_5020_50200602_70_dialog_content = "Achei que os samurais deveriam obedecer a um código de honra...",
  ui_story_5020_50200602_71_dialog_content = "Mas parece que te dei muito crédito.",
  ui_story_5020_50200602_72_dialog_content = "Você honestamente achou que poderia distorcer a verdade a seu favor tão facilmente? Você realmente leva o público a ser tolo?!",
  ui_story_5020_50200602_73_dialog_content = "Eles têm olhos! Existem testemunhas.",
  ui_story_5020_50200602_74_dialog_content = "Que lutou até a morte contra os fantasmas...",
  ui_story_5020_50200602_75_dialog_content = "E quem se escondeu atrás das muralhas do castelo, se encolhendo de medo... A verdade é clara como o dia!",
  ui_story_5020_50200602_76_dialog_content = "Tudo o que eles viram hoje é um bando de traidores quebrando a lei para servir seus próprios interesses.",
  ui_story_5020_50200602_77_dialog_content = "Escolte os civis de volta ao castelo principal! Não podemos arriscar que mais vidas inocentes sejam perdidas na próxima batalha...",
  ui_story_5020_50200602_78_dialog_content = "Cara, outra briga...",
  ui_story_5020_50200602_79_dialog_content = "Vamos, vamos sair daqui...",
  ui_story_5020_50200602_80_dialog_content = "O que há com o mundo...",
  ui_story_5020_50200602_81_dialog_content = "Ei! Temos dois amigos lá, não os machuque!",
  ui_story_5020_50200602_82_dialog_content = "Vice! PlayerName! Vem com a gente, rapidinho...!",
  ui_story_5020_50200602_83_dialog_content = "Parece que as pessoas de Cloud Island estão prestes a lutar entre si... O que devemos fazer?",
  ui_story_5020_50200602_84_dialog_content = "Espere... Eu não acho que as coisas sejam tão simples.",
  ui_story_5020_50200602_85_dialog_content = "Vamos ver como as coisas vão por enquanto...",
  ui_story_5020_50200602_86_dialog_content = "Podemos concordar neste ponto, no mínimo. A vida das pessoas da cidade vem em primeiro lugar.",
  ui_story_5020_50200602_87_dialog_content = "Naturalmente. Preservar a paz em Koufu-jou é nosso dever, afinal.",
  ui_story_5020_50200602_88_dialog_content = "Mesmo? E aqui eu pensei que era o trabalho do Wisp todo esse tempo...",
  ui_story_5020_50200602_89_dialog_content = "Se você é verdadeiramente dedicado a preservar a paz, deponha suas armas e aceite a punição por seus crimes.",
  ui_story_5020_50200602_90_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5020_50200602_91_dialog_content = "As leis do general não se aplicam a mim!",
  ui_story_5020_50200602_92_dialog_content = "Teimoso até o fim... Então prepare-se para colher o que plantou.",
  ui_story_5020_50200602_93_dialog_content = "Hmph! Eu não poderia concordar mais!",
  ui_story_5020_50200602_94_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50200602_95_dialog_content = "?!?",
  ui_story_5020_50200602_96_dialog_content = "!!!",
  ui_story_5020_50200602_97_dialog_content = "Desculpe interromper esta conversa animada...",
  ui_story_5020_50200602_98_dialog_content = "Mas tenho algumas perguntas a fazer antes de vocês se separarem.",
  ui_story_5020_50200602_99_dialog_content = "Senhora Sacerdotisa?!",
  ui_story_5020_50200602_100_dialog_content = "Então você também foi capturado pelos rebeldes!",
  ui_story_5020_50200602_101_dialog_content = "Perdoe minha chegada tardia. Eu juro que vou resgatá-lo a todo custo...",
  ui_story_5020_50200602_102_dialog_content = "Você diz... que os fantasmas foram convocados aqui pelos Wisps, certo?",
  ui_story_5020_50200602_103_dialog_content = "Onde está sua evidência?",
  ui_story_5020_50200602_104_dialog_content = "... Evidência?",
  ui_story_5020_50200602_105_dialog_content = "Quando eles convocaram os fantasmas? Onde? Por qual método?",
  ui_story_5020_50200602_106_dialog_content = "...",
  ui_story_5020_50200602_107_dialog_content = "L-Lady Priestess, sou apenas um humilde soldado. Não estou a par do conhecimento dos meus superiores...",
  ui_story_5020_50200602_108_dialog_content = "Mas fique tranquilo, essas foram as palavras do próprio general.",
  ui_story_5020_50200602_109_dialog_content = "Ah?",
  ui_story_5020_50200602_110_dialog_content = "E você tem certeza de que essas palavras saíram da boca do general? Que não são mentiras ditas por outra pessoa?",
  ui_story_5020_50200602_111_dialog_content = "Sim minha senhora. Isso eu posso garantir.",
  ui_story_5020_50200602_112_dialog_content = "...",
  ui_story_5020_50200602_113_dialog_content = "Ah... entendi.",
  ui_story_5020_50200602_114_dialog_content = "Agradeça ao general por me mostrar exatamente onde estou em tudo isso.",
  ui_story_5020_50200602_115_dialog_content = "Obrigado pela sua compreensão, Senhora Sacerdotisa.",
  ui_story_5020_50200602_116_dialog_content = "Agora, por favor, fique atrás de mim. Não permitirei que ninguém te machuque na batalha que está por vir.",
  ui_story_5020_50200602_117_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50200602_118_dialog_content = "Não será necessário.",
  ui_story_5020_50200602_119_dialog_content = "Este é precisamente o lugar onde eu pertenço.",
  ui_story_5020_50200602_120_dialog_content = "...",
  ui_story_5020_50200602_121_dialog_content = "Senhora Sacerdotisa... Certamente você sabe o que significa ficar em nosso caminho?",
  ui_story_5020_50200602_122_dialog_content = "Não.",
  ui_story_5020_50200602_123_dialog_content = "Estou simplesmente escolhendo não me mexer. O que você faz e para onde vai... não é da minha conta.",
  ui_story_5020_50200602_124_dialog_content = "Ao ficar no meio do nosso campo de batalha, você será considerado nosso inimigo.",
  ui_story_5020_50200602_125_dialog_content = "Em outras palavras... Um inimigo do general.",
  ui_story_5020_50200602_126_dialog_content = "Eu sou uma sacerdotisa. Eu nunca considerei ninguém como meu inimigo.",
  ui_story_5020_50200602_127_dialog_content = "Mas talvez haja aqueles que fariam de mim um inimigo.",
  ui_story_5020_50200602_128_dialog_content = "Você está insinuando que o general é o culpado por tudo isso?",
  ui_story_5020_50200602_129_dialog_content = "De jeito nenhum. Eu finalmente o vejo por quem ele é.",
  ui_story_5020_50200602_130_dialog_content = "Tudo graças a você entregar sua mensagem de que os Wisps foram responsáveis por convocar os fantasmas aqui.",
  ui_story_5020_50200602_131_dialog_content = "...",
  ui_story_5020_50200602_132_dialog_content = "Quando vi os fantasmas no Cloud Pavilion, não entendi.",
  ui_story_5020_50200602_133_dialog_content = "E quando o Cloud Mirror de alguma forma trouxe os fantasmas de volta à vida, eu também não entendi.",
  ui_story_5020_50200602_134_dialog_content = "A contradição entre as palavras do general e suas ações me confundiu... Eu não conseguia entender nada.",
  ui_story_5020_50200602_135_dialog_content = "Mas você e seus homens finalmente me deram a resposta que eu estava procurando.",
  ui_story_5020_50200602_136_dialog_content = "Sacerdotisas e fantasmas se vêem como inimigos há gerações... No entanto, aos olhos do general, somos iguais.",
  ui_story_5020_50200602_137_dialog_content = "Não somos diferentes, pois ambos somos apenas armas a serem usadas.",
  ui_story_5020_50200602_138_dialog_content = "Sempre que a força é necessária, ele usa os fantasmas para esmagar seus inimigos.",
  ui_story_5020_50200602_139_dialog_content = "E sempre que ele precisa conquistar as pessoas, ele envia uma sacerdotisa para combater os próprios fantasmas que ele convoca.",
  ui_story_5020_50200602_140_dialog_content = "Acredito que ainda há muito que você não sabe, Senhora Sacerdotisa.",
  ui_story_5020_50200602_141_dialog_content = "Talvez... E por esta razão, escolhi acreditar apenas no que posso entender.",
  ui_story_5020_50200602_142_dialog_content = "Que é o que aprendi todo esse tempo... Escolho confiar em meu dever como sacerdotisa.",
  ui_story_5020_50200602_143_dialog_content = "Fantasmas, são meus eternos inimigos.",
  ui_story_5020_50200602_144_dialog_content = "...",
  ui_story_5020_50200602_145_dialog_content = "Esta é também a razão pela qual estou onde estou agora.",
  ui_story_5020_50200602_146_dialog_content = "O samurai atrás de você...",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>Nenhum deles está vivo</color>, são eles?",
  ui_story_5020_50200602_148_dialog_content = "...",
  ui_story_5020_50200602_149_dialog_content = "Parece que o tempo das palavras já passou.",
  ui_story_5020_50200602_150_dialog_content = "...",
  ui_story_5020_50200602_151_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50200602_152_dialog_content = "\"Uma ode aos mortos e aos vivos. May essa música guia suas almas de volta aos seus devidos lugares.\"",
  ui_story_5020_50200701_1_dialog_content = "(Enquanto observávamos o samurai fantasma se aproximar, nossos corpos ficaram dormentes pela pura pressão.)",
  ui_story_5020_50200701_2_dialog_content = "(Como uma onda enorme se preparando para cair sobre nós.)",
  ui_story_5020_50200701_3_dialog_content = "(Mas ali, no meio da rua, estava Rinne, sozinho e completamente não afetado pela próxima onda.)",
  ui_story_5020_50200701_4_dialog_content = "(Olhando profundamente nas entranhas do inferno, com o mundo dos vivos atrás dela.)",
  ui_story_5020_50200701_5_dialog_content = "Ai...?",
  ui_story_5020_50200701_6_dialog_content = "Eu pensei que o Wisp não tinha vontade de lutar ao lado de uma sacerdotisa?",
  ui_story_5020_50200701_7_dialog_content = "...",
  ui_story_5020_50200701_8_dialog_content = "Nós odiaríamos ainda mais se deixássemos você nos proteger.",
  ui_story_5020_50200701_9_dialog_content = "Ei, que pena.",
  ui_story_5020_50200701_10_dialog_content = "Se todos vocês forem pegos na batalha, quem mais vai assistir minha... performance?",
  ui_story_5020_50200701_11_dialog_content = "Usando minhas próprias palavras contra mim, hein? Não posso dizer que gosto muito...",
  ui_story_5020_50200701_12_dialog_content = "Foi você quem disse primeiro.",
  ui_story_5020_50200701_13_dialog_content = "Você com certeza sabe guardar rancor... Isso, ou meu discurso foi bem direto.",
  ui_story_5020_50200701_14_dialog_content = "Hum. É verdade!",
  ui_story_5020_50200701_15_dialog_content = "Por ser um inimigo das sacerdotisas, você certamente parece entendê-las ainda mais do que eu.",
  ui_story_5020_50200701_16_dialog_content = "Se você soubesse o que eu sei... Você definitivamente se odiaria por ser um também.",
  ui_story_5020_50200701_17_dialog_content = "Ah... Não seja tão rápido em julgar.",
  ui_story_5020_50200701_18_dialog_content = "Desempenho foi uma maneira dura de colocar isso, mas eu particularmente não me importo.",
  ui_story_5020_50200701_19_dialog_content = "Então você ainda está disposto a ser um fantoche?",
  ui_story_5020_50200701_20_dialog_content = "O que preocupa você e seus homens é apenas quem está puxando as cordas do fantoche.",
  ui_story_5020_50200701_21_dialog_content = "Eu, por outro lado, simplesmente desejo fazer um bom show.",
  ui_story_5020_50200701_22_dialog_content = "Nenhum dos fantoches que vieram antes de você foi capaz de realizar isso.",
  ui_story_5020_50200701_23_dialog_content = "É assim mesmo? Então você acha que eu vou ter sucesso onde todos eles falharam?",
  ui_story_5020_50200701_24_dialog_content = "...",
  ui_story_5020_50200701_25_dialog_content = "É por isso que você sempre esteve tão preocupado em assassinar as sacerdotisas?",
  ui_story_5020_50200701_26_dialog_content = "Amemori me deu muitos problemas, sabe?",
  ui_story_5020_50200701_27_dialog_content = "Amém...",
  ui_story_5020_50200701_28_dialog_content = "Você vai se dirigir a ela como Amemori-sama, entendeu? Mostrar algum respeito!",
  ui_story_5020_50200701_29_dialog_content = "Ah?",
  ui_story_5020_50200701_30_dialog_content = "Mas Amemori sempre falha em suas tentativas de assassinato ... Achei que ela finalmente havia desistido para se salvar de ser uma desgraça.",
  ui_story_5020_50200701_31_dialog_content = "Você...!",
  ui_story_5020_50200701_32_dialog_content = "O que é Amemori para Wisp?",
  ui_story_5020_50200701_33_dialog_content = "Amemori-sama é o discípulo do nosso comandante.",
  ui_story_5020_50200701_34_dialog_content = "Nos anos que se seguiram à prisão de nosso comandante, ela se tornou a líder não oficial do Wisp.",
  ui_story_5020_50200701_35_dialog_content = "Eu vejo... Amemori nunca fui muito de conversar, então não fazia ideia.",
  ui_story_5020_50200701_36_dialog_content = "Seu comandante é conhecido como a Espada do Submundo, correto?",
  ui_story_5020_50200701_37_dialog_content = "Por quê? Você viu ela?",
  ui_story_5020_50200701_38_dialog_content = "De fato. Tivemos uma batalha também.",
  ui_story_5020_50200701_39_dialog_content = "Como alguém que poderia lutar em terreno plano com o general... Ela era terrivelmente poderosa.",
  ui_story_5020_50200701_40_dialog_content = "E para Amemori preencher o seu lugar durante tantos anos... Deve ter sido muito difícil.",
  ui_story_5020_50200701_41_dialog_content = "Amemori-sama é muito parecida com o comandante e cumpriu seus deveres de forma admirável.",
  ui_story_5020_50200701_42_dialog_content = "Em alguns casos... Ela até se saiu melhor que o comandante.",
  ui_story_5020_50200701_43_dialog_content = "É mesmo?",
  ui_story_5020_50200701_44_dialog_content = "Devo dizer que suas habilidades de assassina de sacerdotisas deixam muito a desejar.",
  ui_story_5020_50200701_45_dialog_content = "Isso significa que seu comandante é ainda pior nisso do que Amemori?",
  ui_story_5020_50200701_46_dialog_content = "...",
  ui_story_5020_50200701_47_dialog_content = "Acho que você sabe a resposta para isso.",
  ui_story_5020_50200701_48_dialog_content = "Tente se lembrar da razão pela qual você se tornou uma sacerdotisa em primeiro lugar.",
  ui_story_5020_50200701_49_dialog_content = "...",
  ui_story_5020_50200701_50_dialog_content = "Hehe... entendo.",
  ui_story_5020_50200701_51_dialog_content = "Você não diria que matar sacerdotisas é sua própria versão de uma performance?",
  ui_story_5020_50200701_52_dialog_content = "Não nos compare com você.",
  ui_story_5020_50200701_53_dialog_content = "Mas estamos aqui, lutando juntos, não estamos?",
  ui_story_5020_50200701_54_dialog_content = "Você e seus homens são todos parte do ato agora.",
  ui_story_5020_50200702_1_dialog_content = "Há mais samurais fantasmas se aproximando por trás de nós!",
  ui_story_5020_50200702_2_dialog_content = "Eles estão trazendo reforços!",
  ui_story_5020_50200702_3_dialog_content = "... Entendo.",
  ui_story_5020_50200702_4_dialog_content = "Não vamos durar muito mais neste ritmo, senhor!",
  ui_story_5020_50200702_5_dialog_content = "Quais são seus pedidos?",
  ui_story_5020_50200702_6_dialog_content = "...",
  ui_story_5020_50200702_7_dialog_content = "Receio que esta não seja uma batalha que possamos vencer.",
  ui_story_5020_50200702_8_dialog_content = "Senhor...",
  ui_story_5020_50200702_9_dialog_content = "Então isso é realmente o fim...?",
  ui_story_5020_50200702_10_dialog_content = "Mesmo que seja, não vamos cair sem lutar!",
  ui_story_5020_50200702_11_dialog_content = "Nós... podemos ser capazes de ganhar o <color=#FFB400>próxima luta</color>.",
  ui_story_5020_50200702_12_dialog_content = "A próxima luta?",
  ui_story_5020_50200702_13_dialog_content = "Mas se perdermos aqui e agora, não haverá próxima luta!",
  ui_story_5020_50200702_14_dialog_content = "Quero tentar algo que não fizemos antes.",
  ui_story_5020_50200702_15_dialog_content = "Ei, forasteiro! Venha pra cá!!!",
  ui_story_5020_50200702_16_dialog_content = "N-Não precisa gritar... estou bem ao seu lado...",
  ui_story_5020_50200702_17_dialog_content = "Deixe-me perguntar, você acha que temos alguma chance de escapar daqui?",
  ui_story_5020_50200702_18_dialog_content = "Escapando?",
  ui_story_5020_50200702_19_dialog_content = "Há muitos samurais fantasmas... Nossas chances de escapar são quase nulas.",
  ui_story_5020_50200702_20_dialog_content = "E se o Wisp cobrisse você por trás? Você poderia escapar então?",
  ui_story_5020_50200702_21_dialog_content = "Hã?",
  ui_story_5020_50200702_22_dialog_content = "Ouça. Agora, vocês dois forasteiros precisam sair daqui e levar a sacerdotisa com vocês.",
  ui_story_5020_50200702_23_dialog_content = "Cobriremos sua fuga, mas não conseguiremos segurá-los para sempre.",
  ui_story_5020_50200702_24_dialog_content = "Você precisará usar todo o seu poder assustador para isso.",
  ui_story_5020_50200702_25_dialog_content = "Entender?",
  ui_story_5020_50200702_26_dialog_content = "Eu entendo. É apenas...",
  ui_story_5020_50200702_27_dialog_content = "Por que você está fazendo isso?",
  ui_story_5020_50200702_28_dialog_content = "...",
  ui_story_5020_50200702_29_dialog_content = "Sacerdotisa, mais pessoas deveriam testemunhar essa sua performance.",
  ui_story_5020_50200702_30_dialog_content = "...",
  ui_story_5020_50200702_31_dialog_content = "Tal como está, Wisp está longe de ser forte o suficiente para enfrentar o general.",
  ui_story_5020_50200702_32_dialog_content = "Mas com vocês três... Ainda pode haver esperança.",
  ui_story_5020_50200702_33_dialog_content = "Como já estamos travando uma batalha perdida, prefiro arriscar em vez de esperar o fim chegar.",
  ui_story_5020_50200702_34_dialog_content = "Segure a linha, homens! Não mostre a eles nenhum trimestre!",
  ui_story_5020_50200702_35_dialog_content = "Mas o que vai acontecer com você depois que escaparmos?",
  ui_story_5020_50200702_36_dialog_content = "<size=45>Dê o fora daqui já, garoto!</size>",
  ui_story_5020_50200702_37_dialog_content = "...",
  ui_story_5020_50200702_38_dialog_content = "Vamos, PlayerName.",
  ui_story_5020_50200702_39_dialog_content = "Eles fizeram sua escolha.",
  ui_story_5020_50200702_40_dialog_content = "Você nos deve uma, garoto! Nunca se esqueça!",
  ui_story_5020_50200702_41_dialog_content = "E você vai retribuir.",
  ui_story_5020_50200702_42_dialog_content = "Uau!",
  ui_story_5020_50200702_43_dialog_content = "Isso é um tambor enorme!",
  ui_story_5020_50200702_44_dialog_content = "É enorme!",
  ui_story_5020_50200702_45_dialog_content = "Pra que isso, pai?",
  ui_story_5020_50200702_46_dialog_content = "Ele sinaliza o início do Festival Kasuga.",
  ui_story_5020_50200702_47_dialog_content = "É alto o suficiente para que toda a cidade de Koufu-jou possa ouvi-lo. É assim que todos sabem que o Festival Kasuga começou oficialmente.",
  ui_story_5020_50200702_48_dialog_content = "Nossa!",
  ui_story_5020_50200702_49_dialog_content = "Então o que está fazendo aqui? E onde está o baterista?",
  ui_story_5020_50200702_50_dialog_content = "Provavelmente se escondendo dos fantasmas, imagino?",
  ui_story_5020_50200702_51_dialog_content = "Que pena...",
  ui_story_5020_50200702_52_dialog_content = "Então posso brincar com ele agora?",
  ui_story_5020_50200702_53_dialog_content = "Não agora, filho. Precisamos ficar com os outros.",
  ui_story_5020_50200702_54_dialog_content = "Se ainda estiver aqui amanhã, trarei você aqui para jogar.",
  ui_story_5020_50200702_55_dialog_content = "Oi, Momo!",
  ui_story_5020_50200702_56_dialog_content = "Sim.",
  ui_story_5020_50200702_57_dialog_content = "Este tambor... Não tem mais dono, certo?",
  ui_story_5020_50200702_58_dialog_content = "Me parece assim!",
  ui_story_5020_50200702_59_dialog_content = "Se a levarmos de volta conosco...",
  ui_story_5020_50200702_60_dialog_content = "E instalá-lo ao lado da nossa barraca...",
  ui_story_5020_50200702_61_dialog_content = "Poderíamos angariar ainda mais negócios para nós mesmos!",
  ui_story_5020_50200702_62_dialog_content = "<size=40>Agarre-os!</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>Rapidamente!</size>",
  ui_story_5020_50200702_64_dialog_content = "Hã? O que foi?",
  ui_story_5020_50200702_65_dialog_content = "Parece que...",
  ui_story_5020_50200702_66_dialog_content = "Alguém está correndo em nossa direção agora!",
  ui_story_5020_50200702_67_dialog_content = "Anzu! Momo! Ajuda!",
  ui_story_5020_50200702_68_dialog_content = "Ai...",
  ui_story_5020_50200702_69_dialog_content = "Eita...",
  ui_story_5020_50200702_70_dialog_content = "S-Desculpe, eu não pisei no freio a tempo.",
  ui_story_5020_50200702_71_dialog_content = "De qualquer forma, estamos em apuros! Um bando de samurais está tentando nos matar!",
  ui_story_5020_50200702_72_dialog_content = "Samurai? Matar você?",
  ui_story_5020_50200702_73_dialog_content = "O que é que você fez, PlayerName?",
  ui_story_5020_50200702_74_dialog_content = "Não há tempo para explicar! Você sabe onde podemos nos esconder por enquanto?",
  ui_story_5020_50200702_75_dialog_content = "Pressa! Eles estão ganhando de nós!",
  ui_story_5020_50200702_76_dialog_content = "Um esconderijo? Isso tudo é tão repentino!",
  ui_story_5020_50200702_77_dialog_content = "Bom, já que você perguntou...",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>Hum...</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName, mova-se...",
  ui_story_5020_50200702_81_dialog_content = "Aqui não tem espaço...",
  ui_story_5020_50200702_82_dialog_content = "Eu gostaria, mas... é completamente redondo aqui dentro!",
  ui_story_5020_50200702_83_dialog_content = "Meu corpo continua deslizando para baixo!",
  ui_story_5020_50200702_84_dialog_content = "Suspiro... É para você sugerir um esconderijo ruim como o interior de um tambor...",
  ui_story_5020_50200702_85_dialog_content = "Que? Esta foi a ideia de Anzu e Momo! Eu não tive nada a ver com isso!",
  ui_story_5020_50200702_86_dialog_content = "Heh... Infelizmente, parece que esta foi a nossa melhor escolha dadas as nossas circunstâncias.",
  ui_story_5020_50200702_87_dialog_content = "Nós vamos ter que aturar isso por enquanto.",
  ui_story_5020_50200702_88_dialog_content = "Hum...",
  ui_story_5020_50200702_89_dialog_content = "Shh, eles estão aqui.",
  ui_story_5020_50200702_90_dialog_content = "Você aí! Você viu três pessoas de aparência frenética correndo por aqui agora mesmo?",
  ui_story_5020_50200702_91_dialog_content = "Uma delas estava usando um traje vermelho de sacerdotisa. Você não poderia ter perdido ela.",
  ui_story_5020_50200702_92_dialog_content = "Huh? Por que especificamente três pessoas?",
  ui_story_5020_50200702_93_dialog_content = "Eu vi alguém vestindo roupas azuis. Isso conta?",
  ui_story_5020_50200702_94_dialog_content = "... Apenas me diga se você os viu ou não.",
  ui_story_5020_50200702_95_dialog_content = "Não os vi!",
  ui_story_5020_50200702_96_dialog_content = "Tudo bem, entendi.",
  ui_story_5020_50200702_97_dialog_content = "(Ufa... Ele comprou...)",
  ui_story_5020_50200702_98_dialog_content = "Embora... O que vocês dois estão fazendo aqui, afinal?",
  ui_story_5020_50200702_99_dialog_content = "Por que você não segue os outros?",
  ui_story_5020_50200702_100_dialog_content = "Ah, bem... Você vê... Uh...",
  ui_story_5020_50200702_101_dialog_content = "É por causa desse tambor aqui...",
  ui_story_5020_50200702_102_dialog_content = "Tambor?",
  ui_story_5020_50200702_103_dialog_content = "(!!!)",
  ui_story_5020_50200702_104_dialog_content = "E o tambor?",
  ui_story_5020_50200702_105_dialog_content = "(Estamos ferrados...)",
  ui_story_5020_50200702_106_dialog_content = "Sim! Este tambor!",
  ui_story_5020_50200702_107_dialog_content = "Nós somos bateristas, você vê!",
  ui_story_5020_50200702_108_dialog_content = "Th-Isso mesmo! Estamos nos preparando para anunciar o início do Festival Kasuga!",
  ui_story_5020_50200702_109_dialog_content = "Bateristas?",
  ui_story_5020_50200702_110_dialog_content = "Mas vocês dois são tão pequenos... Vocês são realmente talhados para tocar bateria?",
  ui_story_5020_50200702_111_dialog_content = "Podemos ser pequenos, mas...",
  ui_story_5020_50200702_112_dialog_content = "Nós trabalhamos juntos!",
  ui_story_5020_50200702_113_dialog_content = "Trabalhar juntos?",
  ui_story_5020_50200702_114_dialog_content = "Parece interessante... Por que você não nos dá uma pequena demonstração?",
  ui_story_5020_50200702_115_dialog_content = "S... Sério...?",
  ui_story_5020_50200702_116_dialog_content = "M-Talvez outra hora, meu bom senhor! Nós realmente deveríamos estar alcançando os outros...",
  ui_story_5020_50200702_117_dialog_content = "Não há nada com que se preocupar. Mais samurais estão a caminho, então estamos perfeitamente seguros aqui.",
  ui_story_5020_50200702_118_dialog_content = "Vamos lá, vamos ver o quão bem você pode tocar bateria.",
  ui_story_5020_50200702_119_dialog_content = "(...)",
  ui_story_5020_50200702_120_dialog_content = "(... Anzu? Momo? Você realmente não vai...)",
  ui_story_5020_50200702_121_dialog_content = "<size=30>Perdoe-nos, PlayerName...</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>Apenas tente aguentar por enquanto...</size>",
  ui_story_5020_50200702_123_dialog_content = "(E-Espere! Tem que haver outro...)",
  ui_story_5020_50200702_124_dialog_content = "Ei!",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>Uau!!!</size></color>",
  ui_story_5020_50200702_126_dialog_content = "Ei!",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>Uau!!!</size></color>",
  ui_story_5020_50200702_128_dialog_content = "Oh o! Vocês dois mostram alguma promessa, afinal!",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>Haha... Ha...</anim>",
  ui_story_5020_50200702_130_dialog_content = "Você é muito gentil, senhor...",
  ui_story_5020_50200702_131_dialog_content = "O general disse que o Festival Kasuga deve continuar sem incidentes... Muito bem, vocês dois. Traga seu tambor de volta ao castelo principal, para que você possa continuar com seus preparativos.",
  ui_story_5020_50200702_132_dialog_content = "Além disso, se acontecer de você ver esses três que mencionei antes, apenas nos dê um grito.",
  ui_story_5020_50200702_133_dialog_content = "Maravilha!",
  ui_story_5020_50200702_134_dialog_content = "Hum...",
  ui_story_5020_50200702_135_dialog_content = "PlayerName...",
  ui_story_5020_50200702_136_dialog_content = "Vocês três estão bem...?",
  ui_story_5020_50200702_137_dialog_content = "<size=45>O que você acha?!</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>Nossos tímpanos estão quase estourados!!</size>",
  ui_story_5020_50200702_139_dialog_content = "Sua audição parece bem...",
  ui_story_5020_50200702_140_dialog_content = "Estou usando meus poderes! Minhas orelhas estão completamente baleadas!",
  ui_story_5020_50200702_141_dialog_content = "Você está dizendo alguma coisa, PlayerName? Eu posso ver seus lábios se movendo, mas...",
  ui_story_5020_50200702_142_dialog_content = "Nós lamentamos! Sentimos muito, muito mesmo!!!",
  ui_story_5020_50200702_143_dialog_content = "Ufa...",
  ui_story_5020_50200702_144_dialog_content = "Esqueça isso. Não havia outra escolha.",
  ui_story_5020_50200702_145_dialog_content = "Shiu!",
  ui_story_5020_50200702_146_dialog_content = "Mais samurais estão chegando!",
  ui_story_5020_50200702_147_dialog_content = "Ele simplesmente não para, não é...",
  ui_story_5020_50200702_148_dialog_content = "O que vamos fazer agora?",
  ui_story_5020_50200702_149_dialog_content = "Você terá que continuar se escondendo dentro do tambor!",
  ui_story_5020_50200702_150_dialog_content = "Anzu e eu vamos levá-lo a algum lugar com menos pessoas, para que você tenha mais chances de escapar!",
  ui_story_5020_50200702_151_dialog_content = "Parece uma boa ideia... eu acho.",
  ui_story_5020_50200702_152_dialog_content = "Isso mesmo!",
  ui_story_5020_50200702_153_dialog_content = "A gente sempre dá um jeito!",
  ui_story_5020_50200702_154_dialog_content = "Mas ouça...",
  ui_story_5020_50200702_155_dialog_content = "Chega de batucar! Quero dizer!",
  ui_story_5020_50200702_156_dialog_content = "Entendido! Chega de batucar!",
  ui_story_5020_50200702_157_dialog_content = "(O que Wisp esperava conseguir nos ajudando a escapar?)",
  ui_story_5020_50200702_158_dialog_content = "(Eu me pergunto como eles estão aguentando...)",
  ui_story_5020_50200702_159_dialog_content = "Nós nos rendemos!",
  ui_story_5020_50200702_160_dialog_content = "... Ei, pare com isso já! Eu disse que nos rendemos!",
  ui_story_5020_50200702_161_dialog_content = "O general estava certo o tempo todo! Finalmente vemos o erro de nossos caminhos!",
  ui_story_5020_50200702_162_dialog_content = "Os Wisp são culpados! Aceitamos nosso castigo!",
  ui_story_5020_50200702_163_dialog_content = "...",
  ui_story_5020_50200702_164_dialog_content = "O grande samurai, como cachorrinho do general... Não! Quero dizer, a lâmina mais afiada do general!",
  ui_story_5020_50200702_165_dialog_content = "Você vai agora lidar com as coisas de acordo com a lei... Certo?",
  ui_story_5020_50200702_166_dialog_content = "Diga-me, por que você ajudou a sacerdotisa a escapar?",
  ui_story_5020_50200702_167_dialog_content = "Ajude ela? Ela fugiu sozinha! Não tivemos nada a ver com isso.",
  ui_story_5020_50200702_168_dialog_content = "O inimigo do seu inimigo pode não ser seu amigo.",
  ui_story_5020_50200702_169_dialog_content = "O general é seu pai adotivo. Não há muito que ela possa fazer.",
  ui_story_5020_50200702_170_dialog_content = "Isso é bom para nós! Agora vamos acabar com isso, para que possamos finalmente desfrutar de um pouco de paz!",
  ui_story_5020_50200702_171_dialog_content = "...",
  ui_story_5020_50200702_172_dialog_content = "Amarre-os e traga-os para o castelo principal.",
  ui_story_5020_50200801_1_dialog_content = "Escolha uma flor vermelha para a senhora...",
  ui_story_5020_50200801_2_dialog_content = "Pétalas caem como neve em um pedaço de jade.",
  ui_story_5020_50200801_3_dialog_content = "O que você vai fazer a seguir, mestre?",
  ui_story_5020_50200801_4_dialog_content = "Oh? Ainda me segue, não é?",
  ui_story_5020_50200801_5_dialog_content = "Estou surpreso que você esteja acompanhando todo esse tempo.",
  ui_story_5020_50200801_6_dialog_content = "Por favor, mestre. Deixe-me ajudá-lo.",
  ui_story_5020_50200801_7_dialog_content = "Me ajude? Com o que? Eu não preciso de ajuda.",
  ui_story_5020_50200801_8_dialog_content = "Só tenho um assunto pessoal para tratar.",
  ui_story_5020_50200801_9_dialog_content = "Irei encontrá-lo assim que terminar. Seja uma boa menina.",
  ui_story_5020_50200801_10_dialog_content = "...",
  ui_story_5020_50200801_11_dialog_content = "Mestre... Quando você saiu sozinho, eu...",
  ui_story_5020_50200801_12_dialog_content = "Prometi a mim mesma que não deixaria isso acontecer novamente.",
  ui_story_5020_50200801_13_dialog_content = "Cresci muito na sua ausência, mestre. Posso ajudá-lo a carregar seu fardo.",
  ui_story_5020_50200801_14_dialog_content = "Não só eu... Mas todo o Wisp também.",
  ui_story_5020_50200801_15_dialog_content = "Quantos anos se passaram...?",
  ui_story_5020_50200801_16_dialog_content = "Dez anos.",
  ui_story_5020_50200801_17_dialog_content = "Dez anos?! Hahaha! Realmente faz um tempo, hein?",
  ui_story_5020_50200801_18_dialog_content = "Lembro-me de como você era naquela época... menor que minha espada. Sempre tive medo de que uma brisa te levasse para longe.",
  ui_story_5020_50200801_19_dialog_content = "Agora que você cresceu e está mais habilidoso, não posso me livrar de você, mesmo que eu queira.",
  ui_story_5020_50200801_20_dialog_content = "Mestre...",
  ui_story_5020_50200801_21_dialog_content = "Infelizmente, parece que aquela sua cabecinha não ficou muito mais esperta.",
  ui_story_5020_50200801_22_dialog_content = "\"Ombro meu fardo\"... O que você acha que isso significa, exatamente?",
  ui_story_5020_50200801_23_dialog_content = "Para... Para ajudá-lo a realizar o que você sempre quis realizar.",
  ui_story_5020_50200801_24_dialog_content = "Para devolver Koufu-jou ao seu legítimo governante.",
  ui_story_5020_50200801_25_dialog_content = "Hahahaha! Eu vejo!",
  ui_story_5020_50200801_26_dialog_content = "Então foi por isso que você veio me resgatar?",
  ui_story_5020_50200801_27_dialog_content = "Você quer que eu acabe com tudo isso, certo?",
  ui_story_5020_50200801_28_dialog_content = "Esperando que eu possa levar você e os outros a uma gloriosa batalha contra o general, empunhar minha espada e reivindicar o castelo... É isso?",
  ui_story_5020_50200801_29_dialog_content = "Com sua ajuda, mestre, nós...",
  ui_story_5020_50200801_30_dialog_content = "Chega.",
  ui_story_5020_50200801_31_dialog_content = "Sua visão de seu mestre é muito irreal, minha garota.",
  ui_story_5020_50200801_32_dialog_content = "Não sou nenhum santo... Longe disso, na verdade.",
  ui_story_5020_50200801_33_dialog_content = "Não me prenda com suas esperanças e sonhos e me faça representar sua ideia de \"justiça\".",
  ui_story_5020_50200801_34_dialog_content = "...",
  ui_story_5020_50200801_35_dialog_content = "Mas mestre, tudo o que você fez...",
  ui_story_5020_50200801_36_dialog_content = "Sim, tenho me oposto ao general todo esse tempo.",
  ui_story_5020_50200801_37_dialog_content = "Mas a verdade é que eu tenho feito tudo por mim mesma. Não pelo povo, não pela justiça, ou por quaisquer razões nobres que você possa acreditar.",
  ui_story_5020_50200801_38_dialog_content = "Eu nunca poderia carregar esse tipo de peso em meus ombros.",
  ui_story_5020_50200801_39_dialog_content = "...",
  ui_story_5020_50200801_40_dialog_content = "Honestamente, sempre achei que não era digno de ser o comandante do Wisp.",
  ui_story_5020_50200801_41_dialog_content = "Quando fui escolhido para liderar, foi apenas porque ninguém era mais forte do que eu.",
  ui_story_5020_50200801_42_dialog_content = "Mas essa responsabilidade não me deu nada além de dores de cabeça e exaustão.",
  ui_story_5020_50200801_43_dialog_content = "Não... Acho que preferiria entrar no castelo principal sozinho.",
  ui_story_5020_50200801_44_dialog_content = "Vendo as forças do castelo lutando para se defender... Mesmo que nenhum deles pudesse esperar me deter.",
  ui_story_5020_50200801_45_dialog_content = "Fazendo o que eu quiser... Sim, isso é o que eu deveria fazer.",
  ui_story_5020_50200801_46_dialog_content = "E você, Amemori?",
  ui_story_5020_50200801_47_dialog_content = "O que exatamente você quer fazer?",
  ui_story_5020_50200801_48_dialog_content = "Eu...",
  ui_story_5020_50200801_49_dialog_content = "Nunca pensei nisso, né?",
  ui_story_5020_50200801_50_dialog_content = "...",
  ui_story_5020_50200801_51_dialog_content = "Eu sempre quis ser como você, mestre.",
  ui_story_5020_50200801_52_dialog_content = "Ah?",
  ui_story_5020_50200801_53_dialog_content = "Todos em Wisp me trataram como seu sucessor.",
  ui_story_5020_50200801_54_dialog_content = "Eu tenho feito o que eles esperavam de mim todo esse tempo, tentando preencher o espaço que você deixou para trás.",
  ui_story_5020_50200801_55_dialog_content = "Mas a responsabilidade é muito grande para mim... Não importa o quanto eu tente, eu nunca poderia tomar o seu lugar, mestre.",
  ui_story_5020_50200801_56_dialog_content = "...",
  ui_story_5020_50200801_57_dialog_content = "É por isso que... quando você finalmente foi libertado do Solo Selado, eu senti uma onda de alívio.",
  ui_story_5020_50200801_58_dialog_content = "Achei que finalmente tinha cumprido minha missão.",
  ui_story_5020_50200801_59_dialog_content = "Oh, minha garota boba... Você é mais do que apenas minha substituta.",
  ui_story_5020_50200801_60_dialog_content = "Wisp não conhecia nada além de problemas e derrotas sob meu comando... Mas você os liderou nos últimos dez anos.",
  ui_story_5020_50200801_61_dialog_content = "Você fez um trabalho muito melhor do que eu jamais poderia esperar fazer.",
  ui_story_5020_50200801_62_dialog_content = "H-como pode ser isso...",
  ui_story_5020_50200801_63_dialog_content = "Sua próxima missão... é encontrar o que você quer fazer por si mesmo.",
  ui_story_5020_50200801_64_dialog_content = "O que é algo que não posso te ensinar.",
  ui_story_5020_50200801_65_dialog_content = "...",
  ui_story_5020_50200801_66_dialog_content = "Tudo bem agora. Não fique aí parecendo um tolo. Você é meu discípulo, afinal.",
  ui_story_5020_50200801_67_dialog_content = "Vá em frente e cuide de seus próprios assuntos.",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_69_dialog_content = "...",
  ui_story_5020_50200801_70_dialog_content = "Por que você ainda está me seguindo?",
  ui_story_5020_50200801_71_dialog_content = "Eu ainda não decidi o que eu quero fazer... Então eu decidi te seguir por enquanto, mestre.",
  ui_story_5020_50200801_72_dialog_content = "Você...!",
  ui_story_5020_50200801_73_dialog_content = "*Suspiro* ... Tudo bem. Venha, então.",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_75_dialog_content = "Escolha uma flor vermelha para a senhora...",
  ui_story_5020_50200801_76_dialog_content = "Pétalas...",
  ui_story_5020_50200801_77_dialog_content = "Pétalas caem como neve em um pedaço de jade.",
  ui_story_5020_50200801_78_dialog_content = "...",
  ui_story_5020_50200801_79_dialog_content = "Acabei de me lembrar... Você sempre teve uma bela voz para cantar, desde pequena.",
  ui_story_5020_50200801_80_dialog_content = "E parece ter melhorado com o passar dos anos.",
  ui_story_5020_50200801_81_dialog_content = "Th-Obrigado, mestre.",
  ui_story_5020_50200801_82_dialog_content = "Quanto à outra... ela não conseguia nem lembrar a letra dessa música, muito menos cantá-la bem.",
  ui_story_5020_50200801_83_dialog_content = "... Ela esqueceu muito mais desde então.",
  ui_story_5020_50200801_84_dialog_content = "Eu sabia. Afinal, ela sempre foi melhor em aprender com os punhos. Quando se tratava de lutar, ela era um gênio por si só.",
  ui_story_5020_50200801_85_dialog_content = "Você nunca poderia vencê-la quando criança... Mas e agora?",
  ui_story_5020_50200801_86_dialog_content = "...",
  ui_story_5020_50200801_87_dialog_content = "Bem, já que você insiste em me seguir, tenho um trabalho para você.",
  ui_story_5020_50200801_88_dialog_content = "Ajude-me a puxar esta corda.",
  ui_story_5020_50200801_89_dialog_content = "M-Mas mestre, isso pertence a outra pessoa...",
  ui_story_5020_50200801_90_dialog_content = "Eu sei que! Eu só estou pegando emprestado um pouco, não é como se eu fosse ficar com ele para sempre!",
  ui_story_5020_50200801_91_dialog_content = "Vamos, juntos agora!",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>Swish... Baque!</color>",
  ui_story_5020_50200801_93_dialog_content = "Perfeito, agora me ajude a carregar este pacote de corda.",
  ui_story_5020_50200801_94_dialog_content = "... Entendido.",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_96_dialog_content = "Aliás...",
  ui_story_5020_50200801_97_dialog_content = "Depois que eu desapareci...",
  ui_story_5020_50200801_98_dialog_content = "Por acaso o general realizou um funeral?",
  ui_story_5020_50200801_99_dialog_content = "Um funeral?",
  ui_story_5020_50200801_100_dialog_content = "não acredito assim...",
  ui_story_5020_50200801_101_dialog_content = "Oh, eu vejo.",
  ui_story_5020_50200801_102_dialog_content = "Para quem teria sido este funeral, mestre?",
  ui_story_5020_50200801_103_dialog_content = "...",
  ui_story_5020_50200801_104_dialog_content = "O nome dela era Tsuki. Você ainda se lembra dela?",
  ui_story_5020_50200801_105_dialog_content = "Foi ela quem jogou vocês dois em cima de mim todos esses anos atrás.",
  ui_story_5020_50200801_106_dialog_content = "Sim, eu me lembro.",
  ui_story_5020_50200801_107_dialog_content = "Acredito que ela era sua irmã mais velha... Não era, mestre?",
  ui_story_5020_50200801_108_dialog_content = "Ela cuidou de nós quando éramos muito pequenos.",
  ui_story_5020_50200801_109_dialog_content = "Lembro que ela era uma pessoa gentil e carinhosa.",
  ui_story_5020_50200801_110_dialog_content = "Sim... Ela com certeza era.",
  ui_story_5020_50200801_111_dialog_content = "Como ela faleceu?",
  ui_story_5020_50200801_112_dialog_content = "...",
  ui_story_5020_50200801_113_dialog_content = "Eu matei ela.",
  ui_story_5020_50200801_114_dialog_content = "!!!",
  ui_story_5020_50200801_115_dialog_content = "Porque ela era uma sacerdotisa.",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_118_dialog_content = "Desde o início, eu continuei dizendo a ela para não se tornar uma sacerdotisa.",
  ui_story_5020_50200801_119_dialog_content = "Mas Tsuki nunca me ouviu. Ela era mais velha e sempre pensou que era mais esperta do que sua irmã mais nova.",
  ui_story_5020_50200801_120_dialog_content = "Ela disse que uma sacerdotisa poderia trazer paz a toda a Ilha das Nuvens.",
  ui_story_5020_50200801_121_dialog_content = "Mas eu sempre ria dela, dizendo que as sacerdotisas eram apenas ferramentas para o general... Que a única maneira de trazer a paz para a Ilha das Nuvens era com lâminas.",
  ui_story_5020_50200801_122_dialog_content = "No final, nenhum de nós conseguiu convencer o outro, e assim escolhemos caminhos diferentes que cada um acreditava ser o certo.",
  ui_story_5020_50200801_123_dialog_content = "Ela foi para a ilha principal para se submeter a um treinamento formal, e eu... perambulei por aí, matando incontáveis fantasmas para aprimorar minhas habilidades.",
  ui_story_5020_50200801_124_dialog_content = "Alguns anos depois, ela se tornou a sacerdotisa do general, e eu me tornei a Espada do Submundo.",
  ui_story_5020_50200801_125_dialog_content = "...",
  ui_story_5020_50200801_126_dialog_content = "A próxima vez que nos vimos, ela não perdeu tempo em relembrar o passado. Tudo o que ela disse foi que queria ver quem era melhor em matar fantasmas.",
  ui_story_5020_50200801_127_dialog_content = "Mal pude conter minha risada e aceitei de bom grado seu desafio.",
  ui_story_5020_50200801_128_dialog_content = "A última coisa que eu esperava era vê-la sacar sua lâmina com confiança.",
  ui_story_5020_50200801_129_dialog_content = "Era a espada mais bonita que eu já tinha visto. Exalava um poder que queimava como o sol... Como se tivesse sido feito para cortar demônios e trevas.",
  ui_story_5020_50200801_130_dialog_content = "Escusado será dizer que perdi espetacularmente. Heh... Eu lembro que Tsuki estava tão orgulhoso de ganhar. Ela estava dançando ao meu redor e dizendo—",
  ui_story_5020_50200801_131_dialog_content = "\"Eu te disse, uma sacerdotisa pode trazer paz para a Ilha das Nuvens!\"",
  ui_story_5020_50200801_132_dialog_content = "Naquela época... eu realmente acreditava que ela poderia fazer isso.",
  ui_story_5020_50200801_133_dialog_content = "Incrível... Alguém foi capaz de derrotar até você, mestre...",
  ui_story_5020_50200801_134_dialog_content = "Se não fosse por essa espada, ela nunca poderia me vencer!",
  ui_story_5020_50200801_135_dialog_content = "Fatia do Céu, a espada que mata fantasmas... Até uma criança de três anos pode cortar a maioria dos fantasmas com essa lâmina na mão, sem falar na minha irmã.",
  ui_story_5020_50200801_136_dialog_content = "Infelizmente, essa foi a última vez que coloquei os olhos no Slice of Heaven.",
  ui_story_5020_50200801_137_dialog_content = "Depois disso, seu foco mudou de expulsar fantasmas. Tornou-se apenas um meio para um fim.",
  ui_story_5020_50200801_138_dialog_content = "...",
  ui_story_5020_50200801_139_dialog_content = "Ela começou a usar o Cloud Mirror para fazer parecer que estava expulsando os fantasmas.",
  ui_story_5020_50200801_140_dialog_content = "Mas eu sabia que era tudo apenas um ato.",
  ui_story_5020_50200801_141_dialog_content = "Dez anos atrás, durante o Festival Kasuga... Ela usou o Espelho das Nuvens para invocar fantasmas, apenas para colocá-los na frente das pessoas. Tsuki realmente parecia gostar de sua pequena performance.",
  ui_story_5020_50200801_142_dialog_content = "Eu vi através dele... Infelizmente, ninguém mais conseguiu fazer o mesmo. Todos eles se apaixonaram pelo ato dela.",
  ui_story_5020_50200801_143_dialog_content = "Todos eles acreditavam que a sacerdotisa traria paz a Koufu-jou, e que o general que a treinou era digno de governar sobre todos nós.",
  ui_story_5020_50200801_144_dialog_content = "Naquele momento, percebi que nosso maior obstáculo para realizar nossos sonhos de paz... era o outro.",
  ui_story_5020_50200801_145_dialog_content = "Os membros do Wisp começaram a baixar a guarda, e alguns até perderam a vontade de resistir completamente. Eles escolheram se tornar súditos dóceis e obedientes do general.",
  ui_story_5020_50200801_146_dialog_content = "Comparado com a repressão forçada... Este foi um destino muito mais aterrorizante.",
  ui_story_5020_50200801_147_dialog_content = "Por quê?",
  ui_story_5020_50200801_148_dialog_content = "Se o general matasse dez dos nossos, seus filhos herdariam seu ódio por ele e sustentariam a resistência no futuro.",
  ui_story_5020_50200801_149_dialog_content = "Mas depois de serem enganados pela sacerdotisa, eles esqueceram todo o seu ódio e o que era deles por direito... E assim, eles se tornaram o gado domesticado do general.",
  ui_story_5020_50200801_150_dialog_content = "Wisp não tem medo da derrota. Nunca vencemos verdadeiramente nenhuma batalha, mas também nunca perdemos a vontade de resistir.",
  ui_story_5020_50200801_151_dialog_content = "O que mais tememos é complacência... assimilação... e uma mudança de coração.",
  ui_story_5020_50200801_152_dialog_content = "Pouco a pouco, essas coisas reduzem a razão de um guerreiro lutar.",
  ui_story_5020_50200801_153_dialog_content = "E quando isso acontecer, ninguém se lembrará de quem éramos, ou do que realizamos...",
  ui_story_5020_50200801_154_dialog_content = "Esta ilha ainda pode ser conhecida como Cloud Island, mas perdeu toda a aparência do que era há muito tempo.",
  ui_story_5020_50200801_155_dialog_content = "...",
  ui_story_5020_50200801_156_dialog_content = "E essa... é a razão pela qual digo a todos, inclusive a você, que a sacerdotisa deve morrer.",
  ui_story_5020_50200801_157_dialog_content = "O general nunca pode realmente nos derrotar, mas a sacerdotisa é uma história diferente.",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_159_dialog_content = "Tudo bem... aqui está.",
  ui_story_5020_50200801_160_dialog_content = "Me dê uma mão. Basta pegar todos os <color=#FFB400>vinho</color> aqui.",
  ui_story_5020_50200801_161_dialog_content = "Amarre todas as garrafas com essa corda...",
  ui_story_5020_50200801_162_dialog_content = "... Mas mestre, isso é definitivamente...",
  ui_story_5020_50200801_163_dialog_content = "Ah, dá um descanso, sim? Por acaso conheço o dono desta loja! Voltamos anos e anos!",
  ui_story_5020_50200801_164_dialog_content = "Deixei um bilhete na mesa dizendo que pagaremos mais tarde.",
  ui_story_5020_50200801_165_dialog_content = "Agora vamos nos mexer.",
  ui_story_5020_50200801_166_dialog_content = "...",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>Hmm...</color>",
  ui_story_5020_50200801_168_dialog_content = "Ufa...",
  ui_story_5020_50200801_169_dialog_content = "Isso deve resolver! Bonito e apertado!",
  ui_story_5020_50200801_170_dialog_content = "Agora pegue todos eles e siga-me.",
  ui_story_5020_50200801_171_dialog_content = "Deixe-me saber se eles são muito pesados para você. Posso ajudá-lo a carregá-los.",
  ui_story_5020_50200801_172_dialog_content = "Eu... eu posso lidar com isso.",
  ui_story_5020_50200801_173_dialog_content = "Tem certeza que? Só vai ficar mais difícil a partir daqui.",
  ui_story_5020_50200801_174_dialog_content = "Onde estamos indo?",
  ui_story_5020_50200801_175_dialog_content = "Ao <color=#FFB400>castelo principal</color>.",
  ui_story_5020_50200801_176_dialog_content = "O castelo principal?!",
  ui_story_5020_50200801_177_dialog_content = "Sim.",
  ui_story_5020_50200801_178_dialog_content = "Já esteve no telhado do castelo? A vista é incrível... Um lugar perfeito para se sentar para tomar uma bebida.",
  ui_story_5020_50200801_179_dialog_content = "Invadir um castelo não deve ser um grande problema para meu querido discípulo, certo?",
  ui_story_5020_50200801_180_dialog_content = "Claro...",
  ui_story_5020_50200801_181_dialog_content = "Em qualquer lugar que meu mestre possa ir, eu também posso ir.",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_183_dialog_content = "De volta aqui de novo, hein?",
  ui_story_5020_50200801_184_dialog_content = "Dez anos atrás, eu andava por essa mesma estrada, vendo o castelo ficar cada vez maior à medida que me aproximava dele.",
  ui_story_5020_50200801_185_dialog_content = "É tão alto que cobre o sol e a lua, e faz as pessoas se perguntarem se conseguiriam encontrar a saída assim que pisassem nele.",
  ui_story_5020_50200801_186_dialog_content = "Mas você nunca quis encontrar o seu caminho naquela época, certo?",
  ui_story_5020_50200801_187_dialog_content = "Você até nos deixou com o jade Rebellion e Ryojin.",
  ui_story_5020_50200801_188_dialog_content = "Heh... Você está absolutamente certo.",
  ui_story_5020_50200801_189_dialog_content = "O jade da Rebelião e Ryojin são valiosos demais para arriscar cair nas mãos do general.",
  ui_story_5020_50200801_190_dialog_content = "Mesmo sabendo dos riscos... Ainda assim escolheu matá-la?",
  ui_story_5020_50200801_191_dialog_content = "Sua própria irmã...",
  ui_story_5020_50200801_192_dialog_content = "Isso mesmo... Minha própria irmã.",
  ui_story_5020_50200801_193_dialog_content = "Acho que nós dois sabíamos que isso aconteceria naquele dia.",
  ui_story_5020_50200801_194_dialog_content = "Eu estava preparado para morrer, e ela estava pronta para morrer pela minha mão.",
  ui_story_5020_50200801_195_dialog_content = "Eu pensei que nós dois iríamos encontrar nossos fins no Pavilhão das Nuvens naquele dia, ambos morrendo por nossa busca pela paz na Ilha das Nuvens.",
  ui_story_5020_50200801_196_dialog_content = "Mas inesperadamente...",
  ui_story_5020_50200801_197_dialog_content = "Ela não queria que eu morresse...",
  ui_story_5020_50200801_198_dialog_content = "E eu também não queria mais morrer.",
  ui_story_5020_50200801_199_dialog_content = "?!",
  ui_story_5020_50200801_200_dialog_content = "Há mais uma pessoa que devo levar comigo.",
  ui_story_5020_50200801_201_dialog_content = "...",
  ui_story_5020_50200801_202_dialog_content = "É... General Fujikumo?",
  ui_story_5020_50200801_203_dialog_content = "Claro que é. Quem mais poderia ser?",
  ui_story_5020_50200801_204_dialog_content = "No dia em que Tsuki morreu, eu finalmente percebi o que a fez mudar tanto.",
  ui_story_5020_50200801_205_dialog_content = "Ela colocou sua fé em uma pessoa e confiou nelas até seu último suspiro.",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_207_dialog_content = "Eu queria acreditar que ela havia enlouquecido ou foi forçada a cumprir seus deveres...",
  ui_story_5020_50200801_208_dialog_content = "Mas... ela estava perfeitamente sã e disposta a deixar Fujikumo enganá-la.",
  ui_story_5020_50200801_209_dialog_content = "Mesmo sabendo que suas ações estavam erradas, ela continuou acreditando nele e em suas mentiras.",
  ui_story_5020_50200801_210_dialog_content = "Uma pessoa... tinha feito refém o senso de certo e errado da minha irmã.",
  ui_story_5020_50200801_211_dialog_content = "Eu odeio isso.",
  ui_story_5020_50200801_212_dialog_content = "Eu odeio que Fujikumo se aproveitou do amor de Tsuki.",
  ui_story_5020_50200801_213_dialog_content = "Acho que já mencionei isso antes. Eu sempre faço o que eu quero.",
  ui_story_5020_50200801_214_dialog_content = "Entre ele e eu, pelo menos um de nós morrendo.",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_216_dialog_content = "Estamos aqui.",
  ui_story_5020_50200801_217_dialog_content = "Você deve ser muito bom em escalar agora, certo?",
  ui_story_5020_50200801_218_dialog_content = "Sim.",
  ui_story_5020_50200801_219_dialog_content = "Tudo bem! Vamos ver quem chega ao topo primeiro!",
  ui_story_5020_50200801_220_dialog_content = "... Ainda estou carregando todo esse álcool, mestre.",
  ui_story_5020_50200801_221_dialog_content = "Eu só estava brincando! Você realmente não sente vontade de competir com seu mestre agora, não é?",
  ui_story_5020_50200801_222_dialog_content = "...",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>Poço... Poço... Poço... Pat...</color>",
  ui_story_5020_50200801_224_dialog_content = "Mestre... Você já se arrependeu de ter matado Tsuki?",
  ui_story_5020_50200801_225_dialog_content = "Claro que não. Eu não estou arrependido.",
  ui_story_5020_50200801_226_dialog_content = "Então por que perguntou sobre o funeral dela?",
  ui_story_5020_50200801_227_dialog_content = "...",
  ui_story_5020_50200801_228_dialog_content = "Não me arrependo de matá-la, mas...",
  ui_story_5020_50200801_229_dialog_content = "Ela era minha irmã, afinal. Eu deveria ter sido o único a enterrá-la.",
  ui_story_5020_50200801_230_dialog_content = "Entendo...",
  ui_story_5020_50200801_231_dialog_content = "E, há mais uma coisa.",
  ui_story_5020_50200801_232_dialog_content = "Slice of Heaven pertencia a ela. Então, se eu tivesse que adivinhar, provavelmente foi enterrado com ela.",
  ui_story_5020_50200801_233_dialog_content = "Afinal, foi feito para matar fantasmas. O general não precisa de algo assim.",
  ui_story_5020_50200801_234_dialog_content = "Você deseja encontrar o Slice of Heaven, mestre?",
  ui_story_5020_50200801_235_dialog_content = "Isso mesmo.",
  ui_story_5020_50200801_236_dialog_content = "Tsuki estaria rolando em seu túmulo se ela soubesse que sua preciosa espada foi deixada para enferrujar sob uma pilha de terra.",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>Poço... Pat...</color>",
  ui_story_5020_50200801_238_dialog_content = "Ufa! Faz séculos desde a última vez que subi aqui!",
  ui_story_5020_50200801_239_dialog_content = "Tudo bem, minha garota, desamarre essas garrafas e me passe uma.",
  ui_story_5020_50200801_240_dialog_content = "Vamos ver se a bebida do meu velho amigo melhorou na última década.",
  ui_story_5020_50200801_241_dialog_content = "Sim...",
  ui_story_5020_50200801_242_dialog_content = "Diga... Você já tem idade suficiente para beber?",
  ui_story_5020_50200801_243_dialog_content = "Eu... eu não consigo segurar minha bebida.",
  ui_story_5020_50200801_244_dialog_content = "Que chato.",
  ui_story_5020_50200801_245_dialog_content = "Ah, esqueça. Apenas me dê uma daquelas garrafas, e <color=#FFB400>quebra</color> o resto.",
  ui_story_5020_50200801_246_dialog_content = "Esmagá-los? Mas por que...?",
  ui_story_5020_50200801_247_dialog_content = "Você está me questionando? Se eu disser para você quebrar essas garrafas, você as quebra imediatamente! Percebido?",
  ui_story_5020_50200801_248_dialog_content = "... Entendido.",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>Rachadura!!</color>",
  ui_story_5020_50200801_252_dialog_content = "Hahahahaha! Bem desse jeito!",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>Cola... Cola...</anim>",
  ui_story_5020_50200801_254_dialog_content = "Fuaaahh! Essa é a coisa boa!",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>Poço... Poço... Poço... Pat...</color>",
  ui_story_5020_50200801_256_dialog_content = "Por favor, tente não cair, mestre.",
  ui_story_5020_50200801_257_dialog_content = "Ah! Com quem você pensa que está falando, hein?",
  ui_story_5020_50200801_258_dialog_content = "Agora olhe lá embaixo, Amemori.",
  ui_story_5020_50200801_259_dialog_content = "Você vê aquele homem andando ali? Diga-me, quem poderia ser?",
  ui_story_5020_50200801_260_dialog_content = "...",
  ui_story_5020_50200801_261_dialog_content = "É Fujikumo.",
  ui_story_5020_50200801_262_dialog_content = "O que ele está fazendo?",
  ui_story_5020_50200801_263_dialog_content = "Vou te contar uma coisa. Os inimigos se entendem melhor.",
  ui_story_5020_50200801_264_dialog_content = "Mesmo desta distância, no telhado de um prédio completamente diferente... ainda consigo entender o que está passando pela cabeça dele agora.",
  ui_story_5020_50200801_265_dialog_content = "Neste momento, ele deve estar pensando que está avançando para a paz.",
  ui_story_5020_50200801_266_dialog_content = "Por quê?",
  ui_story_5020_50200801_267_dialog_content = "Porque isso é exatamente o que eu estaria pensando.",
  ui_story_5020_50200801_268_dialog_content = "!!!",
  ui_story_5020_50200801_269_dialog_content = "Mas mestre...",
  ui_story_5020_50200801_270_dialog_content = "Vamos lá! Beber sozinho não é divertido!",
  ui_story_5020_50200801_271_dialog_content = "Se meu próprio aluno não beber comigo, terei que pedir a todos os Koufu-jou!",
  ui_story_5020_50200901_1_dialog_content = "Em geral! As principais forças do Wisp foram capturadas. Eles estão a caminho do castelo enquanto falamos.",
  ui_story_5020_50200901_2_dialog_content = "Claro.",
  ui_story_5020_50200901_3_dialog_content = "Hoje, a bandeira da rebelião será reduzida a cinzas.",
  ui_story_5020_50200901_4_dialog_content = "Avise as pessoas! Diga-lhes para virem ao castelo e testemunharem a justiça sendo feita contra os traidores!",
  ui_story_5020_50200901_5_dialog_content = "Depois de uma noite de apreensão, alguém deve ser responsabilizado pelo caos que ameaçava nossa bela cidade.",
  ui_story_5020_50200901_6_dialog_content = "Ainda temos o Festival Kasuga ao amanhecer.",
  ui_story_5020_50200901_7_dialog_content = "Sim, senhor.",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50200901_9_dialog_content = "Ei! Estamos realmente indo para algum lugar com menos pessoas?",
  ui_story_5020_50200901_10_dialog_content = "Por que parece que as coisas estão ficando cada vez mais agitadas aqui?",
  ui_story_5020_50200901_11_dialog_content = "Não pode ser ajudado, PlayerName.",
  ui_story_5020_50200901_12_dialog_content = "Empurrar aquele tambor enorme teria sido muito visível. Nossa melhor aposta é se esconder na multidão e segui-los.",
  ui_story_5020_50200901_13_dialog_content = "Certo, então... Onde exatamente estamos agora?",
  ui_story_5020_50200901_14_dialog_content = "Nos deveríamos ser...",
  ui_story_5020_50200901_15_dialog_content = "Do lado de fora do castelo.",
  ui_story_5020_50200901_16_dialog_content = "O que?! Você está tentando nos levar para nossas mortes?!",
  ui_story_5020_50200901_17_dialog_content = "Não se preocupe, vamos descobrir alguma coisa!",
  ui_story_5020_50200901_18_dialog_content = "Se o pior acontecer, você terá que se esconder até o final do Festival Kasuga...",
  ui_story_5020_50200901_19_dialog_content = "Você realmente está tentando nos matar, não é?!",
  ui_story_5020_50200901_20_dialog_content = "<size=45>Limpe um caminho!</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>Não fique no nosso caminho!</size>",
  ui_story_5020_50200901_22_dialog_content = "Que foi agora?",
  ui_story_5020_50200901_23_dialog_content = "Os samurais estão liderando um grande grupo de pessoas aqui!",
  ui_story_5020_50200901_24_dialog_content = "Espere, eles não são...?",
  ui_story_5020_50200901_25_dialog_content = "Eles estão! É Wisp!",
  ui_story_5020_50200901_26_dialog_content = "Wisp?!",
  ui_story_5020_50200901_27_dialog_content = "Todos foram capturados?",
  ui_story_5020_50200901_28_dialog_content = "Com certeza é o que parece...",
  ui_story_5020_50200901_29_dialog_content = "Eles estão indo para o castelo também.",
  ui_story_5020_50200901_30_dialog_content = "O castelo... O que o general fará com eles?",
  ui_story_5020_50200901_31_dialog_content = "Ele vai usá-los como bodes expiatórios. Alguém para o público dirigir sua raiva e medo.",
  ui_story_5020_50200901_32_dialog_content = "Mas não foi culpa deles!",
  ui_story_5020_50200901_33_dialog_content = "As pessoas realmente acreditarão nele?",
  ui_story_5020_50200901_34_dialog_content = "O general está no controle total dos fantasmas e pode convocá-los e dispensá-los à vontade.",
  ui_story_5020_50200901_35_dialog_content = "Agora que Wisp foi capturado, ele pode facilmente parar os ataques e fazer as pessoas acreditarem que os rebeldes foram os responsáveis.",
  ui_story_5020_50200901_36_dialog_content = "Tudo o que podem fazer é acreditar nele.",
  ui_story_5020_50200901_37_dialog_content = "Mas se isso acontecer...",
  ui_story_5020_50200901_38_dialog_content = "Se isso acontecer...",
  ui_story_5020_50200901_39_dialog_content = "Hã?",
  ui_story_5020_50200901_40_dialog_content = "Então não haverá mais fantasmas para lutar em Koufu-jou...",
  ui_story_5020_50200901_41_dialog_content = "Isso não seria... uma coisa boa?",
  ui_story_5020_50200901_42_dialog_content = "Você tem razão, sim...",
  ui_story_5020_50200901_43_dialog_content = "Essas são as táticas de um governante frio e impiedoso.",
  ui_story_5020_50200901_44_dialog_content = "Ele sacrifica e trai os outros sem hesitação.",
  ui_story_5020_50200901_45_dialog_content = "Mas no final... as coisas parecerão melhores, pelo menos na superfície.",
  ui_story_5020_50200901_46_dialog_content = "...",
  ui_story_5020_50200901_47_dialog_content = "Mas apenas na superfície, certo?",
  ui_story_5020_50200901_48_dialog_content = "O povo de Cloud Island acredita na existência da alma de todo o coração.",
  ui_story_5020_50200901_49_dialog_content = "Se as coisas acontecerem como eu previ, todos viverão no mundo ilusório do general, felizes e despreocupados.",
  ui_story_5020_50200901_50_dialog_content = "Mas uma alma que vive na ignorância pecaminosa de uma verdade tão terrível não é diferente da morte.",
  ui_story_5020_50200901_51_dialog_content = "Acredito que quem conhece a verdade não ficaria parado e aceitaria as coisas como elas são.",
  ui_story_5020_50200901_52_dialog_content = "Isso mesmo! Como poderia uma cidade inteira viver sob a ilusão de tal mentira?",
  ui_story_5020_50200901_53_dialog_content = "Todos precisam ouvir a verdade!",
  ui_story_5020_50200901_54_dialog_content = "...",
  ui_story_5020_50200901_55_dialog_content = "Vocês dois estão absolutamente certos.",
  ui_story_5020_50200901_56_dialog_content = "Uma paz construída sobre uma montanha de mentiras não é paz.",
  ui_story_5020_50200901_57_dialog_content = "Precisamos mostrar a todos a verdade.",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>Pit-pat... Pit-pat...</color>",
  ui_story_5020_50200901_59_dialog_content = "Anzu, Momo... Você acha que consegue alcançar aquele time de Wisp?",
  ui_story_5020_50200901_60_dialog_content = "Apanhá-los?",
  ui_story_5020_50200901_61_dialog_content = "Se o fizermos, então não temos chance de escapar, você sabe.",
  ui_story_5020_50200901_62_dialog_content = "Não estamos fugindo. Não mais.",
  ui_story_5020_50200901_63_dialog_content = "Não quero perder o Festival Kasuga por nada!",
  ui_story_5020_50200901_64_dialog_content = "Ouvi dizer que vão julgar alguns criminosos... É verdade?",
  ui_story_5020_50200901_65_dialog_content = "Isto é! O próprio general disse isso!",
  ui_story_5020_50200901_66_dialog_content = "Finalmente, os traidores que invocaram os fantasmas são levados à justiça!",
  ui_story_5020_50200901_67_dialog_content = "Ei, olha aí! Eles estão sendo escoltados para a praça agora mesmo!",
  ui_story_5020_50200901_68_dialog_content = "Espere, eram realmente eles? Conheço tantos!",
  ui_story_5020_50200901_69_dialog_content = "Quem sabe, talvez eles estejam apenas sendo usados como bodes expiatórios...",
  ui_story_5020_50200901_70_dialog_content = "Hmph! O general com certeza sabe como garantir sua posição.",
  ui_story_5020_50200901_71_dialog_content = "Bem, quem foi o responsável por tudo isso vai pagar caro...",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>Bang...!</color>",
  ui_story_5020_50200901_73_dialog_content = "Em geral!",
  ui_story_5020_50200901_74_dialog_content = "Os rebeldes Wisp foram todos capturados!",
  ui_story_5020_50200901_75_dialog_content = "Pedimos humildemente que você os julgue por seus crimes hediondos!",
  ui_story_5020_50200901_76_dialog_content = "Já se passaram várias décadas desde que pus os pés em Koufu-jou pela primeira vez.",
  ui_story_5020_50200901_77_dialog_content = "Eu me cansei das lutas constantes e feias que me cercaram desde então.",
  ui_story_5020_50200901_78_dialog_content = "Isso tudo acaba hoje. Bem aqui. Agora mesmo.",
  ui_story_5020_50200901_79_dialog_content = "Eu posso ver o amanhecer da paz se aproximando...",
  ui_story_5020_50200901_80_dialog_content = "Paz...",
  ui_story_5020_50200901_81_dialog_content = "Quando a guerra ameaçou toda Koufu-jou, fui eu quem pôs fim à luta.",
  ui_story_5020_50200901_82_dialog_content = "Quando os fantasmas ameaçaram nosso próprio modo de vida, comecei a treinar sacerdotisas para suprimir a ameaça dos mortos-vivos.",
  ui_story_5020_50200901_83_dialog_content = "Sob meu governo, toda Koufu-jou desfrutou de um nível sem precedentes de paz e tranquilidade.",
  ui_story_5020_50200901_84_dialog_content = "Mas sempre há aqueles que nunca ficarão satisfeitos.",
  ui_story_5020_50200901_85_dialog_content = "Eles atropelaram a ordem que eu estava mantendo, e eles descaradamente exigiram mais!",
  ui_story_5020_50200901_86_dialog_content = "Agora, eles estão ajoelhados na frente de todos nós.",
  ui_story_5020_50200901_87_dialog_content = "...",
  ui_story_5020_50200901_88_dialog_content = "Wisp rebeldes, você está ciente de seus pecados?",
  ui_story_5020_50200901_89_dialog_content = "Pecados?",
  ui_story_5020_50200901_90_dialog_content = "Sinceramente, não faço ideia.",
  ui_story_5020_50200901_91_dialog_content = "Parece que você sabe, por que não lhe dou a honra de nos contar?",
  ui_story_5020_50200901_92_dialog_content = "Certo. Então eu vou.",
  ui_story_5020_50200901_93_dialog_content = "Você conspirou com fantasmas cruéis para perturbar a paz e a ordem de Koufu-jou.",
  ui_story_5020_50200901_94_dialog_content = "Isso é punível com a morte!",
  ui_story_5020_50200901_95_dialog_content = "Ha.",
  ui_story_5020_50200901_96_dialog_content = "Fujikumo, seu velho...",
  ui_story_5020_50200901_97_dialog_content = "(Uh, desculpe-me. Eu odeio interromper seu discurso apaixonado.)",
  ui_story_5020_50200901_98_dialog_content = "(Mas você poderia, por favor, jogar com calma para nos ganhar mais tempo?)",
  ui_story_5020_50200901_99_dialog_content = "(Será difícil salvá-lo se você for executado imediatamente.)",
  ui_story_5020_50200901_100_dialog_content = "...",
  ui_story_5020_50200901_101_dialog_content = "(Anzu e Momo vão desamarrar você mais tarde. Será nossa única chance.)",
  ui_story_5020_50200901_102_dialog_content = "(Você deve subjugar todos os samurais de uma vez, ou estaremos todos ferrados.)",
  ui_story_5020_50200901_103_dialog_content = "(Tosse se você entender.)",
  ui_story_5020_50200901_104_dialog_content = "*Tosse*",
  ui_story_5020_50200901_105_dialog_content = "(Ok. Continue, mantenha-o ocupado.)",
  ui_story_5020_50200901_106_dialog_content = "Er... meu senhor, ouça-me.",
  ui_story_5020_50200901_107_dialog_content = "Vá em frente e corte um membro ou dois, mas você poderia, por favor, manter minha cabeça no meu pescoço?",
  ui_story_5020_50200901_108_dialog_content = "...",
  ui_story_5020_50200901_109_dialog_content = "Eu tenho dois braços e duas pernas. Escolha o que você gosta.",
  ui_story_5020_50200901_110_dialog_content = "Mas ainda tenho uso para minha cabeça, então gostaria de mantê-la.",
  ui_story_5020_50200901_111_dialog_content = "Certo, temos três samurais aqui... e mais cinco ali. Há outros dois do outro lado da estrada.",
  ui_story_5020_50200901_112_dialog_content = "Vice, você consegue se lembrar de tudo isso?",
  ui_story_5020_50200901_113_dialog_content = "Três... E cinco... E mais dois...",
  ui_story_5020_50200901_114_dialog_content = "Você tem que se lembrar disso. Não teremos uma segunda chance!",
  ui_story_5020_50200901_115_dialog_content = "Anzu e Momo afrouxaram a pele do tambor. Só precisamos mergulhar nele.",
  ui_story_5020_50200901_116_dialog_content = "Assim que sairmos do tambor, precisamos nocautear todos os samurais!",
  ui_story_5020_50200901_117_dialog_content = "Esta é a única maneira de Anzu e Momo desatar o Wisp.",
  ui_story_5020_50200901_118_dialog_content = "Sim! Três... e cinco...",
  ui_story_5020_50200901_119_dialog_content = "E meu papel é parar o general, certo?",
  ui_story_5020_50200901_120_dialog_content = "Sim, faça o máximo de caos que puder.",
  ui_story_5020_50200901_121_dialog_content = "Assim que o general ordenar que os fantasmas nos parem, a verdade virá à tona!",
  ui_story_5020_50200901_122_dialog_content = "E então? Como vamos sair depois?",
  ui_story_5020_50200901_123_dialog_content = "Não posso planejar com tanta antecedência. Vamos ter que improvisar depois disso!",
  ui_story_5020_50200901_124_dialog_content = "Anzu e Momo, você está pronto?",
  ui_story_5020_50200901_125_dialog_content = "Sim!",
  ui_story_5020_50200901_126_dialog_content = "Cortamos as cordas e depois corremos com o Wisp.",
  ui_story_5020_50200901_127_dialog_content = "Exatamente!",
  ui_story_5020_50200901_128_dialog_content = "Eles não parecem estar em boa forma...",
  ui_story_5020_50200901_129_dialog_content = "Será perigoso?",
  ui_story_5020_50200901_130_dialog_content = "Avise-nos se estiver em perigo.",
  ui_story_5020_50200901_131_dialog_content = "Como...",
  ui_story_5020_50200901_132_dialog_content = "Use este tambor.",
  ui_story_5020_50200901_133_dialog_content = "Oh, certo! Entendido.",
  ui_story_5020_50200901_134_dialog_content = "Eu amo batucar!",
  ui_story_5020_50200901_135_dialog_content = "Agora é só esperar Vice para memorizar tudo...",
  ui_story_5020_50200901_136_dialog_content = "Saquei!",
  ui_story_5020_50200901_137_dialog_content = "Vamos!",
  ui_story_5020_50200901_138_dialog_content = "Prepare-se. Três...",
  ui_story_5020_50200901_139_dialog_content = "<size=40>Dois...</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>Um...</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>Ir!</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>Estrondo...</size></color>",
  ui_story_5020_50200901_143_dialog_content = "Torrente Rápida!",
  ui_story_5020_50200901_144_dialog_content = "Resgate o Wisp! Pressa!",
  ui_story_5020_50200901_145_dialog_content = "Eu sei, eu sei!",
  ui_story_5020_50200901_146_dialog_content = "Ajuda! Há uma luta!",
  ui_story_5020_50200901_147_dialog_content = "Irmãos, peguem suas armas!",
  ui_story_5020_50200901_148_dialog_content = "Rebeldes! Proteja o general!",
  ui_story_5020_50200901_149_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50200901_150_dialog_content = "...",
  ui_story_5020_50200901_151_dialog_content = "...",
  ui_story_5020_50200901_152_dialog_content = "Rinne, você cometeu um grande erro.",
  ui_story_5020_50200901_153_dialog_content = "Por quê?",
  ui_story_5020_50200901_154_dialog_content = "Porque isso está errado.",
  ui_story_5020_50200901_155_dialog_content = "O certo e o errado que você me ensinou parecem bem diferentes de suas crenças reais.",
  ui_story_5020_50200901_156_dialog_content = "Não posso te ensinar tudo o que sei. Vai levar tempo para você entender.",
  ui_story_5020_50200901_157_dialog_content = "Não há necessidade. Eu mesmo descobri.",
  ui_story_5020_50200901_158_dialog_content = "Todas as sacerdotisas antes de mim, aquelas que fizeram o que você achava certo, onde estão agora?",
  ui_story_5020_50200901_159_dialog_content = "Eles construíram o Koufu-jou que você vê hoje.",
  ui_story_5020_50200901_160_dialog_content = "É mesmo?",
  ui_story_5020_50200901_161_dialog_content = "Eu gostaria de ver um Koufu-jou diferente.",
  ui_story_5020_50200901_162_dialog_content = "E é assim que você escolhe ir sobre isso?",
  ui_story_5020_50200901_163_dialog_content = "Já vi muitas revoltas na minha vida. Eles nunca trouxeram mudança – apenas destruição.",
  ui_story_5020_50200901_164_dialog_content = "Tenho certeza que há coisas que você não viu.",
  ui_story_5020_50200901_165_dialog_content = "Como uma sacerdotisa apontando uma lâmina para você.",
  ui_story_5020_50200901_166_dialog_content = "Eu não me importo para onde você aponta sua lâmina.",
  ui_story_5020_50200901_167_dialog_content = "Eu só quero que você pense bem.",
  ui_story_5020_50200901_168_dialog_content = "Pensei que os fantasmas fossem meu único inimigo.",
  ui_story_5020_50200901_169_dialog_content = "Mas agora, estou de frente para você.",
  ui_story_5020_50200901_170_dialog_content = "E pela primeira vez sinto um ódio intenso por uma pessoa viva.",
  ui_story_5020_50200901_171_dialog_content = "Você deveria ter medo desse ódio.",
  ui_story_5020_50200901_172_dialog_content = "Hehehe.",
  ui_story_5020_50200901_173_dialog_content = "Estou mais emocionado do que assustado.",
  ui_story_5020_50200902_1_dialog_content = "Mate eles!",
  ui_story_5020_50200902_2_dialog_content = "Rebeldes imprudentes!",
  ui_story_5020_50200902_3_dialog_content = "Ahhh! Eles estão matando pessoas!",
  ui_story_5020_50200902_4_dialog_content = "Sem pânico!",
  ui_story_5020_50200902_5_dialog_content = "Reagrupar! Cerquem os rebeldes!",
  ui_story_5020_50200902_6_dialog_content = "Nos cercam? Hmph!",
  ui_story_5020_50200902_7_dialog_content = "Samurai, acho que você não entende a situação.",
  ui_story_5020_50200902_8_dialog_content = "Sem os fantasmas para ajudá-lo, você não pode comandar este campo de batalha!",
  ui_story_5020_50200902_9_dialog_content = "Que piada.",
  ui_story_5020_50200902_10_dialog_content = "Quando você Wisp ganhou uma luta, seja contra fantasmas ou pessoas vivas?",
  ui_story_5020_50200902_11_dialog_content = "Desta vez.",
  ui_story_5020_50200902_12_dialog_content = "Devemos correr? não quero morrer...",
  ui_story_5020_50200902_13_dialog_content = "Para onde? Se sairmos, podemos encontrar fantasmas...",
  ui_story_5020_50200902_14_dialog_content = "Primeiro fantasmas matam pessoas, agora pessoas matam pessoas também...",
  ui_story_5020_50200902_15_dialog_content = "Quantas vidas serão tiradas hoje?",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_5020_50200902_17_dialog_content = "!!!",
  ui_story_5020_50200902_18_dialog_content = "!!!",
  ui_story_5020_50200902_19_dialog_content = "Aquilo foi...",
  ui_story_5020_50200902_20_dialog_content = "Essa não.",
  ui_story_5020_50200902_21_dialog_content = "A nuvem dourada surgiu, lançando seu brilho sobre o mundo. Todos os fantasmas e espíritos se curvam ao seu rei.",
  ui_story_5020_50200902_22_dialog_content = "...",
  ui_story_5020_50200902_23_dialog_content = "General, finalmente chegou a hora de você me ensinar como usar o Cloud Mirror.",
  ui_story_5020_50200902_24_dialog_content = "Tudo que eu sempre quis foi paz.",
  ui_story_5020_50200902_25_dialog_content = "Você se beneficia da paz, mas não a entende.",
  ui_story_5020_50200902_26_dialog_content = "Não tenho tempo para te ensinar mais nada.",
  ui_story_5020_50200902_27_dialog_content = "Hoje, Koufu-jou conhecerá a paz.",
  ui_story_5020_50200902_28_dialog_content = "Goste você ou não.",
  ui_story_5020_50200902_29_dialog_content = "...",
  ui_story_5020_50200902_30_dialog_content = "...",
  ui_story_5020_50200902_31_dialog_content = "Fantasmas... Os fantasmas estão chegando!",
  ui_story_5020_50200902_32_dialog_content = "Pare de lutar! Lide com os fantasmas primeiro!",
  ui_story_5020_50200902_33_dialog_content = "Pare? Hmm!",
  ui_story_5020_50200902_34_dialog_content = "Os samurais finalmente sentem vontade de lutar, agora que seus reforços estão aqui.",
  ui_story_5020_50200902_35_dialog_content = "...",
  ui_story_5020_50200902_36_dialog_content = "Soldados!",
  ui_story_5020_50200902_37_dialog_content = "Bloqueie todas as ruas.",
  ui_story_5020_50200902_38_dialog_content = "Por ordem do general, ninguém sai daqui!",
  ui_story_5020_50200902_39_dialog_content = "O quê?",
  ui_story_5020_50200902_40_dialog_content = "O que você quer dizer com ninguém sai? Os fantasmas estão chegando!",
  ui_story_5020_50200902_41_dialog_content = "Você está...",
  ui_story_5020_50200902_42_dialog_content = "Meus companheiros! O Wisp não aceita ordens do general!",
  ui_story_5020_50200902_43_dialog_content = "Abra um caminho e escolte os civis para a segurança!",
  ui_story_5020_50200902_44_dialog_content = "Sim!",
  ui_story_5020_50200902_45_dialog_content = "Pressa! Siga o Wisp!",
  ui_story_5020_50200902_46_dialog_content = "É o que eu venho dizendo, você sempre pode contar com o pessoal da Cloud Island!",
  ui_story_5020_50200902_47_dialog_content = "Claramente, aquele general está conspirando com os fantasmas!",
  ui_story_5020_50200902_48_dialog_content = "Hmph! Uma pessoa com um coração de lobo!",
  ui_story_5020_50200902_49_dialog_content = "Você está bloqueando as ruas? E os civis?",
  ui_story_5020_50200902_50_dialog_content = "Estou mantendo a ordem para eles.",
  ui_story_5020_50200902_51_dialog_content = "Aqueles que observam a ordem desfrutam de paz. E aqueles que desafiam a ordem serão punidos.",
  ui_story_5020_50200902_52_dialog_content = "Você está usando fantasmas para manter a ordem?",
  ui_story_5020_50200902_53_dialog_content = "Você é Insano.",
  ui_story_5020_50200902_54_dialog_content = "Fantasmas, pessoas... Eles não são tão diferentes.",
  ui_story_5020_50200902_55_dialog_content = "Rinne, você se tornou superficial.",
  ui_story_5020_50200902_56_dialog_content = "Você...!",
  ui_story_5020_50200902_57_dialog_content = "Rinne, esqueça-o por enquanto.",
  ui_story_5020_50200902_58_dialog_content = "O Wisp está tentando romper com os civis, mas...",
  ui_story_5020_50200902_59_dialog_content = "Eles estão em menor número, eles podem não conseguir.",
  ui_story_5020_50200902_60_dialog_content = "... Você tem um plano?",
  ui_story_5020_50200902_61_dialog_content = "Sim.",
  ui_story_5020_50200902_62_dialog_content = "Você dá-lhes uma mão.",
  ui_story_5020_50200902_63_dialog_content = "Mim? Então e a situação aqui?",
  ui_story_5020_50200902_64_dialog_content = "Vice e eu vou lidar com o general.",
  ui_story_5020_50200902_65_dialog_content = "Uhh? Vamos?",
  ui_story_5020_50200902_66_dialog_content = "sim. Não tenho certeza de quanto tempo podemos aguentar aqui. Não há tempo a perder.",
  ui_story_5020_50200902_67_dialog_content = "Rinne, ninguém pode lutar contra fantasmas melhor do que você. Tem que ser você.",
  ui_story_5020_50200902_68_dialog_content = "Só não tenho certeza se você vai conseguir...",
  ui_story_5020_50200902_69_dialog_content = "Não se preocupe! Está no papo!",
  ui_story_5020_50200902_70_dialog_content = "Depressa!",
  ui_story_5020_50200902_71_dialog_content = "... Tá bem.",
  ui_story_5020_50200902_72_dialog_content = "Só tome cuidado, ok?",
  ui_story_5020_50200902_73_dialog_content = "... PlayerName, você tem certeza que isso é uma boa ideia?",
  ui_story_5020_50200902_74_dialog_content = "Você e eu contra o general?",
  ui_story_5020_50200902_75_dialog_content = "Não temos chance.",
  ui_story_5020_50200902_76_dialog_content = "<size=45>Achei que você tinha um plano!</size>",
  ui_story_5020_50200902_77_dialog_content = "Acalmar. Temos ajudantes.",
  ui_story_5020_50200902_78_dialog_content = "Eles estão a caminho.",
  ui_story_5020_50200902_79_dialog_content = "Ah! Outro beco sem saída!",
  ui_story_5020_50200902_80_dialog_content = "Quem pensou que era uma boa ideia construir uma casa tão complicada?",
  ui_story_5020_50200902_81_dialog_content = "Talvez eu tenha que passar a noite aqui...",
  ui_story_5020_50200902_82_dialog_content = "Sem comida ou água...",
  ui_story_5020_50200902_83_dialog_content = "E no calor escaldante...",
  ui_story_5020_50200902_84_dialog_content = "Hmm? Tem estado tão quente esse tempo todo?",
  ui_story_5020_50200902_85_dialog_content = "Nossa!",
  ui_story_5020_50200902_86_dialog_content = "F-Fogo! Alguém está aqui?",
  ui_story_5020_50200902_87_dialog_content = "Não posso mais ficar aqui... Agora tenho que sair!",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>Baque...</color>",
  ui_story_5020_50200902_89_dialog_content = "Ah! Não é outro beco sem saída!",
  ui_story_5020_50200902_90_dialog_content = "O que devo fazer? Que tal essa janela?",
  ui_story_5020_50200902_91_dialog_content = "É muito alto!",
  ui_story_5020_50200902_92_dialog_content = "De jeito nenhum... Se eu pular aqui...",
  ui_story_5020_50200902_93_dialog_content = "Aaaahhhh!",
  ui_story_5020_50200902_94_dialog_content = "Acho que não é tão alto assim!",
  ui_story_5020_50200902_95_dialog_content = "Está bem. Contanto que eu não caia de cabeça, eu vou ficar bem!",
  ui_story_5020_50200902_96_dialog_content = "Preparar...",
  ui_story_5020_50200902_97_dialog_content = "Um dois...",
  ui_story_5020_50200902_98_dialog_content = "Três!",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>Ahhhhhhhhhhhhhhhh!</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>Bang...</color>",
  ui_story_5020_50200902_101_dialog_content = "Ai! Minha bunda...",
  ui_story_5020_50200902_102_dialog_content = "É aquele... Yao?",
  ui_story_5020_50200902_103_dialog_content = "Sim!",
  ui_story_5020_50200902_104_dialog_content = "Uau! Vice! PlayerName!",
  ui_story_5020_50200902_105_dialog_content = "Tem sido para sempre!",
  ui_story_5020_50200902_106_dialog_content = "... Você poderia me ajudar?",
  ui_story_5020_50200902_107_dialog_content = "... Venha aqui. Segure firme.",
  ui_story_5020_50200902_108_dialog_content = "PlayerName, este é um dos ajudantes que você falou?",
  ui_story_5020_50200902_109_dialog_content = "Acho que ela mesma poderia usar alguma ajuda.",
  ui_story_5020_50200902_110_dialog_content = "Err... Ela é uma delas.",
  ui_story_5020_50200902_111_dialog_content = "Fora do caminho!",
  ui_story_5020_50200902_112_dialog_content = "Fujikumo, é hora de você pagar.",
  ui_story_5020_50200902_113_dialog_content = "Quem é Você? Não me lembro de lhe dever nada.",
  ui_story_5020_50200902_114_dialog_content = "Você deve sua vida a Cloud Island.",
  ui_story_5020_50200902_115_dialog_content = "Amemori! Bom te ver!",
  ui_story_5020_50200902_116_dialog_content = "Eu tenho observado da torre do portão.",
  ui_story_5020_50200902_117_dialog_content = "Eu estava planejando curtir um show, mas vocês não resistiram muito.",
  ui_story_5020_50200902_118_dialog_content = "Que divertido.",
  ui_story_5020_50200902_119_dialog_content = "Você realmente achou que juntar mais alguns ratos seria suficiente para me derrubar?",
  ui_story_5020_50200902_120_dialog_content = "Hahahahahaha!",
  ui_story_5020_50200902_121_dialog_content = "Não despreze os ratos. Eles têm dentes!",
  ui_story_5020_50200902_122_dialog_content = "Dê-lhes uma década ou, melhor ainda, um século...",
  ui_story_5020_50200902_123_dialog_content = "E eles podem derrubar até o castelo mais alto!",
  ui_story_5020_50200902_124_dialog_content = "A cidade inteira está pegando fogo!",
  ui_story_5020_50200902_125_dialog_content = "Bem, sim. Foi por isso que eu pulei...",
  ui_story_5020_50200902_126_dialog_content = "Fujikumo, você já viu uma torre de portão mais bonita?",
  ui_story_5020_50200902_127_dialog_content = "É tão alto que obscurece um canto considerável do céu.",
  ui_story_5020_50200902_128_dialog_content = "Mas esta é a primeira vez que realmente parece bonito, envolto na fragrância do vinho e no calor do fogo.",
  ui_story_5020_50200902_129_dialog_content = "Eu acredito que tudo no mundo existe para aquele momento glorioso.",
  ui_story_5020_50200902_130_dialog_content = "E este é o melhor final que poderia ter.",
  ui_story_5020_50200902_131_dialog_content = "Espada do Submundo...",
  ui_story_5020_50200902_132_dialog_content = "Eu sabia que você não fugiria. A liberdade não pode satisfazê-lo.",
  ui_story_5020_50200902_133_dialog_content = "Você ainda é a mesma lâmina perversa que uma vez veio para mim do inferno...",
  ui_story_5020_50200902_134_dialog_content = "Fujikumo, quando você acha que Tsuki foi a mais bonita?",
  ui_story_5020_50200902_135_dialog_content = "... Você não é digno de falar o nome dela!",
  ui_story_5020_50200902_136_dialog_content = "Quando eu era pequena, achava ela tão linda quando me ensinava a cantar.",
  ui_story_5020_50200902_137_dialog_content = "À medida que crescia, senti que ela estava ainda mais bonita quando me disse que as sacerdotisas podiam trazer paz a este mundo.",
  ui_story_5020_50200902_138_dialog_content = "Adivinha quando eu acho que ela era a mais bonita agora.",
  ui_story_5020_50200902_139_dialog_content = "Chega!",
  ui_story_5020_50200902_140_dialog_content = "Ela era a mais linda quando faleceu em meus braços.",
  ui_story_5020_50200902_141_dialog_content = "...",
  ui_story_5020_50200902_142_dialog_content = "Ela era tão linda que não pude conter minha raiva e ódio.",
  ui_story_5020_50200902_143_dialog_content = "Porque você possuía cada pedaço de sua beleza.",
  ui_story_5020_50200902_144_dialog_content = "Já se passaram dez anos, governante de Koufu-jou.",
  ui_story_5020_50200902_145_dialog_content = "Vamos fazer um teste de determinação.",
  ui_story_5020_50200902_146_dialog_content = "Você está mais determinado a se livrar de mim, ou eu estou mais determinado a matá-lo?",
  ui_story_5020_50201001_1_dialog_content = "Como você se atreve a falar sobre ela assim!",
  ui_story_5020_50201001_2_dialog_content = "Como você ousa dizer o nome dela!",
  ui_story_5020_50201001_3_dialog_content = "Sua ignorância arruinou o mundo perfeito que ela criou.",
  ui_story_5020_50201001_4_dialog_content = "Você deveria pedir perdão a ela no inferno!",
  ui_story_5020_50201001_5_dialog_content = "!!!",
  ui_story_5020_50201001_6_dialog_content = "... Fujikumo, você realmente enlouqueceu.",
  ui_story_5020_50201001_7_dialog_content = "Não tenho mais nada a perder.",
  ui_story_5020_50201001_8_dialog_content = "...",
  ui_story_5020_50201001_9_dialog_content = "Ei, vocês dois. Não fique aí parado assistindo.",
  ui_story_5020_50201001_10_dialog_content = "Mestre! Estou pronto para te ajudar!",
  ui_story_5020_50201001_11_dialog_content = "Não estou pedindo ajuda.",
  ui_story_5020_50201001_12_dialog_content = "Eu preciso que você fuja, o mais rápido que puder.",
  ui_story_5020_50201001_13_dialog_content = "Mas... Mestre...",
  ui_story_5020_50201001_14_dialog_content = "Eu disse corra!",
  ui_story_5020_50201001_15_dialog_content = "Eu não tenho tempo para isso!",
  ui_story_5020_50201001_16_dialog_content = "Não piore as coisas para mim!",
  ui_story_5020_50201001_17_dialog_content = "Mestre...",
  ui_story_5020_50201001_18_dialog_content = "T-tudo bem!",
  ui_story_5020_50201001_19_dialog_content = "Vamos, Amemori. O mestre tem isso!",
  ui_story_5020_50201001_20_dialog_content = "...",
  ui_story_5020_50201001_21_dialog_content = "Sim, mestre.",
  ui_story_5020_50201001_22_dialog_content = "Isso mesmo, bons aprendizes fazem o que seu mestre manda!",
  ui_story_5020_50201001_23_dialog_content = "Bem, bem, Espada do Submundo, eu nunca esperei ver auto-sacrifício em você.",
  ui_story_5020_50201001_24_dialog_content = "Ah. Eu simplesmente quero continuar a lenda da Espada do Submundo.",
  ui_story_5020_50201001_25_dialog_content = "Como mestre de espadas conhecido por caçar fantasmas, não poderia perder a oportunidade de lutar contra o homem que escolheu se tornar um...",
  ui_story_5020_50201001_26_dialog_content = "E morrer em suas mãos.",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50201001_28_dialog_content = "A voz dele é tão assustadora...",
  ui_story_5020_50201001_29_dialog_content = "Isso é realmente uma luta de duas pessoas?",
  ui_story_5020_50201001_30_dialog_content = "Fugir é definitivamente a decisão certa... Mesmo todos nós juntos ainda não somos páreo para ele.",
  ui_story_5020_50201001_31_dialog_content = "O que está acontecendo na cidade?",
  ui_story_5020_50201001_32_dialog_content = "Onde está a Rinne? Por que ela não está com você?",
  ui_story_5020_50201001_33_dialog_content = "Err... É uma longa história.",
  ui_story_5020_50201001_34_dialog_content = "O general conjurou fantasmas para restaurar a ordem. Eles uniram forças com os samurais, tentando manter o controle de todos os cidadãos de Koufu-jou.",
  ui_story_5020_50201001_35_dialog_content = "Felizmente, a maioria dos civis se reuniu. O Wisp e Rinne estão escoltando-os para a segurança.",
  ui_story_5020_50201001_36_dialog_content = "Vespa?",
  ui_story_5020_50201001_37_dialog_content = "Wisp!",
  ui_story_5020_50201001_38_dialog_content = "Uma força composta por moradores de Cloud Island. Mestre e eu somos parte deles.",
  ui_story_5020_50201001_39_dialog_content = "Direita!",
  ui_story_5020_50201001_40_dialog_content = "Você costumava ser um de nós.",
  ui_story_5020_50201001_41_dialog_content = "Então os Wisp são mocinhos?",
  ui_story_5020_50201001_42_dialog_content = "... Claro.",
  ui_story_5020_50201001_43_dialog_content = "Mas por que a sacerdotisa está com o Wisp?",
  ui_story_5020_50201001_44_dialog_content = "Eles a sequestraram?",
  ui_story_5020_50201001_45_dialog_content = "Seqüestradores! Os Wisp são ruins!",
  ui_story_5020_50201001_46_dialog_content = "Não, não... As coisas aconteceram, e Rinne lutou lado a lado com o Wisp.",
  ui_story_5020_50201001_47_dialog_content = "Por enquanto vamos apenas dizer que eles estão do nosso lado.",
  ui_story_5020_50201001_48_dialog_content = "O Wisp e a sacerdotisa estão do mesmo lado?",
  ui_story_5020_50201001_49_dialog_content = "Tudo isso é muito difícil de digerir...",
  ui_story_5020_50201001_50_dialog_content = "Err... Como Rinne disse antes, os fantasmas são o único inimigo da sacerdotisa.",
  ui_story_5020_50201001_51_dialog_content = "Então ela está cumprindo seu dever.",
  ui_story_5020_50201001_52_dialog_content = "... Tudo bem, eu vejo.",
  ui_story_5020_50201001_53_dialog_content = "Ela manterá os civis seguros, pelo menos por um tempo.",
  ui_story_5020_50201001_54_dialog_content = "Eu preciso ir procurar alguma coisa.",
  ui_story_5020_50201001_55_dialog_content = "O que foi?",
  ui_story_5020_50201001_56_dialog_content = "A espada matadora de fantasmas—<color=#FFB400>Pedaço de céu</color>.",
  ui_story_5020_50201001_57_dialog_content = "De acordo com o mestre... Pode ser capaz de virar a maré.",
  ui_story_5020_50201001_58_dialog_content = "Eu acho que o Wisp mencionou isso também! É uma arma lendária, certo?",
  ui_story_5020_50201001_59_dialog_content = "Mas seu paradeiro é um mistério...",
  ui_story_5020_50201001_60_dialog_content = "Foi enterrado com a sacerdotisa anterior.",
  ui_story_5020_50201001_61_dialog_content = "Ah! Isso é uma pista!",
  ui_story_5020_50201001_62_dialog_content = "Mas vamos precisar de mais do que isso...",
  ui_story_5020_50201001_63_dialog_content = "Podemos desenterrar todas as sepulturas perto da cidade.",
  ui_story_5020_50201001_64_dialog_content = "Aguentar! Isso é um pouco excessivo!",
  ui_story_5020_50201001_65_dialog_content = "O que você sugere então? Só o céu sabe qual túmulo pertence à sacerdotisa anterior...",
  ui_story_5020_50201001_66_dialog_content = "Err...",
  ui_story_5020_50201001_67_dialog_content = "Tsuki não era a sacerdotisa anterior?",
  ui_story_5020_50201001_68_dialog_content = "Correto.",
  ui_story_5020_50201001_69_dialog_content = "Você se lembra dela?",
  ui_story_5020_50201001_70_dialog_content = "Gosto sim.",
  ui_story_5020_50201001_71_dialog_content = "Eu... eu me lembro onde ela foi enterrada.",
  ui_story_5020_50201001_72_dialog_content = "Quê?!",
  ui_story_5020_50201001_73_dialog_content = "Você faz?",
  ui_story_5020_50201001_73X1_dialog_content = "Quê?!",
  ui_story_5020_50201001_73X2_dialog_content = "V-você... Se você consegue se lembrar disso... Isso significa...",
  ui_story_5020_50201001_73X3_dialog_content = "Você recuperou a memória?",
  ui_story_5020_50201001_73X4_dialog_content = "sim. Lembro-me agora, de tudo.",
  ui_story_5020_50201001_73X5_dialog_content = "Isso é maravilhoso!",
  ui_story_5020_50201001_73X6_dialog_content = "Eu não esperava que isso acontecesse agora, mas...",
  ui_story_5020_50201001_73X7_dialog_content = "Finalmente alcançamos nosso objetivo de vir para Cloud Island!",
  ui_story_5020_50201001_73X8_dialog_content = "Haha, sim, nós definitivamente conseguimos isso!",
  ui_story_5020_50201001_73X9_dialog_content = "Então, novamente... eu realmente não posso dizer que estou feliz...",
  ui_story_5020_50201001_73X10_dialog_content = "Sim, especialmente com Koufu-jou no estado em que está...",
  ui_story_5020_50201001_73X11_dialog_content = "Como você recuperou a memória?",
  ui_story_5020_50201001_73X12_dialog_content = "Encontrei um guarda-roupa no Cloud Pavilion, onde o mestre estava preso.",
  ui_story_5020_50201001_73X13_dialog_content = "As memórias voltaram à tona. Foi aí que perdi minha memória dez anos atrás.",
  ui_story_5020_50201001_73X14_dialog_content = "Eu estava me escondendo no guarda-roupa e vi o mestre matar Tsuki.",
  ui_story_5020_50201001_73X15_dialog_content = "Eu estava apavorado e confuso, e eu...",
  ui_story_5020_50201001_73X16_dialog_content = "Acho que meu cérebro enterrou tudo...",
  ui_story_5020_50201001_73X17_dialog_content = "Sim, isso não é algo que eu poderia chamar de uma memória feliz...",
  ui_story_5020_50201001_73X18_dialog_content = "Todo esse tempo, eu estava procurando a dor que eu gostaria de esquecer...",
  ui_story_5020_50201001_73X19_dialog_content = "Agora tudo parece... sem sentido.",
  ui_story_5020_50201001_73X20_dialog_content = "Tente pensar sobre isso de uma maneira diferente.",
  ui_story_5020_50201001_73X21_dialog_content = "Tudo o que você fez foi confiar a memória a uma versão crescida e mais madura de si mesmo.",
  ui_story_5020_50201001_73X22_dialog_content = "A memória está esperando você crescer e voltar para enfrentar o destino que você evitou dez anos atrás.",
  ui_story_5020_50201001_73X23_dialog_content = "Hã?",
  ui_story_5020_50201001_73X24_dialog_content = "Eu... não sabia que você era tão bom em confortar as pessoas.",
  ui_story_5020_50201001_73X25_dialog_content = "...",
  ui_story_5020_50201001_73X26_dialog_content = "Você os ouviu dizer onde enterraram Tsuki?",
  ui_story_5020_50201001_74_dialog_content = "Hum...",
  ui_story_5020_50201001_75_dialog_content = "O general disse que iria enterrar Tsuki no <color=#FFB400>montanhas a oeste de Koufu-jou.</color>",
  ui_story_5020_50201001_76_dialog_content = "As montanhas a oeste Koufu-jou...",
  ui_story_5020_50201001_77_dialog_content = "Entendi.",
  ui_story_5020_50201001_78_dialog_content = "Siga-me, para fora da cidade.",
  ui_story_5020_50201001_79_dialog_content = "Fora da cidade? Não vai ser fácil sair...",
  ui_story_5020_50201001_80_dialog_content = "Eles nos encontraram.",
  ui_story_5020_50201001_81_dialog_content = "!!!",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>...</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>Ninguém... sai!</anim>",
  ui_story_5020_50201002_1_dialog_content = "Pai…",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50201002_3_dialog_content = "*Soluços*",
  ui_story_5020_50201002_4_dialog_content = "Rá!",
  ui_story_5020_50201002_5_dialog_content = "Em frente!",
  ui_story_5020_50201002_6_dialog_content = "Uau!",
  ui_story_5020_50201002_7_dialog_content = "Não corra, garoto! É perigoso lá fora!",
  ui_story_5020_50201002_8_dialog_content = "Volte para os outros!",
  ui_story_5020_50201002_9_dialog_content = "Beleza!",
  ui_story_5020_50201002_10_dialog_content = "E você?",
  ui_story_5020_50201002_11_dialog_content = "Temos coisas para fazer!",
  ui_story_5020_50201002_12_dialog_content = "Já chega, Anzu. Se apresse!",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50201002_14_dialog_content = "Oh!",
  ui_story_5020_50201002_15_dialog_content = "Este tambor é enorme!",
  ui_story_5020_50201002_16_dialog_content = "Impressionante, não é?",
  ui_story_5020_50201002_17_dialog_content = "Por que você está trazendo isso com você?",
  ui_story_5020_50201002_18_dialog_content = "Porque é nosso!",
  ui_story_5020_50201002_19_dialog_content = "Mas não é perigoso lá fora?",
  ui_story_5020_50201002_20_dialog_content = "É tão grande que parece um fardo...",
  ui_story_5020_50201002_21_dialog_content = "De jeito nenhum! Ele acabou de salvar o Wisp mais cedo!",
  ui_story_5020_50201002_22_dialog_content = "Isso mesmo. Pode salvar mais vidas em breve!",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>Clique... Clique...</color>",
  ui_story_5020_50201002_24_dialog_content = "Chefe, temo que não consigamos passar por aqui!",
  ui_story_5020_50201002_25_dialog_content = "Estamos exaustos demais para enfrentá-los...",
  ui_story_5020_50201002_26_dialog_content = "Devemos tentar de outra forma?",
  ui_story_5020_50201002_27_dialog_content = "Não temos escolha. Em breve o inimigo nos cercará.",
  ui_story_5020_50201002_28_dialog_content = "Temos que criar uma abertura, e rápido.",
  ui_story_5020_50201002_29_dialog_content = "Mas...",
  ui_story_5020_50201002_30_dialog_content = "Eu sei que estamos todos exaustos depois de uma noite inteira de luta.",
  ui_story_5020_50201002_31_dialog_content = "Mas esta batalha é diferente das que lutamos antes.",
  ui_story_5020_50201002_32_dialog_content = "Não estamos apenas lutando por nossas vidas. Temos toda a Ilha das Nuvens atrás de nós.",
  ui_story_5020_50201002_33_dialog_content = "Desistir não é uma opção.",
  ui_story_5020_50201002_34_dialog_content = "Se morrermos, continuaremos lutando como fantasmas!",
  ui_story_5020_50201002_35_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5020_50201002_36_dialog_content = "Quem lhe deu permissão para se tornar fantasmas?",
  ui_story_5020_50201002_37_dialog_content = "Eu tenho coisas suficientes para lidar do jeito que está.",
  ui_story_5020_50201002_38_dialog_content = "A sacerdotisa?",
  ui_story_5020_50201002_39_dialog_content = "O que está fazendo aqui?",
  ui_story_5020_50201002_40_dialog_content = "PlayerName te deve um favor...",
  ui_story_5020_50201002_41_dialog_content = "Estou aqui para te vingar.",
  ui_story_5020_50201002_42_dialog_content = "...",
  ui_story_5020_50201002_43_dialog_content = "Claro.",
  ui_story_5020_50201002_44_dialog_content = "Vou confiar em você para cuidar dos fantasmas, então.",
  ui_story_5020_50201002_45_dialog_content = "E eu espero que você tenha as táticas cobertas.",
  ui_story_5020_50201002_46_dialog_content = "Você aprenderá que o Wisp é mais confiável do que aquele general.",
  ui_story_5020_50201002_47_dialog_content = "Todos! Prepare-se para um ataque total! Vamos sair do cerco!",
  ui_story_5020_50201002_48_dialog_content = "Proteja os civis! Estamos indo em direção ao <color=#FFB400>porta</color>!",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>Tosse...</anim>",
  ui_story_5020_50201002_50_dialog_content = "Você se arrepende de ter ficado para trás, Nagi?",
  ui_story_5020_50201002_51_dialog_content = "Arrependimento? Essa é uma palavra nova para mim.",
  ui_story_5020_50201002_52_dialog_content = "Você é uma guerreira. Você já imaginou sua morte?",
  ui_story_5020_50201002_53_dialog_content = "Apenas uma vez, dez anos atrás.",
  ui_story_5020_50201002_54_dialog_content = "Achei que Tsuki e eu morreríamos juntos.",
  ui_story_5020_50201002_55_dialog_content = "Mas Tsuki queria que você vivesse.",
  ui_story_5020_50201002_56_dialog_content = "Sua dívida com ela é maior do que você jamais poderia pagar.",
  ui_story_5020_50201002_57_dialog_content = "Eu só rezo para que você não seja irmã dela na próxima vida.",
  ui_story_5020_50201002_58_dialog_content = "Tosse... Hahah...",
  ui_story_5020_50201002_59_dialog_content = "A próxima vida... Parece muito patético, vindo de você.",
  ui_story_5020_50201002_60_dialog_content = "Quanto tempo mais seu coração pode durar, Fujikumo?",
  ui_story_5020_50201002_61_dialog_content = "Quem poderia guiar sua alma podre ao renascimento?",
  ui_story_5020_50201002_62_dialog_content = "...",
  ui_story_5020_50201002_63_dialog_content = "Eu sei o que me espera na morte.",
  ui_story_5020_50201002_64_dialog_content = "Mas perdi meu coração há muito tempo, quando a perdi.",
  ui_story_5020_50201002_65_dialog_content = "Então, por que eu temeria me tornar um fantasma? Não há nada neste mundo mortal que eu esteja relutante em deixar para trás.",
  ui_story_5020_50201002_66_dialog_content = "Isso soa certo...",
  ui_story_5020_50201002_67_dialog_content = "Morrer de velhice no Snow Pavilion... não é para você.",
  ui_story_5020_50201002_68_dialog_content = "Você não merece um final tranquilo.",
  ui_story_5020_50201002_69_dialog_content = "Eu não me vejo como patético em tudo.",
  ui_story_5020_50201002_70_dialog_content = "Sou um guerreiro e acabei de derrotar um rival muito poderoso.",
  ui_story_5020_50201002_71_dialog_content = "Mas Fujikumo...",
  ui_story_5020_50201002_72_dialog_content = "Nossa batalha terminou há dez anos...",
  ui_story_5020_50201002_73_dialog_content = "Você tem que agradecer a Tsuki por esses dez anos extras de vida.",
  ui_story_5020_50201002_74_dialog_content = "Não se esqueça por que essa batalha aconteceu novamente...",
  ui_story_5020_50201002_75_dialog_content = "...",
  ui_story_5020_50201002_76_dialog_content = "É porque novos lutadores estão prontos para assumir o campo de batalha!",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>Haha... ah...</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>Hahahaha!</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201101_2_dialog_content = "Ufa...",
  ui_story_5020_50201101_3_dialog_content = "Tantos samurais fantasmas...",
  ui_story_5020_50201101_4_dialog_content = "Fujikumo está realmente dando tudo de si desta vez.",
  ui_story_5020_50201101_5_dialog_content = "Quem se importa! Cuidaremos de todos eles, um de cada vez!",
  ui_story_5020_50201101_6_dialog_content = "Hyaah! Malha de Pedra!",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>Gah...</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>Graaagh!</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "T-Esses fantasmas são impossíveis de matar!",
  ui_story_5020_50201101_10_dialog_content = "Apenas Rinne pode lidar com eles.",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>Graaaaaah!</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "Huh!",
  ui_story_5020_50201101_13_dialog_content = "Podemos não ser capazes de destruí-los, mas ainda podemos empurrá-los de volta!",
  ui_story_5020_50201101_14_dialog_content = "Natureza Divina — Espigas de Bambu!",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>Grou...</anim>",
  ui_story_5020_50201101_16_dialog_content = "Mas...",
  ui_story_5020_50201101_17_dialog_content = "PlayerName, olhe para o castelo ...",
  ui_story_5020_50201101_18_dialog_content = "!!!",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>Rugido!</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "C-Como ele pode...?!",
  ui_story_5020_50201101_21_dialog_content = "Os samurais fantasmas estão todos fugindo do fogo no castelo.",
  ui_story_5020_50201101_22_dialog_content = "Fujikumo convocou tantos deles em um dia...",
  ui_story_5020_50201101_23_dialog_content = "Ele realmente não está se segurando desta vez.",
  ui_story_5020_50201101_24_dialog_content = "Ninjutsu para sempre!",
  ui_story_5020_50201101_25_dialog_content = "Devemos sair de Sakai agora e nos livrar desses perseguidores desagradáveis.",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>Perto de um cemitério no país fora de Koufu-jou</color>",
  ui_story_5020_50201101_27_dialog_content = "Oh!",
  ui_story_5020_50201101_28_dialog_content = "PlayerName, algumas das minhas memórias antigas acabaram de voltar!",
  ui_story_5020_50201101_29_dialog_content = "Eu estive aqui antes!",
  ui_story_5020_50201101_30_dialog_content = "Você realmente já esteve aqui antes...",
  ui_story_5020_50201101_31_dialog_content = "Foi aqui que nos conhecemos Rinne e Amemori pela primeira vez!",
  ui_story_5020_50201101_32_dialog_content = "Isso mesmo. O Colossus realizou um pouso de emergência após nossa chegada a Cloud Island...",
  ui_story_5020_50201101_32X_dialog_content = "Nós conhecemos Rinne na floresta de bambu à frente, e...",
  ui_story_5020_50201101_33_dialog_content = "Amemori, que teve que lutar conosco antes de ser nossa amiga!",
  ui_story_5020_50201101_34_dialog_content = "...",
  ui_story_5020_50201101_35_dialog_content = "Ah! Não é à toa que tudo parece tão familiar!",
  ui_story_5020_50201101_36_dialog_content = "… \"Siga este rio para oeste através de Rice Paddy Village e você chegará ao cemitério nas montanhas.\"",
  ui_story_5020_50201101_37_dialog_content = "Segundo minha memória, estamos no caminho certo!",
  ui_story_5020_50201101_38_dialog_content = "Ei, Amemori. Fique fora do meu caminho mais tarde, ok?",
  ui_story_5020_50201101_39_dialog_content = "Ah! Essa é a minha fala.",
  ui_story_5020_50201101_40_dialog_content = "Slice of Heaven—a espada matadora de fantasmas é nossa única esperança contra os samurais fantasmas de Fujikumo.",
  ui_story_5020_50201101_41_dialog_content = "Não estou esperando que você ajude. Só não atrapalhe.",
  ui_story_5020_50201101_42_dialog_content = "Esperar! O que você quer dizer?",
  ui_story_5020_50201101_43_dialog_content = "Você está tentando tomar Slice of Heaven para si mesmo?",
  ui_story_5020_50201101_44_dialog_content = "Está correto.",
  ui_story_5020_50201101_45_dialog_content = "Mas... Mas não é seu... Slice of Heaven é...",
  ui_story_5020_50201101_46_dialog_content = "Pertence à sacerdotisa, aquela que faleceu!",
  ui_story_5020_50201101_47_dialog_content = "Eu não me importo com nada disso. Eu preciso para proteger as pessoas inocentes de Koufu-jou.",
  ui_story_5020_50201101_48_dialog_content = "Uau! Quando você se tornou o tipo de discursos grandiosos?",
  ui_story_5020_50201101_49_dialog_content = "Você faria o mesmo se o mestre não odiasse aquela sacerdotisa?",
  ui_story_5020_50201101_50_dialog_content = "(Essas irmãs realmente são exatamente opostas...)",
  ui_story_5020_50201101_51_dialog_content = "Vocês dois... Por favor, parem de discutir!",
  ui_story_5020_50201101_52_dialog_content = "...Hã?",
  ui_story_5020_50201101_53_dialog_content = "Hmm...?",
  ui_story_5020_50201101_54_dialog_content = "Uau... Está nevando?",
  ui_story_5020_50201101_55_dialog_content = "Não, não neve. Estes são...",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>flores de cerejeira branca</color>?",
  ui_story_5020_50201101_57_dialog_content = "Estas pequenas pétalas brancas estão caindo tão suavemente... Parecem flocos de neve!",
  ui_story_5020_50201101_58_dialog_content = "\"Os moradores da Ilha das Nuvens preferem flores de cerejeira gordas e coloridas...\"",
  ui_story_5020_50201101_59_dialog_content = "Huh, isso é completamente diferente do guia!",
  ui_story_5020_50201101_60_dialog_content = "Este pode ser o único lugar em Cloud Island com este tipo de flores de cerejeira...",
  ui_story_5020_50201101_61_dialog_content = "Estamos chegando ao cemitério.",
  ui_story_5020_50201101_62_dialog_content = "Hmm... Não é à toa que está tão quieto aqui...",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201101_64_dialog_content = "Err... De jeito nenhum...",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>Gaaaa!!</anim>",
  ui_story_5020_50201101_66_dialog_content = "Não há nenhum lugar que essas coisas não vão!",
  ui_story_5020_50201101_67_dialog_content = "Bem, é um cemitério, então acho que não é completamente inesperado...",
  ui_story_5020_50201101_68_dialog_content = "Chega de conversa. É hora de eu dar alguns socos!",
  ui_story_5020_50201201_1_dialog_content = "Torrente Rápida!",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201201_3_dialog_content = "Ufa... Essas coisas são tão chatas!",
  ui_story_5020_50201201_4_dialog_content = "Mas você sabe o que dizem, não se pode tirar uma cenoura sem sujar também!",
  ui_story_5020_50201201_5_dialog_content = "... Quem disse isso, exatamente?",
  ui_story_5020_50201201_6_dialog_content = "Minha irmã jurada! Ela tem um ditado para todas as ocasiões e vence todas as discussões da família Lin!",
  ui_story_5020_50201201_7_dialog_content = "Claro, ela ganha todas as lutas também!",
  ui_story_5020_50201201_8_dialog_content = "Ela parece uma personagem...",
  ui_story_5020_50201201_9_dialog_content = "Entendo. Não admira.",
  ui_story_5020_50201201_10_dialog_content = "Hum? Não admira o quê? Não admira que eu seja tão grande?",
  ui_story_5020_50201201_11_dialog_content = "Não é à toa que você se tornou tão grosseiro.",
  ui_story_5020_50201201_12_dialog_content = "É uma pena ver o treinamento do Mestre ser desperdiçado assim.",
  ui_story_5020_50201201_13_dialog_content = "O que é que foi isso? Diga isso de novo!",
  ui_story_5020_50201201_14_dialog_content = "PlayerName, você ouve como ela fala com seus juniores?",
  ui_story_5020_50201201_15_dialog_content = "OK, Yao. É o bastante.",
  ui_story_5020_50201201_16_dialog_content = "Você também, Amemori. Você não precisava provocá-la.",
  ui_story_5020_50201201_17_dialog_content = "Que? Eu não estava brincando!",
  ui_story_5020_50201201_18_dialog_content = "E daí se você fosse!?",
  ui_story_5020_50201201_19_dialog_content = "Você está dizendo que está com muito medo de mim para me provocar?",
  ui_story_5020_50201201_20_dialog_content = "(Oh não, eu realmente não deveria ter dito nada!)",
  ui_story_5020_50201201_21_dialog_content = "Deixe-me esclarecer uma coisa.",
  ui_story_5020_50201201_22_dialog_content = "Não vou sair deste cemitério sem Slice of Heaven.",
  ui_story_5020_50201201_23_dialog_content = "Você pode inventar quantas desculpas quiser...",
  ui_story_5020_50201201_24_dialog_content = "Mas no final, você mal conseguia se lembrar do mestre. Só falou daquela sua irmã jurada.",
  ui_story_5020_50201201_25_dialog_content = "Fui criado pelo mestre.",
  ui_story_5020_50201201_26_dialog_content = "Devo obter Slice of Heaven para ajudar o mestre a derrotar Fujikumo.",
  ui_story_5020_50201201_27_dialog_content = "(Embora o mestre nunca me pediu para fazer nada por ela...)",
  ui_story_5020_50201201_28_dialog_content = "Mesmo que a mestra não tenha lhe contado seu plano de incendiar a cidade inteira?",
  ui_story_5020_50201201_29_dialog_content = "Hum...",
  ui_story_5020_50201201_30_dialog_content = "A Mestra tem seus motivos!",
  ui_story_5020_50201201_31_dialog_content = "Claro que ela sabe. Mas o quanto você realmente sabe sobre ela?",
  ui_story_5020_50201201_32_dialog_content = "?!",
  ui_story_5020_50201201_33_dialog_content = "Você... Você se lembra de algo sobre ela que eu não saiba?",
  ui_story_5020_50201201_34_dialog_content = "... Eu compartilhei tudo o que sei com você.",
  ui_story_5020_50201201_35_dialog_content = "Mas a pessoa que possuía Slice of Heaven certamente significava muito para dominar.",
  ui_story_5020_50201201_36_dialog_content = "...",
  ui_story_5020_50201201_37_dialog_content = "Sim... eu não entendo.",
  ui_story_5020_50201201_37X_dialog_content = "A Mestra se preocupa muito com a reputação dela... Por que ela sujaria as mãos?",
  ui_story_5020_50201201_38_dialog_content = "Heh. Além disso...",
  ui_story_5020_50201201_39_dialog_content = "Tenho certeza de que a sacerdotisa era uma pessoa muito importante. Eu posso dizer de minha memória.",
  ui_story_5020_50201201_40_dialog_content = "Tem tanta certeza assim?",
  ui_story_5020_50201201_41_dialog_content = "... Intuição!",
  ui_story_5020_50201201_42_dialog_content = "...",
  ui_story_5020_50201201_43_dialog_content = "O que há com o rosto? Minha intuição nunca está errada!",
  ui_story_5020_50201201_44_dialog_content = "Posso atestar isso.",
  ui_story_5020_50201201_45_dialog_content = "Goste-se ou não, vou levar Slice of Heaven.",
  ui_story_5020_50201201_46_dialog_content = "Tenho certeza que vai me ajudar a lembrar de mais coisas.",
  ui_story_5020_50201201_47_dialog_content = "Coisas sobre o mestre!",
  ui_story_5020_50201201_48_dialog_content = "De qualquer forma, eu não estou esperando nenhuma ajuda de você. Só não fique no meu caminho!",
  ui_story_5020_50201201_49_dialog_content = "...",
  ui_story_5020_50201201_50_dialog_content = "... ECA?",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>Swish...</color>",
  ui_story_5020_50201201_52_dialog_content = "Kunai!",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201201_54_dialog_content = "Yao, você precisaria de dez de vocês para me pegar de surpresa.",
  ui_story_5020_50201201_55_dialog_content = "Ele Ele! Isso mesmo!",
  ui_story_5020_50201201_55X_dialog_content = "Espere... Isso não soa bem...",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "Você pode não querer me ajudar, mas agora...",
  ui_story_5020_50201201_59_dialog_content = "Huh!",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201201_61_dialog_content = "Nossa prioridade deve ser livrar-se desses fantasmas cruéis!",
  ui_story_5020_50201201_62_dialog_content = "Heh. Como se eu precisasse de você para me dizer isso.",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>Gaaa...</anim>",
  ui_story_5020_50201202_2_dialog_content = "Hmm! Mole-mole!",
  ui_story_5020_50201202_3_dialog_content = "Fiquem alertas todos. Haverá mais fantasmas vagando dentro do cemitério.",
  ui_story_5020_50201202_4_dialog_content = "Vou esgueirar-me para dar uma olhada ao redor.",
  ui_story_5020_50201202_5_dialog_content = "Obrigada!",
  ui_story_5020_50201202_6_dialog_content = "Ninjutsu para sempre!",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>Swish... Swoosh...</color>",
  ui_story_5020_50201202_8_dialog_content = "Meu coração está batendo... Este silêncio mortal está me assustando.",
  ui_story_5020_50201202_9_dialog_content = "Não tenha medo. Não há problema que não possa ser resolvido com um soco!",
  ui_story_5020_50201202_10_dialog_content = "Hum?",
  ui_story_5020_50201202_11_dialog_content = "... Amemori?",
  ui_story_5020_50201202_12_dialog_content = "Alguma coisa não está certa...",
  ui_story_5020_50201202_13_dialog_content = "O que você está falando? Amemori... Você está bem?",
  ui_story_5020_50201202_14_dialog_content = "... Por favor, entrem, todos.",
  ui_story_5020_50201202_15_dialog_content = "Não há um único fantasma dentro do cemitério.",
  ui_story_5020_50201202_16_dialog_content = "O quê?",
  ui_story_5020_50201202_17_dialog_content = "Você pode baixar a guarda. Este lugar é absolutamente seguro.",
  ui_story_5020_50201202_18_dialog_content = "Tudo o que eu podia ouvir...",
  ui_story_5020_50201202_19_dialog_content = "Era apenas o som das flores de cerejeira caindo.",
  ui_story_5020_50201202_20_dialog_content = "Elas não florescem apenas como outras flores...",
  ui_story_5020_50201202_21_dialog_content = "Eles espalham suas pétalas lentamente, suportando a mistura de dor e alegria provocada por seu florescimento.",
  ui_story_5020_50201202_22_dialog_content = "E quando chega a hora, eles silenciosamente murcham em silêncio.",
  ui_story_5020_50201202_23_dialog_content = "As flores de cerejeira suportam tudo pacientemente. Agora eu entendo porque o mestre os ama tanto.",
  ui_story_5020_50201202_24_dialog_content = "Oh, uau... Meu guia não mencionou nada disso!",
  ui_story_5020_50201202_25_dialog_content = "Não sei porque, mas fico triste em pensar nisso...",
  ui_story_5020_50201202_26_dialog_content = "Hum... Isso é estranho...",
  ui_story_5020_50201202_27_dialog_content = "Afinal, este lugar não parece deserto...",
  ui_story_5020_50201202_28_dialog_content = "Olha, PlayerName!",
  ui_story_5020_50201202_29_dialog_content = "Ah...",
  ui_story_5020_50201202_30_dialog_content = "Alguém abriu caminho nas pétalas de cerejeira caídas.",
  ui_story_5020_50201202_31_dialog_content = "... Alguém esteve aqui antes de nós?",
  ui_story_5020_50201202_32_dialog_content = "Ah não! Pedaço de céu...",
  ui_story_5020_50201202_33_dialog_content = "Ah...",
  ui_story_5020_50201202_34_dialog_content = "Uau! Isso é...",
  ui_story_5020_50201202_35_dialog_content = "Não é à toa que é chamada de lendária lâmina matadora de fantasmas...",
  ui_story_5020_50201202_36_dialog_content = "Sua curva é suave... E a lâmina é um puro clássico...",
  ui_story_5020_50201202_37_dialog_content = "Mesmo depois de tantos anos, ainda está em perfeitas condições...",
  ui_story_5020_50201202_38_dialog_content = "Mas quem fez tudo isso?",
  ui_story_5020_50201202_39_dialog_content = "A forma como o Slice of Heaven é colocado…",
  ui_story_5020_50201202_40_dialog_content = "Parece algum tipo de oferta!",
  ui_story_5020_50201202_41_dialog_content = "Ah! PlayerName, Veja!",
  ui_story_5020_50201202_42_dialog_content = "Há algo sob Slice of Heaven…",
  ui_story_5020_50201202_43_dialog_content = "... Deixe-me dar uma olhada primeiro.",
  ui_story_5020_50201202_44_dialog_content = "Embora não seja provável que alguém arme uma armadilha aqui, é melhor prevenir do que remediar...",
  ui_story_5020_50201202_45_dialog_content = "Uau! O que você está fazendo?",
  ui_story_5020_50201202_46_dialog_content = "...?",
  ui_story_5020_50201202_47_dialog_content = "Quem você pensa que é para empunhar Slice of Heaven?",
  ui_story_5020_50201202_48_dialog_content = "... Por favor. Não tenho tempo para isso agora.",
  ui_story_5020_50201202_49_dialog_content = "Ei, PlayerName!",
  ui_story_5020_50201202_50_dialog_content = "Que? Por favor, deixe-me fora do seu argumento...",
  ui_story_5020_50201202_51_dialog_content = "Você vai pegar.",
  ui_story_5020_50201202_52_dialog_content = "E-Eu?",
  ui_story_5020_50201202_53_dialog_content = "...",
  ui_story_5020_50201202_54_dialog_content = "Se isso vai fechar Yao para cima, eu estou bem com isso.",
  ui_story_5020_50201202_55_dialog_content = "PlayerName, por favor, não perca meu tempo.",
  ui_story_5020_50201202_56_dialog_content = "... Entendo.",
  ui_story_5020_50201202_57_dialog_content = "Hum?",
  ui_story_5020_50201202_58_dialog_content = "Aqui...",
  ui_story_5020_50201202_59_dialog_content = "Aquela coisa ao lado do Slice of Heaven é...",
  ui_story_5020_50201202_60_dialog_content = "UMA... <color=#FFB400>caderno</color>?",
  ui_story_5020_50201202_61_dialog_content = "Isso pertence a...",
  ui_story_5020_50201202_62_dialog_content = "... <color=#FFB400>Tsuki</color>?",
  ui_story_5020_50201202_63_dialog_content = "?!",
  ui_story_5020_50201202_64_dialog_content = "... Esse é o nome dela.",
  ui_story_5020_50201202_65_dialog_content = "Esse é o caderno da sacerdotisa anterior.",
  ui_story_5020_50201202_66_dialog_content = "Parece estar em perfeito estado. Aposto que não está no cemitério há muito tempo.",
  ui_story_5020_50201202_67_dialog_content = "O último visitante pode ter deixado aqui.",
  ui_story_5020_50201202_68_dialog_content = "Quem diabos veio aqui antes de nós?",
  ui_story_5020_50201202_69_dialog_content = "...",
  ui_story_5020_50201202_70_dialog_content = "não posso ter certeza...",
  ui_story_5020_50201202_71_dialog_content = "Quem quer que seja essa pessoa, há um vínculo estreito entre ele e a sacerdotisa anterior.",
  ui_story_5020_50201202_72_dialog_content = "E este caderno...",
  ui_story_5020_50201202_73_dialog_content = "Nós vamos ler!",
  ui_story_5020_50201202_74_dialog_content = "Deve haver informações sobre o passado do mestre.",
  ui_story_5020_50201202_75_dialog_content = "Deve haver algo que eu esqueci!",
  ui_story_5020_50201202_76_dialog_content = "Vamos abri-lo com muito cuidado, PlayerName.",
  ui_story_5020_50201202_77_dialog_content = "Vire para a última entrada primeiro! Se apresse!",
  ui_story_5020_50201202_78_dialog_content = "Está bem, está bem. Aproxima-te...",
  ui_story_5020_50201301_1_dialog_content = "Sua Santidade a Sacerdotisa, está pronta?",
  ui_story_5020_50201301_2_dialog_content = "Sim... Mas, por favor, espere.",
  ui_story_5020_50201301_3_dialog_content = "Por favor, traga isso para o sacerdote do festival...",
  ui_story_5020_50201301_4_dialog_content = "Economize uma viagem para os servos, Tsuki.",
  ui_story_5020_50201301_5_dialog_content = "Eu tenho esse.",
  ui_story_5020_50201301_6_dialog_content = "Ah... Kubou-sama, pensei que você já estivesse no Festival Kasuga.",
  ui_story_5020_50201301_7_dialog_content = "... Há um pequeno problema no festival.",
  ui_story_5020_50201301_8_dialog_content = "Voltei para o espelho de nuvem.",
  ui_story_5020_50201301_9_dialog_content = "... O que aconteceu?",
  ui_story_5020_50201301_10_dialog_content = "Não se preocupe com isso. Concentre-se em sua cerimônia.",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>estrondo... estrondo...</color>",
  ui_story_5020_50201301_12_dialog_content = "Ahh!",
  ui_story_5020_50201301_13_dialog_content = "Que som é esse lá fora?",
  ui_story_5020_50201301_14_dialog_content = "Tsuki, não se preocupe...",
  ui_story_5020_50201301_15_dialog_content = "He...",
  ui_story_5020_50201301_16_dialog_content = "...",
  ui_story_5020_50201301_17_dialog_content = "Não é esta a traidora da Ilha das Nuvens, a Sacerdotisa?",
  ui_story_5020_50201301_18_dialog_content = "Olhe para você, toda vestida tão lindamente. Não quero ser chamado de valentão.",
  ui_story_5020_50201301_19_dialog_content = "Hmm... Mas o Festival Kasuga deste ano não vai acontecer.",
  ui_story_5020_50201301_20_dialog_content = "o que exatamente você quer?",
  ui_story_5020_50201301_21_dialog_content = "... Tsuki!",
  ui_story_5020_50201301_22_dialog_content = "Ah?",
  ui_story_5020_50201301_23_dialog_content = "Isso é muito direto...",
  ui_story_5020_50201301_24_dialog_content = "Pelo menos você é mais esperto que Fujikumo.",
  ui_story_5020_50201301_25_dialog_content = "Eu quero acabar com o Festival Kasuga.",
  ui_story_5020_50201301_26_dialog_content = "Qualquer coisa que promova as forças da ilha principal deve ser interrompida!",
  ui_story_5020_50201301_27_dialog_content = "Um ninguém ultrapassado. Tsuki, não perca seu tempo com eles...",
  ui_story_5020_50201301_28_dialog_content = "Entendi.",
  ui_story_5020_50201301_29_dialog_content = "Você não quer ver a cultura e os costumes da ilha principal se espalharem.",
  ui_story_5020_50201301_30_dialog_content = "Até certo ponto, sim!",
  ui_story_5020_50201301_31_dialog_content = "Mas entramos em uma nova era desde o dia em que Cloud Island abriu seu porto para a ilha principal.",
  ui_story_5020_50201301_32_dialog_content = "É perfeitamente normal que alguns de nós tenham se adaptado rapidamente às novas regras enquanto outros se recusam a aceitar a realidade.",
  ui_story_5020_50201301_33_dialog_content = "Se a própria Ilha das Nuvens pudesse ter uma voz para expressar seu próprio sentimento, tenho certeza que ficaria maravilhada com a rapidez com que as coisas mudaram...",
  ui_story_5020_50201301_34_dialog_content = "Mas enquanto Koufu-jou ainda estiver de pé, você e eu estamos compartilhando esta terra juntos.",
  ui_story_5020_50201301_35_dialog_content = "Você pode impedir que o Festival Kasuga aconteça. Você poderia se livrar de um general. Mas nada disso mudaria o futuro da ilha.",
  ui_story_5020_50201301_36_dialog_content = "...",
  ui_story_5020_50201301_37_dialog_content = "Em vez de acabar com o festival, aconselho a pensar...",
  ui_story_5020_50201301_38_dialog_content = "Como transformar o Festival Kasuga em sua própria celebração.",
  ui_story_5020_50201301_39_dialog_content = "...",
  ui_story_5020_50201301_40_dialog_content = "Sua Santidade a Sacerdotisa, a multidão não causou mais perturbação no festival.",
  ui_story_5020_50201301_41_dialog_content = "Heheh... Cadê o comandante deles?",
  ui_story_5020_50201301_42_dialog_content = "Você quer dizer a mulher Nagi?",
  ui_story_5020_50201301_43_dialog_content = "Seu paradeiro é desconhecido, mas todos ainda estão procurando por ela.",
  ui_story_5020_50201301_43X_dialog_content = "Se necessário, enviaremos mais tropas...",
  ui_story_5020_50201301_44_dialog_content = "Não será necessário.",
  ui_story_5020_50201301_45_dialog_content = "Se eles encenarem outra revolta, Kubou-sama ficaria perturbado.",
  ui_story_5020_50201301_46_dialog_content = "Deixe Nagi apreciar as flores de cerejeira no Festival Kasuga.",
  ui_story_5020_50201301_47_dialog_content = "Sua Santidade a Sacerdotisa... Por favor, perdoe-me se eu cruzei a linha...",
  ui_story_5020_50201301_48_dialog_content = "O que você disse antes parecia ter chateado Kubou-sama.",
  ui_story_5020_50201301_49_dialog_content = "Ah... Você está certo.",
  ui_story_5020_50201301_49X_dialog_content = "Kubou-sama ainda teria cuidado deles mesmo se eu saísse sem dizer nada.",
  ui_story_5020_50201301_50_dialog_content = "Acho que neste dia de alegria e celebração, eu não queria...",
  ui_story_5020_50201301_51_dialog_content = "Veja Kubou-sama ter uma matança.",
  ui_story_5020_50201301_52_dialog_content = "... Uma matança?",
  ui_story_5020_50201301_53_dialog_content = "Sim, era bastante óbvio quando Kubou-sama voltou ao castelo principal para o espelho de nuvens...",
  ui_story_5020_50201301_54_dialog_content = "Ele pretendia manipular fantasmas com o espelho de nuvem para suprimir esses rebeldes.",
  ui_story_5020_50201301_55_dialog_content = "Isso realmente não é uma coisa boa...",
  ui_story_5020_50201301_56_dialog_content = "O que está incomodando você? Você tem Slice of Heaven - a espada matadora de fantasmas!",
  ui_story_5020_50201301_57_dialog_content = "Você poderia matá-los todos depois.",
  ui_story_5020_50201301_58_dialog_content = "...",
  ui_story_5020_50201301_59_dialog_content = "Slice of Heaven e Cloud Mirror são ambos abençoados pelos deuses, um para expulsar espíritos malignos e o outro para exorcizar fantasmas...",
  ui_story_5020_50201301_60_dialog_content = "Não há problema em usá-los para a cerimônia, mas eles nunca devem ser ferramentas de dominação...",
  ui_story_5020_50201301_61_dialog_content = "Estou profundamente preocupado que outras forças possam ser desencadeadas... Algo que as pessoas comuns não conseguem lidar.",
  ui_story_5020_50201301_62_dialog_content = "Mas não é este o seu dever?",
  ui_story_5020_50201301_63_dialog_content = "Empunhar Slice of Heaven contra todos os espíritos malignos sempre foi o dever de uma sacerdotisa da ilha principal por gerações.",
  ui_story_5020_50201301_64_dialog_content = "Isso é como cutucar seu escudo com sua própria lança.",
  ui_story_5020_50201301_65_dialog_content = "Slice of Heaven mata, e o Cloud Mirror os traz de volta à vida...",
  ui_story_5020_50201301_66_dialog_content = "Quando essas duas forças estão em equilíbrio, a vontade do portador torna-se extremamente importante.",
  ui_story_5020_50201301_67_dialog_content = "Mas eu não posso mudar a mente de Kubou-sama de jeito nenhum...",
  ui_story_5020_50201301_68_dialog_content = "Sou apenas mais uma ferramenta para ajudar a Cloud Island a progredir em direção a uma paz duradoura.",
  ui_story_5020_50201301_69_dialog_content = "Sua Santidade a Sacerdotisa... eu...",
  ui_story_5020_50201301_70_dialog_content = "Acho que não estou seguindo!",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_72_dialog_content = "Heheh. Veja! Kubou-sama está em um palanquim adornado com tantos sinos!",
  ui_story_5020_50201301_73_dialog_content = "Ah... Kubou-sama!",
  ui_story_5020_50201301_74_dialog_content = "Sua Santidade a Sacerdotisa, se você puder me dar licença... eu devo ir e proteger Kubou-sama!",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_76_dialog_content = "Não me persiga! Não!",
  ui_story_5020_50201301_77_dialog_content = "Ufa... Garota má. Devolva o Kagura Bell para Tsuki!",
  ui_story_5020_50201301_78_dialog_content = "Irmã Tsuki, persiga-me! Eu devolvo se você puder me pegar!",
  ui_story_5020_50201301_79_dialog_content = "Você... Quantas vezes eu tenho que te dizer? Você não pode se dirigir a Sua Santidade pelo seu nome pessoal!",
  ui_story_5020_50201301_80_dialog_content = "Tudo bem, Irmã Tsuki!",
  ui_story_5020_50201301_81_dialog_content = "Não se preocupe com isso, Nagi. Ela é apenas uma criança.",
  ui_story_5020_50201301_82_dialog_content = "Yao só me chama de irmã porque gosta de mim.",
  ui_story_5020_50201301_83_dialog_content = "... Mas você gosta de uma irmã para mim. Yao é seu filho adotivo.",
  ui_story_5020_50201301_84_dialog_content = "Se ela também te chama de irmã, o que isso faz de mim?",
  ui_story_5020_50201301_85_dialog_content = "Heheheh.",
  ui_story_5020_50201301_86_dialog_content = "Não é engraçado!",
  ui_story_5020_50201301_87_dialog_content = "Multar. Eu sei Yao é safado, mas Amemori é uma boa menina.",
  ui_story_5020_50201301_88_dialog_content = "Eu pedi para você me ajudar a cuidar dos dois e você virou Amemori em uma versão em miniatura de você.",
  ui_story_5020_50201301_89_dialog_content = "Hmm... Ela é realmente talentosa.",
  ui_story_5020_50201301_90_dialog_content = "Não posso deixar de lhe ensinar algumas coisas.",
  ui_story_5020_50201301_91_dialog_content = "... Nagi!",
  ui_story_5020_50201301_92_dialog_content = "Não se preocupe. Não vou ensinar nada disso a eles sem sua permissão.",
  ui_story_5020_50201301_93_dialog_content = "Além disso, eu acho Amemori já está carregando muito peso nos ombros...",
  ui_story_5020_50201301_94_dialog_content = "Em uma idade tão jovem, ela já está propositalmente agindo como severamente fria e apática...",
  ui_story_5020_50201301_95_dialog_content = "Eu sei com certeza que ela ainda não está na idade de reprimir sentimentos.",
  ui_story_5020_50201301_96_dialog_content = "De fato.",
  ui_story_5020_50201301_97_dialog_content = "Desde que os acolhi, os tenho criado como se fossem meus.",
  ui_story_5020_50201301_98_dialog_content = "Ainda assim ela não se aproxima de mim e não mostra interesse em brincar comigo Yao...",
  ui_story_5020_50201301_99_dialog_content = "Mas por alguma razão, ela realmente gosta de você, Nagi.",
  ui_story_5020_50201301_100_dialog_content = "Ela gosta de mim?",
  ui_story_5020_50201301_101_dialog_content = "sim. Ela não fala muito, mas adora te seguir e imitar tudo que você faz...",
  ui_story_5020_50201301_102_dialog_content = "Veja! Até a flor favorita dela é a mesma que a sua.",
  ui_story_5020_50201301_103_dialog_content = "Que tipo de garotinha pode entender a beleza das flores de cerejeira caindo?",
  ui_story_5020_50201301_104_dialog_content = "Hã?",
  ui_story_5020_50201301_105_dialog_content = "Ah... As cerejeiras já estão caindo.",
  ui_story_5020_50201301_106_dialog_content = "<size=33>... O tempo voa. Em breve partirei para a ilha principal.</size>",
  ui_story_5020_50201301_107_dialog_content = "O que foi isso?",
  ui_story_5020_50201301_108_dialog_content = "Nada.",
  ui_story_5020_50201301_109_dialog_content = "Nagi, tenho que deixar a Ilha das Nuvens por algum tempo.",
  ui_story_5020_50201301_110_dialog_content = "Quando eu voltar, você será o verdadeiro comandante das forças locais.",
  ui_story_5020_50201301_111_dialog_content = "Onde você está indo? E para quê? Por que você não disse nada antes?",
  ui_story_5020_50201301_112_dialog_content = "... É por isso que você está confiando Amemori e Yao aos meus cuidados?",
  ui_story_5020_50201301_113_dialog_content = "Heheh... Eles deixaram sua cabeça e rosto sujos de sujeira...",
  ui_story_5020_50201301_114_dialog_content = "Mas você não me odeia, não é?",
  ui_story_5020_50201301_115_dialog_content = "... Claro que não!",
  ui_story_5020_50201301_116_dialog_content = "Isso é realmente lindo...",
  ui_story_5020_50201301_117_dialog_content = "Espero que as coisas continuem assim...",
  ui_story_5020_50201301_118_dialog_content = "Irmã! O que está acontecendo? Por que eu nunca...",
  ui_story_5020_50201301_119_dialog_content = "Não se preocupe.",
  ui_story_5020_50201301_120_dialog_content = "Não posso lhe dizer muito no momento. Mas confie em mim. Tenho meus motivos.",
  ui_story_5020_50201301_121_dialog_content = "Quando eu estiver fora, você pode ensinar a eles a música que costumávamos cantar.",
  ui_story_5020_50201301_122_dialog_content = "Vamos. Não me diga que você esqueceu!",
  ui_story_5020_50201301_123_dialog_content = "Nunca!",
  ui_story_5020_50201301_124_dialog_content = "Essa música... É perfeita para esta temporada.",
  ui_story_5020_50201301_125_dialog_content = "Escolha uma flor vermelha para a senhora...",
  ui_story_5020_50201301_126_dialog_content = "Pétalas caem como a neve em um pedaço de jade...",
  ui_story_5020_50201301_127_dialog_content = "Nagi, realmente há uma pétala de cereja em sua testa.",
  ui_story_5020_50201301_128_dialog_content = "Ah... Irmã, me ajude...",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201401_1_dialog_content = "...",
  ui_story_5020_50201401_2_dialog_content = "...",
  ui_story_5020_50201401_3_dialog_content = "A irmã sacerdotisa registrou tal história.",
  ui_story_5020_50201401_4_dialog_content = "Agora eu entendo porque me senti tão perto de Rinne no momento em que a vi...",
  ui_story_5020_50201401_5_dialog_content = "Tudo faz sentido agora.",
  ui_story_5020_50201401_6_dialog_content = "Uma sacerdotisa que você parece ter conhecido antes... E os sinos familiares tocando profundamente em sua cabeça...",
  ui_story_5020_50201401_7_dialog_content = "Esta é a memória perdida de Yao!",
  ui_story_5020_50201401_8_dialog_content = "Mas eu...",
  ui_story_5020_50201401_9_dialog_content = "... Yao?",
  ui_story_5020_50201401_10_dialog_content = "Meu coração está doendo...",
  ui_story_5020_50201401_11_dialog_content = "Não deveria ser uma coisa feliz quando se encontra sua memória perdida?",
  ui_story_5020_50201401_12_dialog_content = "Ainda não consigo entender por que a decisão do mestre.",
  ui_story_5020_50201401_13_dialog_content = "Mas o que eu faria se estivesse na posição de mestre?",
  ui_story_5020_50201401_14_dialog_content = "A sacerdotisa que retornou da ilha principal foi amplamente considerada uma traidora imperdoável da Ilha das Nuvens...",
  ui_story_5020_50201401_15_dialog_content = "Era para ser uma escolha simples entre o bem e o mal, mas...",
  ui_story_5020_50201401_16_dialog_content = "Por que estou ainda mais triste do que o mestre naquela época?",
  ui_story_5020_50201401_17_dialog_content = "... Muitas coisas neste mundo não são tão simples como preto ou branco.",
  ui_story_5020_50201401_18_dialog_content = "É o mesmo de Astra para o Extremo Oriente...",
  ui_story_5020_50201401_19_dialog_content = "As pessoas têm diferentes posições e crenças e experimentam o desamparo por várias razões.",
  ui_story_5020_50201401_20_dialog_content = "... É assim mesmo?",
  ui_story_5020_50201401_21_dialog_content = "E no final da história...",
  ui_story_5020_50201401_22_dialog_content = "Deixe-me ver... Deve ser por aqui...",
  ui_story_5020_50201401_22X_dialog_content = "Hã?",
  ui_story_5020_50201401_23_dialog_content = "Há um <color=#FFB400>carta</color> entre as páginas!",
  ui_story_5020_50201401_24_dialog_content = "Ah. Ainda está selado.",
  ui_story_5020_50201401_25_dialog_content = "Para a próxima sacerdotisa...",
  ui_story_5020_50201401_26_dialog_content = "Uau! A sacerdotisa partiu Rinne uma letra!",
  ui_story_5020_50201401_27_dialog_content = "PlayerName, vamos trazer isso para Rinne.",
  ui_story_5020_50201401_28_dialog_content = "Hmm... Você vê, a passagem que eu estou procurando está bem aqui no início da nota!",
  ui_story_5020_50201401_29_dialog_content = "O que a irmã sacerdotisa quis dizer quando se despediu do mestre antes de sua partida?",
  ui_story_5020_50201401_30_dialog_content = "Ela já sabia que se tornaria uma sacerdotisa?",
  ui_story_5020_50201401_31_dialog_content = "Ela já previu um futuro cheio de ódio do mestre e de todos os residentes da Ilha das Nuvens?",
  ui_story_5020_50201401_32_dialog_content = "Afinal... Foi sua própria escolha.",
  ui_story_5020_50201401_33_dialog_content = "Foi realmente sua própria escolha?",
  ui_story_5020_50201401_34_dialog_content = "Falando nisso... Hum...",
  ui_story_5020_50201401_35_dialog_content = "Amemori! Eu sabia que a sacerdotisa não era má pessoa!",
  ui_story_5020_50201401_36_dialog_content = "Ela era uma guerreira que realmente se importava com a paz e a segurança de Cloud Island!",
  ui_story_5020_50201401_37_dialog_content = "... Amemori?",
  ui_story_5020_50201401_38_dialog_content = "Amemori, você está chorando?",
  ui_story_5020_50201401_39_dialog_content = "Não.",
  ui_story_5020_50201401_40_dialog_content = "(Por favor, não exponha sua tristeza e tristeza tão sem rodeios!)",
  ui_story_5020_50201401_41_dialog_content = "Eu nunca vi o mestre desse ângulo antes...",
  ui_story_5020_50201401_42_dialog_content = "Eu nunca ouvi o mestre falar sobre mim na frente dos outros.",
  ui_story_5020_50201401_43_dialog_content = "Eu pensei que eu era apenas como mestre.",
  ui_story_5020_50201401_44_dialog_content = "Até o Wisp fez essas observações.",
  ui_story_5020_50201401_45_dialog_content = "Mas apenas o mestre pode comentar sobre isso.",
  ui_story_5020_50201401_46_dialog_content = "Depois de tantos anos de cultivo, a mestra temperou seu corpo e coração com mais força do que o de Fujikumo...",
  ui_story_5020_50201401_47_dialog_content = "Ela era tão forte que nenhuma força bruta poderia prejudicá-la, incluindo o soco pesado de Fujikumo...",
  ui_story_5020_50201401_48_dialog_content = "Ela enfrentou todos os golpes, admiração e fofocas...",
  ui_story_5020_50201401_49_dialog_content = "Mas ela não suportou o empurrão suave do Tsuki moribundo, que a enviou para o solo selado.",
  ui_story_5020_50201401_50_dialog_content = "Quando o mestre me viu novamente uma década depois, as primeiras palavras que ela disse...",
  ui_story_5020_50201401_51_dialog_content = "Às vezes, você finge ser tão legal e implacável... E ainda assim, você não consegue superar sua compaixão e covardia com os outros.",
  ui_story_5020_50201401_52_dialog_content = "Para viver em um mundo como este, é melhor você abandonar suas emoções em sua totalidade.",
  ui_story_5020_50201401_53_dialog_content = "Acho que as palavras foram para ela também.",
  ui_story_5020_50201401_54_dialog_content = "... O que você está tentando dizer? Claro que você não é o mesmo que mestre.",
  ui_story_5020_50201401_55_dialog_content = "Eu já sabia disso quando vi o mestre pela primeira vez.",
  ui_story_5020_50201401_56_dialog_content = "O quê?",
  ui_story_5020_50201401_57_dialog_content = "Deixe-me dizer-lhe mais. Tosse...",
  ui_story_5020_50201401_58_dialog_content = "A Mestra sabe claramente o que ela quer.",
  ui_story_5020_50201401_59_dialog_content = "Não apenas mestre. Assim como a irmã sacerdotisa...",
  ui_story_5020_50201401_60_dialog_content = "Ambos sabiam o que deveriam fazer no momento.",
  ui_story_5020_50201401_61_dialog_content = "Então, Amemori... Se você deixasse de lado a influência do Mestre e toda a pressão que coloca sobre si mesmo...",
  ui_story_5020_50201401_62_dialog_content = "O que irá <color=#FFB400>sua escolha</color> estar?",
  ui_story_5020_50201401_63_dialog_content = "...?!",
  ui_story_5020_50201401_64_dialog_content = "Deixando tudo isso de lado, eu...",
  ui_story_5020_50201401_65_dialog_content = "Não sei mesmo.",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>Baque...</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>Baque... Baque!</color>",
  ui_story_5020_50201401_68_dialog_content = "Uau! Que som é esse?",
  ui_story_5020_50201401_69_dialog_content = "<color=#FFB400>Taiko</color>... Este é o taiko de Momo e Anzu!",
  ui_story_5020_50201401_70_dialog_content = "Mas por que? Koufu-jou já está em um estado tão caótico...",
  ui_story_5020_50201401_71_dialog_content = "É um sinal. Rinne Está em perigo!",
  ui_story_5020_50201401_72_dialog_content = "Rinne!",
  ui_story_5020_50201401_73_dialog_content = "Cadê ela?",
  ui_story_5020_50201401_74_dialog_content = "... Vou enviar o Wisp para ajudar!",
  ui_story_5020_50201401_75_dialog_content = "Acho que não precisaremos mais disso!",
  ui_story_5020_50201401_75X_dialog_content = "Rinne está com o Wisp desde Rinne nos deixou.",
  ui_story_5020_50201401_76_dialog_content = "Eu acho que eles estão lutando uma nova batalha juntos.",
  ui_story_5020_50201401_77_dialog_content = "Junto? Como isso aconteceu?",
  ui_story_5020_50201401_78_dialog_content = "Amemori... Às vezes, sua única escolha ainda é uma escolha.",
  ui_story_5020_50201401_79_dialog_content = "Neste momento crucial, você deve saber o que realmente quer fazer!",
  ui_story_5020_50201401_80_dialog_content = "...",
  ui_story_5020_50201401_81_dialog_content = "Em direção ao porto.",
  ui_story_5020_50201401_82_dialog_content = "Yao, me dê sua mão.",
  ui_story_5020_50201401_83_dialog_content = "Já que isso traz nossa memória de dez anos atrás, vamos usar isso para tirar uma conclusão.",
  ui_story_5020_50201401_84_dialog_content = "Hmm! Mentes brilhantes pensam igual!",
  ui_story_5020_50201401_85_dialog_content = "Vamos, seguindo o taiko. Em direção a <color=#FFB400>porta</color>!",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>Em uma rua na cidade do castelo de Koufu-jou</color>",
  ui_story_5020_50201401_87_dialog_content = "Pressa! Manter-se!",
  ui_story_5020_50201401_88_dialog_content = "Desça este rio e chegaremos ao porto.",
  ui_story_5020_50201401_89_dialog_content = "Se apresse! Devemos recuar rapidamente!",
  ui_story_5020_50201401_90_dialog_content = "As pessoas no porto irão levá-lo em segurança.",
  ui_story_5020_50201401_91_dialog_content = "Fuja do castelo principal de Koufu-jou, o mais longe que puder!",
  ui_story_5020_50201401_92_dialog_content = "Isso é loucura...",
  ui_story_5020_50201401_93_dialog_content = "As tropas do ex-comandante uniram forças com a sacerdotisa do general...",
  ui_story_5020_50201401_93X_dialog_content = "... Huh?!",
  ui_story_5020_50201401_94_dialog_content = "Minha bunda!",
  ui_story_5020_50201401_95_dialog_content = "Tome cuidado com o que você diz! Não será o cabo da próxima vez!",
  ui_story_5020_50201401_96_dialog_content = "Pai... Vamos com a irmã sacerdotisa! Todos nos encaram...",
  ui_story_5020_50201401_97_dialog_content = "O fogo ainda está furioso... eu não quero morrer...",
  ui_story_5020_50201401_98_dialog_content = "Por que devemos segui-la?",
  ui_story_5020_50201401_99_dialog_content = "Ela é uma traidora da ilha. Ela vai nos vender para a ilha principal!",
  ui_story_5020_50201401_100_dialog_content = "Isso significa que haverá uma centena de Fujikumos esperando para nos torturar?!",
  ui_story_5020_50201401_100X_dialog_content = "... Nãooo!!",
  ui_story_5020_50201401_101_dialog_content = "Ai... Errrr! Meu ombro...",
  ui_story_5020_50201401_102_dialog_content = "Pai!",
  ui_story_5020_50201401_103_dialog_content = "Seus lacaios armados! Você está evacuando moradores de Cloud Island ou ajudando a destruir nossa ilha?",
  ui_story_5020_50201401_104_dialog_content = "Hã?",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>Gaa... Gaaaah!!</anim>",
  ui_story_5020_50201401_106_dialog_content = "Fantasmas... Há fantasmas em Sakai...",
  ui_story_5020_50201401_107_dialog_content = "Fique com o grupo. Não entre em pânico!",
  ui_story_5020_50201401_108_dialog_content = "Sacerdotisa, você lidera o caminho. Eu trarei a retaguarda!",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "Irmãos, saquem suas armas!",
  ui_story_5020_50201401_113_dialog_content = "Pique esses espíritos imundos!",
  ui_story_5020_50201401_114_dialog_content = "Hyaah!",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>Perto do porto de Koufu-jou</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>Baque... Baque!</color>",
  ui_story_5020_50201501_3_dialog_content = "Tantas pessoas... Onde diabos está Rinne?",
  ui_story_5020_50201501_4_dialog_content = "Droga!",
  ui_story_5020_50201501_5_dialog_content = "Rinne!",
  ui_story_5020_50201501_6_dialog_content = "Rinne! Você pode me ouvir?",
  ui_story_5020_50201501_7_dialog_content = "... Yao?",
  ui_story_5020_50201501_8_dialog_content = "Eai!",
  ui_story_5020_50201501_9_dialog_content = "Ah! E Amemori, Vice, e PlayerName!",
  ui_story_5020_50201501_10_dialog_content = "Você ouviu o taiko!",
  ui_story_5020_50201501_11_dialog_content = "PlayerName tem orelhas afiadas! Viemos o mais rápido que pudemos.",
  ui_story_5020_50201501_12_dialog_content = "Como estão as coisas? Você está machucado?",
  ui_story_5020_50201501_13_dialog_content = "Estou bem. A maioria dos moradores de Koufu-jou foi evacuada.",
  ui_story_5020_50201501_14_dialog_content = "O Wisp saiu de barco com alguns civis...",
  ui_story_5020_50201501_15_dialog_content = "E você? Eles deram-lhe um tempo difícil?",
  ui_story_5020_50201501_16_dialog_content = "Hehe. É bom saber que você se importa comigo, Yao.",
  ui_story_5020_50201501_17_dialog_content = "Não se preocupe. Estou bem. Como estão todos?",
  ui_story_5020_50201501_18_dialog_content = "Tantos de nós juntos, nada de ruim poderia acontecer! PlayerName, rapidamente. Mostrar <color=#FFB400>isto</color> a ela!",
  ui_story_5020_50201501_19_dialog_content = "Hum?",
  ui_story_5020_50201501_20_dialog_content = "Isto? Ah! Eu me lembro agora.",
  ui_story_5020_50201501_21_dialog_content = "Rinne, Isto é para você.",
  ui_story_5020_50201501_22_dialog_content = "Ah! Uma carta em um caderno?",
  ui_story_5020_50201501_23_dialog_content = "Isto é para mim? Mas acho que não conheço ninguém com esse nome...",
  ui_story_5020_50201501_24_dialog_content = "Tsuki é a sacerdotisa anterior de Koufu-jou.",
  ui_story_5020_50201501_25_dialog_content = "... Entendo.",
  ui_story_5020_50201501_26_dialog_content = "Para a próxima sacerdotisa...",
  ui_story_5020_50201501_27_dialog_content = "Decido escrever algo enquanto espero.",
  ui_story_5020_50201501_28_dialog_content = "Sinto-me desconfortável com o futuro que não viverei para ver...",
  ui_story_5020_50201501_29_dialog_content = "Quanto mais penso, mais me preocupo com você, meu sucessor.",
  ui_story_5020_50201501_30_dialog_content = "Não é justo você assumir essa posição sem um mentor sênior.",
  ui_story_5020_50201501_31_dialog_content = "Já existem tantas coisas injustas e injustas que vêm com esse status de sacerdotisa.",
  ui_story_5020_50201501_32_dialog_content = "Não sei em que temporada você vai abrir esta carta na Ilha das Nuvens...",
  ui_story_5020_50201501_33_dialog_content = "A Ilha das Nuvens é bem conhecida por suas flores de cerejeira que florescem como nuvens rosadas—",
  ui_story_5020_50201501_33X_dialog_content = "E eles caem como neve—",
  ui_story_5020_50201501_34_dialog_content = "Para a maioria dos moradores de Cloud Island, nós, sacerdotisas, somos lindas, mas transitórias, assim como as flores de cerejeira.",
  ui_story_5020_50201501_35_dialog_content = "Mas para mim, a sacerdotisa de Cloud Island deve brilhar como o sol, sozinha, mas perfeitamente esplêndida, guardando esta terra...",
  ui_story_5020_50201501_36_dialog_content = "Enquanto lutamos contra a noite escura, não podemos deixar que as nuvens da ilha principal bloqueiem nossos raios.",
  ui_story_5020_50201501_37_dialog_content = "No entanto, se você já aprendeu sobre esta parte da história, eu provavelmente deveria lhe contar algumas coisas, de uma sacerdotisa para outra.",
  ui_story_5020_50201501_38_dialog_content = "Kubou-sama não é uma nuvem escura que bloqueia o céu azul, pelo menos não na minha opinião.",
  ui_story_5020_50201501_39_dialog_content = "Ele não está tão longe, mais como um guarda-chuva acima de nossas cabeças.",
  ui_story_5020_50201501_40_dialog_content = "Ele não é um bom homem e não pode dizer que fez muitas coisas boas. Na verdade, ele trouxe inúmeros sofrimentos e infortúnios para esta cidade...",
  ui_story_5020_50201501_41_dialog_content = "Mas este já é o melhor futuro que Koufu-jou pode ter, e ele lutou muito por isso.",
  ui_story_5020_50201501_42_dialog_content = "Por favor, perdoe-me por escrever-lhe esta carta como um completo estranho.",
  ui_story_5020_50201501_43_dialog_content = "Eu hesitei por algum tempo sobre o destinatário...",
  ui_story_5020_50201501_44_dialog_content = "Afinal, sei que será uma despedida pesada e dolorosa.",
  ui_story_5020_50201501_45_dialog_content = "Decidi mantê-lo lacrado até um dia no futuro.",
  ui_story_5020_50201501_46_dialog_content = "Por favor, viva como o sol, com meus melhores votos.",
  ui_story_5020_50201501_47_dialog_content = "Seu antecessor.",
  ui_story_5020_50201501_48_dialog_content = "...",
  ui_story_5020_50201501_49_dialog_content = "Isso é mágico...",
  ui_story_5020_50201501_50_dialog_content = "A sacerdotisa de Koufu-jou está fadada a ficar sozinha.",
  ui_story_5020_50201501_51_dialog_content = "Mas sinto que ganhei força com o veterano...",
  ui_story_5020_50201501_52_dialog_content = "Todas as sacerdotisas de Koufu-jou costumavam ficar sozinhas...",
  ui_story_5020_50201501_53_dialog_content = "Mas Rinne, você mudou isso. Você não vê?",
  ui_story_5020_50201501_54_dialog_content = "Eu?",
  ui_story_5020_50201501_55_dialog_content = "Sua Santidade a Sacerdotisa... Por favor, aceite isso antes de embarcarmos no navio...",
  ui_story_5020_50201501_56_dialog_content = "Essa bolsa inteira é para a irmã!",
  ui_story_5020_50201501_57_dialog_content = "É um saco de <color=#FFB400>fukumame</color> para manter os demônios fora e trazer boa sorte?",
  ui_story_5020_50201501_58_dialog_content = "Estes são tudo o que temos. Toda a nossa boa sorte está embalada neste saco!",
  ui_story_5020_50201501_59_dialog_content = "Irmã, espero que esses feijões possam ajudá-la a vencer esses bandidos!",
  ui_story_5020_50201501_60_dialog_content = "Espero que nossa boa sorte possa mantê-lo seguro...",
  ui_story_5020_50201501_61_dialog_content = "Sua Santidade, a Sacerdotisa, guarde esses grãos e esteja seguro na batalha.",
  ui_story_5020_50201501_62_dialog_content = "Eu...",
  ui_story_5020_50201501_63_dialog_content = "Por favor, confie em mim!",
  ui_story_5020_50201501_64_dialog_content = "Sacerdotisa, outro barco está pronto. Devemos ser capazes de atender a todos desta vez.",
  ui_story_5020_50201501_65_dialog_content = "Obrigada. Por favor, mantenha-os seguros.",
  ui_story_5020_50201501_66_dialog_content = "Amemori, você tem estado muito quieto.",
  ui_story_5020_50201501_67_dialog_content = "Faça algo antes do Wisp desertar para um novo comandante.",
  ui_story_5020_50201501_68_dialog_content = "... não tenho muito o que dizer Rinne.",
  ui_story_5020_50201501_69_dialog_content = "Ai... Isso é frio.",
  ui_story_5020_50201501_70_dialog_content = "Amemori, faz algum tempo. Você está com saudades de mim?",
  ui_story_5020_50201501_71_dialog_content = "Não faz muito tempo.",
  ui_story_5020_50201501_72_dialog_content = "Não é apropriado falar sobre os velhos tempos em uma situação tão terrível!",
  ui_story_5020_50201501_73_dialog_content = "Ah! Comandante!",
  ui_story_5020_50201501_74_dialog_content = "<size=45>Senhora Amemori!</size>",
  ui_story_5020_50201501_75_dialog_content = "Não me chame de comandante!",
  ui_story_5020_50201501_76_dialog_content = "Comandante Amemori, você treinou o Wisp muito bem.",
  ui_story_5020_50201501_77_dialog_content = "Trabalhamos muito bem juntos.",
  ui_story_5020_50201501_78_dialog_content = "Uau, vamos lá! Rinne e Amemori deve ter um confronto adequado!",
  ui_story_5020_50201501_79_dialog_content = "A luta pela nave comandante do Wisp começou!",
  ui_story_5020_50201501_80_dialog_content = "Ai! Minha cabeça!",
  ui_story_5020_50201501_81_dialog_content = "Que tipo de piada é essa?",
  ui_story_5020_50201501_82_dialog_content = "OK. Chega de brincadeira.",
  ui_story_5020_50201501_83_dialog_content = "Os fantasmas estão se movendo rapidamente. Não vai demorar muito para chegar ao porto.",
  ui_story_5020_50201501_84_dialog_content = "PlayerName, vamos nos separar e nos preparar antes que eles cheguem lá!",
  ui_story_5020_50201501_85_dialog_content = "Então...",
  ui_story_5020_50201501_86_dialog_content = "Amemori e Yao conduzirá o Wisp para proteger a passagem entre Sakai e o porto.",
  ui_story_5020_50201501_87_dialog_content = "Vice e PlayerName, por favor, fique aqui para cuidar de qualquer um que consiga passar pelo desfiladeiro.",
  ui_story_5020_50201501_88_dialog_content = "Vou enfrentar aqueles samurais no porto.",
  ui_story_5020_50201501_89_dialog_content = "Sozinho? Tem certeza?",
  ui_story_5020_50201501_90_dialog_content = "Você realmente acha que este é um bom momento para questionar minhas habilidades, PlayerName?",
  ui_story_5020_50201501_91_dialog_content = "(Rinne realmente mudou...)",
  ui_story_5020_50201501_92_dialog_content = "Vamos indo!",
  ui_story_5020_50201501_93_dialog_content = "Sim!",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201501_95_dialog_content = "Eles estão chegando perto.",
  ui_story_5020_50201501_96_dialog_content = "Hmm! Meus punhos não podem esperar!",
  ui_story_5020_50201501_97_dialog_content = "Devo partir para o porto agora.",
  ui_story_5020_50201501_98_dialog_content = "Estejam seguros, todos. Vamos superar essa guerra juntos!",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>Entrada para o porto de Koufu-jou</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>Sss... Sss...</color>",
  ui_story_5020_50201601_3_dialog_content = "Huff... Huff...",
  ui_story_5020_50201601_4_dialog_content = "Urgh... Tosse!",
  ui_story_5020_50201601_5_dialog_content = "Senhora Amemori!",
  ui_story_5020_50201601_6_dialog_content = "Ela está ferida! Cubra o retiro dela!",
  ui_story_5020_50201601_7_dialog_content = "Não há necessidade. Você continua em direção a Sakai...",
  ui_story_5020_50201601_8_dialog_content = "Ficar parado é um convite ao fracasso.",
  ui_story_5020_50201601_9_dialog_content = "Mantenha as forças juntas. Não mostre piedade ao inimigo.",
  ui_story_5020_50201601_10_dialog_content = "Se você encontrar alguém que seja demais para você lidar, deixe-o escapar…",
  ui_story_5020_50201601_11_dialog_content = "Nosso Slice of Heaven vai acabar com todos eles!",
  ui_story_5020_50201601_12_dialog_content = "mas senhora Amemori, você já está...",
  ui_story_5020_50201601_13_dialog_content = "Me fiz claro?!",
  ui_story_5020_50201601_14_dialog_content = "Sim!",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>Bate, baque, baque...</color>",
  ui_story_5020_50201601_16_dialog_content = "Huff... Huff...",
  ui_story_5020_50201601_17_dialog_content = "Atenção! Amemori—",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201601_19_dialog_content = "Ninjutsu - Sem Rastros... Urgh...",
  ui_story_5020_50201601_20_dialog_content = "Amemori!",
  ui_story_5020_50201601_21_dialog_content = "Eu deveria ter sido mais cuidadoso.",
  ui_story_5020_50201601_22_dialog_content = "Yao... Venha e fique de costas comigo.",
  ui_story_5020_50201601_23_dialog_content = "Certo! Mas por que...",
  ui_story_5020_50201601_24_dialog_content = "Ah... entendi...",
  ui_story_5020_50201601_25_dialog_content = "Os Lins me ensinaram que um verdadeiro guerreiro sempre enfrenta o inimigo de frente.",
  ui_story_5020_50201601_26_dialog_content = "Os Ninjas usam a mesma estratégia?",
  ui_story_5020_50201601_27_dialog_content = "Virar as costas para o seu inimigo é um grande não-não.",
  ui_story_5020_50201601_28_dialog_content = "Ninjas não temem ataques furtivos de qualquer direção.",
  ui_story_5020_50201601_29_dialog_content = "No entanto, agora eu não sou tão forte quanto eu gostaria de ser.",
  ui_story_5020_50201601_30_dialog_content = "Posso confiar em você para cuidar das minhas costas?",
  ui_story_5020_50201601_31_dialog_content = "Ah! Você ainda tem que perguntar?",
  ui_story_5020_50201601_32_dialog_content = "Mesmo se você não estivesse ferido... Mesmo se não estivéssemos ligados pela Rebelião e Ryojin...",
  ui_story_5020_50201601_33_dialog_content = "Você é minha irmã de armas...",
  ui_story_5020_50201601_34_dialog_content = "E eu vou te ajudar com tudo que eu tenho!",
  ui_story_5020_50201601_35_dialog_content = "Heheh... Bem dito.",
  ui_story_5020_50201601_36_dialog_content = "Mais inimigos estão chegando...",
  ui_story_5020_50201601_37_dialog_content = "Preparar, <color=#FFB400>júnior</color>?",
  ui_story_5020_50201601_38_dialog_content = "Muito! Eu tenho muita força sobrando!",
  ui_story_5020_50201601_39_dialog_content = "Huh!",
  ui_story_5020_50201601_40_dialog_content = "Haaaa... ha...",
  ui_story_5020_50201601_41_dialog_content = "Amemori, você deve aguentar aí...",
  ui_story_5020_50201601_42_dialog_content = "Huff... estou...",
  ui_story_5020_50201601_43_dialog_content = "... Yao, pegue a Fatia do Céu!",
  ui_story_5020_50201601_44_dialog_content = "Alguma coisa não está certa...",
  ui_story_5020_50201601_45_dialog_content = "Vamos!",
  ui_story_5020_50201601_46_dialog_content = "O que não está certo? O que deveríamos fazer?",
  ui_story_5020_50201601_47_dialog_content = "... Vamos em direção a Sakai. Temos que ganhar tempo para Rinne e os civis no porto.",
  ui_story_5020_50201601_48_dialog_content = "Observe seus arredores.",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_51_dialog_content = "(O Wisp está lutando contra alguns fantasmas menores na direção das 2 horas...)",
  ui_story_5020_50201601_52_dialog_content = "(E há passos humanos às 10 horas...)",
  ui_story_5020_50201601_53_dialog_content = "(Seis pássaros decolaram na floresta às 7 horas...)",
  ui_story_5020_50201601_54_dialog_content = "(Estranho, não consigo ouvir nenhum som incomum. O que está acontecendo?)",
  ui_story_5020_50201601_55_dialog_content = "...",
  ui_story_5020_50201601_56_dialog_content = "Uau! Amemori, lá!",
  ui_story_5020_50201601_57_dialog_content = "Essa figura...",
  ui_story_5020_50201601_58_dialog_content = "Um residente de Koufu deixado para trás?",
  ui_story_5020_50201601_59_dialog_content = "Mas como ainda poderia haver alguém na cidade?",
  ui_story_5020_50201601_60_dialog_content = "... Yao! Tome cuidado!",
  ui_story_5020_50201601_61_dialog_content = "O quê?",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>... Ga...</anim>",
  ui_story_5020_50201601_63_dialog_content = "O que ele disse?",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>Rugido!</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "Isso é… Fujikumo?!",
  ui_story_5020_50201601_67_dialog_content = "... Não!",
  ui_story_5020_50201601_68_dialog_content = "(Como Fujikumo escapou do mestre e chegou ao porto inteiro?)",
  ui_story_5020_50201601_69_dialog_content = "(Poderia ser mestre...)",
  ui_story_5020_50201601_70_dialog_content = "O que... Que tipo de monstro é esse?",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>Deitar...</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>Deite-o...</anim>",
  ui_story_5020_50201601_73_dialog_content = "Yao, segure firme no Slice of Heaven...",
  ui_story_5020_50201601_74_dialog_content = "Podemos não ganhar...",
  ui_story_5020_50201601_75_dialog_content = "Mas não podemos entregar Slice of Heaven para ninguém!",
  ui_story_5020_50201601_76_dialog_content = "Onde está meu mestre?!",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>Mate...</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>Mate...</anim>",
  ui_story_5020_50201601_79_dialog_content = "O quê?",
  ui_story_5020_50201601_80_dialog_content = "...",
  ui_story_5020_50201601_81_dialog_content = "Eu vou matar você! Ninjutsu - Trace...",
  ui_story_5020_50201601_82_dialog_content = "Urgh... *Tosse*",
  ui_story_5020_50201601_83_dialog_content = "(... O que mais posso fazer? É isso...?)",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>Swish... Smack!</color>",
  ui_story_5020_50201601_85_dialog_content = "Torrente Rápida!",
  ui_story_5020_50201601_86_dialog_content = "Barreira... Implante!",
  ui_story_5020_50201601_87_dialog_content = "Vocês caras!",
  ui_story_5020_50201601_88_dialog_content = "Vocês dois lutaram muito!",
  ui_story_5020_50201601_89_dialog_content = "Tudo limpo aqui! Agora, vamos focar na defesa do passe!",
  ui_story_5020_50201601_90_dialog_content = "Esconda-se atrás da barreira. Deixe-me...",
  ui_story_5020_50201601_91_dialog_content = "Ah...",
  ui_story_5020_50201601_92_dialog_content = "Bom...",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>Rugido!</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>Rinne...</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>Você se atreve...</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>Rugido!</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "Aquele é o General Fujikumo? O que aconteceu com ele?",
  ui_story_5020_50201601_98_dialog_content = "*Tosse* Isso não é importante agora!",
  ui_story_5020_50201601_99_dialog_content = "Pressa! Mate-o com Slice of Heaven…",
  ui_story_5020_50201601_100_dialog_content = "Rinne! Pegar!",
  ui_story_5020_50201601_101_dialog_content = "Sim!",
  ui_story_5020_50201601_102_dialog_content = "(Esta é a espada sagrada que as sacerdotisas passaram de geração em geração...)",
  ui_story_5020_50201601_103_dialog_content = "(As sacerdotisas o usariam para matar fantasmas, mas o general o manteve longe deles…)",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>Bate... baque... baque...</color>",
  ui_story_5020_50201601_105_dialog_content = "(Ah... General... Kubou-sama... Talvez eu devesse te chamar de pai uma última vez...)",
  ui_story_5020_50201601_106_dialog_content = "(Minhas mãos não param de tremer enquanto seguro Slice of Heaven...)",
  ui_story_5020_50201601_107_dialog_content = "(Estou assustado, nervoso e animado ao mesmo tempo...)",
  ui_story_5020_50201601_108_dialog_content = "(Você nunca me ensinou como usar isso...)",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>Rugido!</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "Pai…",
  ui_story_5020_50201601_111_dialog_content = "Por favor... Tome isso!",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>Gaar...</anim>",
  ui_story_5020_50201602_2_dialog_content = "Ahhh... ah...",
  ui_story_5020_50201602_3_dialog_content = "Rinne, agora!",
  ui_story_5020_50201602_4_dialog_content = "Huh!",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>Uraaaagh!</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>Silvo...</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>Ahn... ah... ah...</anim>",
  ui_story_5020_50201602_8_dialog_content = "Em geral?",
  ui_story_5020_50201602_9_dialog_content = "Conseguimos!",
  ui_story_5020_50201602_10_dialog_content = "Mate os fantasmas e os transforme de volta em humanos...",
  ui_story_5020_50201602_11_dialog_content = "É este o verdadeiro poder de Slice of Heaven?!",
  ui_story_5020_50201602_12_dialog_content = "Rinne... Vocês realmente pegaram o Slice of Heaven ...",
  ui_story_5020_50201602_13_dialog_content = "Você fez bem…",
  ui_story_5020_50201602_14_dialog_content = "Venha até mim…",
  ui_story_5020_50201602_15_dialog_content = "Geral, você...",
  ui_story_5020_50201602_16_dialog_content = "Por todas as coisas imperdoáveis que você fez...",
  ui_story_5020_50201602_17_dialog_content = "Você pode se sentir frustrado e desamparado às vezes, mas isso não justifica sua busca implacável pelo poder.",
  ui_story_5020_50201602_18_dialog_content = "O fogo em Koufu-jou se extinguiu.",
  ui_story_5020_50201602_19_dialog_content = "… E é hora de você descansar.",
  ui_story_5020_50201602_20_dialog_content = "Frustrado e desamparado? Hahah...",
  ui_story_5020_50201602_21_dialog_content = "Afinal, você leu a carta.",
  ui_story_5020_50201602_22_dialog_content = "Além do que você viu, há outras coisas que você nunca entenderá.",
  ui_story_5020_50201602_23_dialog_content = "Mas as crianças não devem se sentir frustradas e desamparadas.",
  ui_story_5020_50201602_24_dialog_content = "Rinne, você cresceu.",
  ui_story_5020_50201602_25_dialog_content = "Você não vai me chamar de Kubou-sama uma última vez?",
  ui_story_5020_50201602_26_dialog_content = "...",
  ui_story_5020_50201602_27_dialog_content = "Hmm! Você não merece esse título!",
  ui_story_5020_50201602_28_dialog_content = "Fujikumo, seus dias acabaram.",
  ui_story_5020_50201602_29_dialog_content = "Olhe ao redor.",
  ui_story_5020_50201602_30_dialog_content = "Ei, pô! Isso é o que eu chamo de carma.",
  ui_story_5020_50201602_31_dialog_content = "Ajoelhe-se... Sim, ajoelhe-se... Hahahah! O majestoso General Fujikumo foi reduzido a um prisioneiro!",
  ui_story_5020_50201602_32_dialog_content = "Por que estamos perdendo tempo falando com ele? Irmãos, acabem com ele! Uma oferta extra para o Festival Kasuga!",
  ui_story_5020_50201602_33_dialog_content = "Isso mesmo! Mate ele…",
  ui_story_5020_50201602_34_dialog_content = "Hahahahahahahahahaha...",
  ui_story_5020_50201602_35_dialog_content = "Não se atreva!",
  ui_story_5020_50201602_36_dialog_content = "Afastem-se seus tolos! Ferir Kubou-sama está fazendo inimigos de toda a ilha principal!",
  ui_story_5020_50201602_37_dialog_content = "Ptui! Quem diabos se importa com a ilha principal?",
  ui_story_5020_50201602_38_dialog_content = "Vire-se e procure por si mesmo! Quantos de seus samurais ainda estão respirando!? Fujikumo, você merece isso!",
  ui_story_5020_50201602_39_dialog_content = "Irmãos, carga!",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>Clink...</color>",
  ui_story_5020_50201602_41_dialog_content = "Fique atrás!",
  ui_story_5020_50201602_42_dialog_content = "Dê um passo para trás... *Tosse* Volte para baixo...",
  ui_story_5020_50201602_43_dialog_content = "Cloud Island seria um lugar melhor se você matasse o General Fujikumo?",
  ui_story_5020_50201602_44_dialog_content = "...",
  ui_story_5020_50201602_45_dialog_content = "Mesmo se você matar o atual general…",
  ui_story_5020_50201602_46_dialog_content = "Um novo general será designado da ilha principal para retomar o comando da Cloud Island dentro de meio mês.",
  ui_story_5020_50201602_47_dialog_content = "Para quem você dirigirá sua raiva então?",
  ui_story_5020_50201602_48_dialog_content = "Para vocês rebeldes, Kubou-sama é um forasteiro no qual você lança o desfiladeiro.",
  ui_story_5020_50201602_49_dialog_content = "Mas, na realidade, Kubou-sama também é uma ferramenta usada por forças externas.",
  ui_story_5020_50201602_50_dialog_content = "Guardas… Removam este homem…",
  ui_story_5020_50201602_51_dialog_content = "(Fujikumo... Está lutando para falar...)",
  ui_story_5020_50201602_52_dialog_content = "Meu senhor, por favor, permita-me terminar!",
  ui_story_5020_50201602_53_dialog_content = "… Os compromissos que Kubou-sama fez para apaziguar a ilha principal…",
  ui_story_5020_50201602_54_dialog_content = "Os esforços que ele fez para manter a Ilha das Nuvens em paz... Você nunca será capaz de entender!",
  ui_story_5020_50201602_55_dialog_content = "Você pode chamá-lo de brutal… Você pode dizer que ele é pervertido…",
  ui_story_5020_50201602_56_dialog_content = "Mas você realmente acha que ele está errado?",
  ui_story_5020_50201602_57_dialog_content = "...",
  ui_story_5020_50201602_58_dialog_content = "Eu não gosto do que ele está dizendo...",
  ui_story_5020_50201602_59_dialog_content = "Mas acho que ele tem razão...",
  ui_story_5020_50201602_60_dialog_content = "Eu sempre disse isso, mas ninguém mais entende o quão complicada é a situação política...",
  ui_story_5020_50201602_61_dialog_content = "Eu poderia gerenciar Cloud Island cem vezes melhor do que esse Fujikumo!",
  ui_story_5020_50201602_62_dialog_content = "O que você está dizendo? Você está comprando suas desculpas?",
  ui_story_5020_50201602_63_dialog_content = "Antes de ir para o inimigo, você terá que lidar comigo primeiro. Eu odeio nada mais do que traidores!",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>Chirp… Twitter…</color>",
  ui_story_5020_50201602_65_dialog_content = "Heh… Kubou-sama não tem utilidade para suas sábias palavras de retrospectiva.",
  ui_story_5020_50201602_66_dialog_content = "Para ele, sua simpatia é uma humilhação!",
  ui_story_5020_50201602_67_dialog_content = "Cale a boca...",
  ui_story_5020_50201602_68_dialog_content = "Sim! Cala a boca!",
  ui_story_5020_50201602_69_dialog_content = "Apenas alguns poucos podem entender Kubou-sama…",
  ui_story_5020_50201602_70_dialog_content = "Kubou-sama, ninguém neste mundo te entende melhor do que eu!",
  ui_story_5020_50201602_71_dialog_content = "Chega!",
  ui_story_5020_50201602_72_dialog_content = "Isso é o suficiente de seu absurdo.",
  ui_story_5020_50201602_73_dialog_content = "Quem diabos é você?",
  ui_story_5020_50201602_74_dialog_content = "...",
  ui_story_5020_50201602_75_dialog_content = "Você está aqui…",
  ui_story_5020_50201701_1_dialog_content = "Essa mulher…",
  ui_story_5020_50201701_2_dialog_content = "Ela ainda está viva?",
  ui_story_5020_50201701_3_dialog_content = "Pai... Quem é ela?",
  ui_story_5020_50201701_4_dialog_content = "Xiu!",
  ui_story_5020_50201701_5_dialog_content = "Não faça perguntas. Mantenha sua boca fechada!",
  ui_story_5020_50201701_6_dialog_content = "(Mestre!)",
  ui_story_5020_50201701_7_dialog_content = "He...",
  ui_story_5020_50201701_8_dialog_content = "Esse discurso foi bastante tocante.",
  ui_story_5020_50201701_9_dialog_content = "Como subordinado, você realmente sabe como humilhar seu general.",
  ui_story_5020_50201701_10_dialog_content = "Do que você está falando?",
  ui_story_5020_50201701_11_dialog_content = "Ugh!",
  ui_story_5020_50201701_12_dialog_content = "Saia do meu caminho.",
  ui_story_5020_50201701_13_dialog_content = "...",
  ui_story_5020_50201701_14_dialog_content = "Fujikumo, você esperou por este momento por muito tempo.",
  ui_story_5020_50201701_15_dialog_content = "Finalmente.",
  ui_story_5020_50201701_16_dialog_content = "Estou um pouco adiantado.",
  ui_story_5020_50201701_17_dialog_content = "Pode não ser uma coisa ruim deixá-lo sofrer o abuso desse samurai um pouco mais.",
  ui_story_5020_50201701_18_dialog_content = "Você não precisa de simpatia ou compreensão. Você quer a morte.",
  ui_story_5020_50201701_19_dialog_content = "Não é?",
  ui_story_5020_50201701_20_dialog_content = "... Hehehe.",
  ui_story_5020_50201701_21_dialog_content = "Morrer em ação nunca é uma tragédia. O campo de batalha é onde um herói pertence.",
  ui_story_5020_50201701_22_dialog_content = "Acabe com isso para mim...",
  ui_story_5020_50201701_23_dialog_content = "Não é ruim morrer na sua mão.",
  ui_story_5020_50201701_24_dialog_content = "Fujikumo, depois de todos os negócios sujos e imundos que você fez em sua vida…",
  ui_story_5020_50201701_25_dialog_content = "Agora, demorando-se em seu último suspiro, de repente você se preocupa com a decência e a dignidade.",
  ui_story_5020_50201701_26_dialog_content = "Hahahaha! Tosse...",
  ui_story_5020_50201701_27_dialog_content = "Nagi, eu sei o quão rápido sua espada é...",
  ui_story_5020_50201701_28_dialog_content = "Se você hesitar em empunhá-lo, você não merece.",
  ui_story_5020_50201701_29_dialog_content = "Heh. Você não precisa se preocupar.",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>Clink...</color>",
  ui_story_5020_50201701_31_dialog_content = "...",
  ui_story_5020_50201701_32_dialog_content = "Eu permito que você diga suas últimas palavras.",
  ui_story_5020_50201701_33_dialog_content = "...",
  ui_story_5020_50201701_34_dialog_content = "Tsuki...",
  ui_story_5020_50201701_35_dialog_content = "É este Koufu-jou como você queria que fosse?",
  ui_story_5020_50201701_36_dialog_content = "...",
  ui_story_5020_50201701_37_dialog_content = "...",
  ui_story_5020_50201701_38_dialog_content = "Ele está morto?",
  ui_story_5020_50201701_39_dialog_content = "Creio que sim.",
  ui_story_5020_50201701_40_dialog_content = "Acho que ele não está respirando...",
  ui_story_5020_50201701_41_dialog_content = "Morta! Sério!",
  ui_story_5020_50201701_42_dialog_content = "Fujikumo está morto! Chega de generalidade para Cloud Island!",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>Isso!</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>O general está morto!</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>Viva a Ilha das Nuvens!</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>Sim...</anim>",
  ui_story_5020_50201701_47_dialog_content = "...",
  ui_story_5020_50201701_48_dialog_content = "Comandante!",
  ui_story_5020_50201701_49_dialog_content = "Você está vivo!",
  ui_story_5020_50201701_50_dialog_content = "Você é realmente Nagi-sama?",
  ui_story_5020_50201701_51_dialog_content = "Comandante? Comandante! Onde você está indo?",
  ui_story_5020_50201701_52_dialog_content = "Por favor, aguarde!",
  ui_story_5020_50201701_53_dialog_content = "...?",
  ui_story_5020_50201701_54_dialog_content = "É você.",
  ui_story_5020_50201701_55_dialog_content = "Eu não gosto de dizer adeus. Faça isso rápido.",
  ui_story_5020_50201701_56_dialog_content = "Mestre, por favor, espere!",
  ui_story_5020_50201701_57_dialog_content = "Yao está aqui se curvando ao mestre!",
  ui_story_5020_50201701_58_dialog_content = "Pelo que?",
  ui_story_5020_50201701_59_dialog_content = "Yao veio para Cloud Island e passou por tantos problemas, tudo graças ao mestre!",
  ui_story_5020_50201701_60_dialog_content = "(Isso não soa bem!)",
  ui_story_5020_50201701_61_dialog_content = "Graças ao mestre, pude vivenciar os conflitos e as lutas de sua geração.",
  ui_story_5020_50201701_62_dialog_content = "Eu nunca tive nada assim antes.",
  ui_story_5020_50201701_63_dialog_content = "Por favor, permita-me chamá-lo de mestre mais uma vez.",
  ui_story_5020_50201701_64_dialog_content = "Mestre, se você precisar de ajuda no futuro, entre em contato com a Lin Guild em Umbraton, Astra!",
  ui_story_5020_50201701_65_dialog_content = "Yao virá em seu auxílio, não importa o quão longe eu deva viajar!",
  ui_story_5020_50201701_66_dialog_content = "Hehe... Obrigado, Yao.",
  ui_story_5020_50201701_67_dialog_content = "Mas para o resto desta jornada, eu devo estar por minha conta.",
  ui_story_5020_50201701_68_dialog_content = "Preciso acabar com o domínio da ilha principal sobre a Ilha das Nuvens. Esta é a única maneira de colocar todas essas pontuações antigas para trás.",
  ui_story_5020_50201701_69_dialog_content = "Você está indo para a ilha principal?",
  ui_story_5020_50201701_70_dialog_content = "Mestre, por favor...",
  ui_story_5020_50201701_71_dialog_content = "Tomar cuidado. E leve a Cloud Island a um futuro melhor.",
  ui_story_5020_50201701_72_dialog_content = "O Wisp e eu estamos sempre prontos para lutar por você.",
  ui_story_5020_50201701_73_dialog_content = "Oh? Amemori...",
  ui_story_5020_50201701_74_dialog_content = "Você cresceu.",
  ui_story_5020_50201701_75_dialog_content = "Você é um comandante melhor do Wisp do que eu já fui.",
  ui_story_5020_50201701_76_dialog_content = "Nagi-sama, tome cuidado. May a vitória esteja com você!",
  ui_story_5020_50201701_77_dialog_content = "...",
  ui_story_5020_50201701_78_dialog_content = "Acho que vou te ver por aí.",
  ui_story_5020_50201701_79_dialog_content = "Ah! Por favor, espere mais um segundo. Que...",
  ui_story_5020_50201701_80_dialog_content = "PlayerName, devemos dar isso a ela.",
  ui_story_5020_50201701_81_dialog_content = "Tem razão!",
  ui_story_5020_50201701_82_dialog_content = "O quê?",
  ui_story_5020_50201701_83_dialog_content = "Nagi, por favor, aceite este caderno.",
  ui_story_5020_50201701_84_dialog_content = "Ela não deu nenhuma ordem...",
  ui_story_5020_50201701_85_dialog_content = "Mas a relíquia dela pode ser importante para você.",
  ui_story_5020_50201701_86_dialog_content = "Isso deve ser guardado por você.",
  ui_story_5020_50201701_87_dialog_content = "Tsuki tinha um diário...",
  ui_story_5020_50201701_88_dialog_content = "Nunca a vi escrevendo...",
  ui_story_5020_50201701_89_dialog_content = "Resolvi deixar tudo de lado e ir para a ilha principal.",
  ui_story_5020_50201701_90_dialog_content = "Por favor, guarde para mim.",
  ui_story_5020_50201701_91_dialog_content = "Tem certeza de que não quer ler?",
  ui_story_5020_50201701_92_dialog_content = "Para seguir em frente, precisamos deixar o passado, não fugir dele.",
  ui_story_5020_50201701_93_dialog_content = "Algumas de suas perguntas podem encontrar resposta, e alguns nós em seu coração podem se abrir.",
  ui_story_5020_50201701_94_dialog_content = "...",
  ui_story_5020_50201701_95_dialog_content = "Claro.",
  ui_story_5020_50201701_96_dialog_content = "...",
  ui_story_5020_50201701_97_dialog_content = "...",
  ui_story_5020_50201701_98_dialog_content = "<size=30>Irmã…</size>",
  ui_story_5020_50201701_99_dialog_content = "Tsuki...",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>Em uma rua na cidade do castelo de Koufu-jou</color>",
  ui_story_5020_50201701_101_dialog_content = "Ahh! Que cena harmônica!",
  ui_story_5020_50201701_102_dialog_content = "O palco é decorado com tantas bandeiras coloridas. Os taikos estão prontos. As pessoas estão pescando debaixo de cerejeiras…",
  ui_story_5020_50201701_103_dialog_content = "E este ninja-sama está sentado aqui ao meu lado em vez de causar problemas.",
  ui_story_5020_50201701_104_dialog_content = "Por favor, não me chame assim.",
  ui_story_5020_50201701_105_dialog_content = "Não decepcione Momo e Anzu. Este chá é muito saboroso.",
  ui_story_5020_50201701_106_dialog_content = "… Eu odeio coisas saborosas. Não vou comer nada desta barraca.",
  ui_story_5020_50201701_107_dialog_content = "(Resmunga...)",
  ui_story_5020_50201701_108_dialog_content = "Argh...!",
  ui_story_5020_50201701_109_dialog_content = "Chegando! Desculpe a espera!",
  ui_story_5020_50201701_110_dialog_content = "Por favor, experimente nosso novo prato, Kaniya Veggie Ramen!",
  ui_story_5020_50201701_111_dialog_content = "Aperfeiçoamos a receita após inúmeros testes de sabor com nosso destemido Guerreiro Yao!",
  ui_story_5020_50201701_112_dialog_content = "Arroto... Estou completamente satisfeito...",
  ui_story_5020_50201701_113_dialog_content = "(Yao está em coma alimentar!)",
  ui_story_5020_50201701_114_dialog_content = "Nesse caso...",
  ui_story_5020_50201701_115_dialog_content = "Eu vou dar algumas mordidas.",
  ui_story_5020_50201701_116_dialog_content = "Devemos nos apressar com alguma nova história para este novo prato!",
  ui_story_5020_50201701_117_dialog_content = "Novos clientes não retornarão para histórias antigas!",
  ui_story_5020_50201701_118_dialog_content = "PlayerName-sama, qual história você acha que é adequada?",
  ui_story_5020_50201701_119_dialog_content = "Ahn? Você está perguntando pra mim?",
  ui_story_5020_50201701_120_dialog_content = "Na minha humilde opinião…",
  ui_story_5020_50201701_121_option_content = "Você pode contar a história de três velhos amigos.",
  ui_story_5020_50201701_122_dialog_content = "Três velhos amigos dedicaram suas vidas a proteger esta terra à sua maneira.",
  ui_story_5020_50201701_123_dialog_content = "O par de irmãs estava condenado a se separar e seguir caminhos diferentes, mas sua música ainda pode ser ouvida aqui.",
  ui_story_5020_50201701_124_dialog_content = "A incompreendida sacerdotisa e o general superaram suas diferentes posições e desenvolveram confiança um no outro.",
  ui_story_5020_50201701_125_dialog_content = "Os dois lutadores lutaram até o último segundo, mas acabaram se entendendo e se despedindo um do outro.",
  ui_story_5020_50201701_126_dialog_content = "Esta terra progrediu em direção à paz, assim como eles haviam previsto...",
  ui_story_5020_50201701_127_dialog_content = "Você realmente acredita que esta é uma boa história ao lado da mesa?",
  ui_story_5020_50201701_128_option_content = "Você pode contar a história de três crianças pequenas.",
  ui_story_5020_50201701_129_dialog_content = "Três crianças incomuns partem em uma jornada contra o mal e monstros por diferentes razões…",
  ui_story_5020_50201701_130_dialog_content = "Ao longo do caminho, todos eles aprenderam coisas que eram muito mais preciosas do que a vitória.",
  ui_story_5020_50201701_131_dialog_content = "O soldadinho de chumbo mascarado encheu seu coração de amizade.",
  ui_story_5020_50201701_132_dialog_content = "O espantalho encharcado de água do mar encheu sua cabeça de lembranças.",
  ui_story_5020_50201701_133_dialog_content = "A leoa disfarçada encontrou coragem para lutar contra seu destino...",
  ui_story_5020_50201701_134_dialog_content = "Não plagie a história de ninar das crianças do norte! Isso é demais!",
  ui_story_5020_50201701_135_dialog_content = "Hmm... Parece bom.",
  ui_story_5020_50201701_136_dialog_content = "Vamos trabalhar em um roteiro em torno PlayerName-ideia do sama!",
  ui_story_5020_50201701_137_dialog_content = "Primeiro, precisamos de um final adequado para o nosso conto da Ilha das Nuvens…",
  ui_story_5020_50201701_138_dialog_content = "Um final adequado? Existe alguma coisa que não estamos cientes?",
  ui_story_5020_50201701_139_dialog_content = "Mmm... Acabamos de receber esta informação do nosso trabalhador de meio período!",
  ui_story_5020_50201701_140_dialog_content = "Se você realmente quer ouvir...",
  ui_story_5020_50201701_141_dialog_content = "Mais um por favor.",
  ui_story_5020_50201701_142_dialog_content = "Querido, você é o melhor. A última vez que nossa história terminou com...",
  ui_story_5020_50201701_143_dialog_content = "Fujikumo é dito ser indestrutível com um coração duro como a rocha e frio como o gelo. Ninguém na Ilha das Nuvens conhece seu ponto fraco, exceto...",
  ui_story_5020_50201701_144_dialog_content = "Tada... Nossa Kayano!",
  ui_story_5020_50201701_145_dialog_content = "Huh? Isso é inesperado! Você me chamou?",
  ui_story_5020_50201701_146_dialog_content = "Venha aqui, nosso pequeno trabalhador. Contar PlayerName-sama o que você viu quando estava ausente do trabalho naquele dia.",
  ui_story_5020_50201701_147_dialog_content = "Eu... fui admirar as flores de cerejeira no <color=#FFB400>cemitério</color> fora da cidade… Esta é a época em que as cerejeiras brancas caem…",
  ui_story_5020_50201701_148_dialog_content = "Na entrada, vi um homem lá dentro...",
  ui_story_5020_50201701_149_dialog_content = "?!",
  ui_story_5020_50201701_150_dialog_content = "(O homem visitou o cemitério antes de nós!)",
  ui_story_5020_50201701_151_dialog_content = "Quem é ele?",
  ui_story_5020_50201701_152_dialog_content = "Ahh... PlayerName-sama é tão feroz e impaciente...",
  ui_story_5020_50201701_153_dialog_content = "Eu... sinto muito...",
  ui_story_5020_50201701_154_dialog_content = "Ele não reparou em mim, mas eu o vi claramente...",
  ui_story_5020_50201701_155_dialog_content = "Aquele homem era… <color=#FFB400>General Fujikumo</color>…",
  ui_story_5020_50201701_156_dialog_content = "...",
  ui_story_5020_50201701_157_dialog_content = "Ele ficou diante de uma tumba em silêncio, sem um único samurai por perto...",
  ui_story_5020_50201701_158_dialog_content = "Achei que ele pegaria o sabre dourado que estava na frente da lápide... Mas ele não pegou...",
  ui_story_5020_50201701_159_dialog_content = "Ele solenemente largou um livro antes de se despedir...",
  ui_story_5020_50201701_160_dialog_content = "Aí... Aí ele quase me viu... Fugi na hora...",
  ui_story_5020_50201701_161_dialog_content = "...",
  ui_story_5020_50201701_162_dialog_content = "Era Fujikumo...",
  ui_story_5020_50201701_163_dialog_content = "Isso mesmo! O insensível general prestou homenagem a um velho amigo em um canto desolado da ilha…",
  ui_story_5020_50201701_164_dialog_content = "Hmm! Isso atrairá muito mais novos clientes!",
  ui_story_5020_50201701_165_dialog_content = "Ei! Mas isso...",
  ui_story_5020_50201701_166_dialog_content = "Tá tudo bem, PlayerName.",
  ui_story_5020_50201701_167_dialog_content = "Se esta pudesse ser a última memória do general e da sacerdotisa anterior na Ilha das Nuvens...",
  ui_story_5020_50201701_168_dialog_content = "É um final muito bom para o passado da ilha.",
  ui_story_5020_50201701_169_dialog_content = "Afinal, uma nova era…",
  ui_story_5020_50201701_170_dialog_content = "Está prestes a começar!",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201701_172_dialog_content = "Mover! Mova sua barraca da estrada para o castelo principal.",
  ui_story_5020_50201701_173_dialog_content = "Castelo principal? Que castelo? Quem é esse forasteiro?",
  ui_story_5020_50201701_174_dialog_content = "...",
  ui_story_5020_50201701_175_dialog_content = "Veja! A ilha principal já enviou tropas. Esses uniformes têm o padrão da ilha principal.",
  ui_story_5020_50201701_176_dialog_content = "Como esperado, eles não vão desistir de seu controle sobre Cloud Island.",
  ui_story_5020_50201701_177_dialog_content = "Rinne, você permanecerá neste lugar?",
  ui_story_5020_50201701_178_dialog_content = "Heheh. Eu fiz meu plano... E você...",
  ui_story_5020_50201701_179_dialog_content = "Como você planeja sair?",
  ui_story_5020_50201701_180_dialog_content = "Não se preocupe. Vamos dirigir o Colossus e pegar o mesmo caminho de volta.",
  ui_story_5020_50201701_181_dialog_content = "Falando nisso... Soroz poderia usar algum serviço...",
  ui_story_5020_50201701_182_dialog_content = "Colosso? Soroz?",
  ui_story_5020_50201701_183_dialog_content = "Ahh… Muitas palavras novas para eu aprender…",
  ui_story_5020_50201701_184_dialog_content = "Eu realmente preciso ir e explorar o mundo lá fora.",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>Porto Koufu-jou</color>",
  ui_story_5020_50201701_186_dialog_content = "OK. É hora de dizer adeus!",
  ui_story_5020_50201701_187_dialog_content = "Meu barco deve chegar a qualquer segundo.",
  ui_story_5020_50201701_188_dialog_content = "Patético.",
  ui_story_5020_50201701_189_dialog_content = "Não estou interessado em te ver embora...",
  ui_story_5020_50201701_190_dialog_content = "Mas isso faz parte da maneira como Cloud Island trata nossos hóspedes.",
  ui_story_5020_50201701_191_dialog_content = "Amemori...",
  ui_story_5020_50201701_192_dialog_content = "Eu...",
  ui_story_5020_50201701_193_dialog_content = "<size=45>Uau... Uau!</size>",
  ui_story_5020_50201701_194_dialog_content = "Vocês! O que você quer?",
  ui_story_5020_50201701_195_dialog_content = "Wuahhhh... Amemori também não suporto me ver partir! EU...",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>Eu não quero dizer adeus... Woah!</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "Pronto pronto. Yao, não chore.",
  ui_story_5020_50201701_198_dialog_content = "Nos veremos novamente.",
  ui_story_5020_50201701_199_dialog_content = "Uau... O quê?",
  ui_story_5020_50201701_200_dialog_content = "Rinne... Tu...",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>Uau Uau! Você não vai comigo?</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>Uau Uau…</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "Ai ai...",
  ui_story_5020_50201701_204_dialog_content = "Yao, ouvir.",
  ui_story_5020_50201701_205_dialog_content = "Tenho muito o que fazer aqui em Cloud Island...",
  ui_story_5020_50201701_206_dialog_content = "As forças da ilha principal já estão agindo. Devo ficar aqui para manter os freios e contrapesos.",
  ui_story_5020_50201701_207_dialog_content = "Eu guardei o Cloud Mirror e o Slice of Heaven em segurança...",
  ui_story_5020_50201701_208_dialog_content = "Usarei minha própria força para manter a paz e a ordem na Ilha das Nuvens.",
  ui_story_5020_50201701_209_dialog_content = "Claro... Amemori e o Wisp vai me ajudar também. Certo?",
  ui_story_5020_50201701_210_dialog_content = "Definitivamente.",
  ui_story_5020_50201701_211_dialog_content = "Com você ou sem, sempre foi a missão do Wisp lutar contra a ilha principal.",
  ui_story_5020_50201701_212_dialog_content = "Como você pode ver, querida Yao... Eu tenho que ficar e trazer mudanças para Cloud Island.",
  ui_story_5020_50201701_213_dialog_content = "Você confia em mim?",
  ui_story_5020_50201701_214_dialog_content = "*Solução*... eu sei Rinne posso fazer isso...",
  ui_story_5020_50201701_215_dialog_content = "Então... Rinne e Amemori... Momo, Anzu e Kayano...",
  ui_story_5020_50201701_216_dialog_content = "Por favor tome cuidado!",
  ui_story_5020_50201701_217_dialog_content = "Óh, e PlayerName e Vice!",
  ui_story_5020_50201701_218_dialog_content = "Sim?",
  ui_story_5020_50201701_219_dialog_content = "Obrigado por aceitar o meu caso e viajar aqui comigo.",
  ui_story_5020_50201701_220_dialog_content = "Obrigado por todos esses amigos que fizemos... Todos vocês são tão preciosos quanto memórias...",
  ui_story_5020_50201701_221_dialog_content = "As coisas que esta ilha me deu serão apreciadas pelo resto da minha vida.",
  ui_story_5020_50201701_222_dialog_content = "*Cheira*",
  ui_story_5020_50201701_223_dialog_content = "(Droga! É melhor eu confortá-la agora...)",
  ui_story_5020_50201701_224_dialog_content = "Por esse motivo...",
  ui_story_5020_50201701_225_dialog_content = "Uma grande quantia, muito além de 7 dígitos, será transferida para sua conta assim que eu voltar ao clã Lin!",
  ui_story_5020_50201701_226_dialog_content = "Hã?!",
  ui_story_5020_50201701_227_dialog_content = "… Nada de bom? Esta é a única maneira de expressar minha gratidão!",
  ui_story_5020_50201701_228_dialog_content = "Isso é demais!",
  ui_story_5020_50201701_229_dialog_content = "Ah... Como devemos gastar esse dinheiro? Precisamos consertar o Colosso... Então...",
  ui_story_5020_50201701_230_dialog_content = "(Não pode esperar já?)",
  ui_story_5020_50201701_231_dialog_content = "Ah! Algo está se aproximando lentamente...",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>Bip... Uau...</color>",
  ui_story_5020_50201701_233_dialog_content = "Hum... ah...",
  ui_story_5020_50201701_234_dialog_content = "Então esse é o poder do mar…",
  ui_story_5020_50201701_235_dialog_content = "Uau! Irmã, por favor! Você está me deixando nervoso!",
  ui_story_5020_50201701_236_dialog_content = "Não conte a ninguém que o célebre Ying do reputado clã Lin não aguenta um passeio de barco!",
  ui_story_5020_50201701_237_dialog_content = "Pare... *vomitando* Pare de gritar...",
  ui_story_5020_50201701_238_dialog_content = "*Soluço*",
  ui_story_5020_50201701_239_dialog_content = "Nosso distinto cliente que come sete tigelas de ramen de uma só vez...",
  ui_story_5020_50201701_240_dialog_content = "Por favor, volte para visitar Cloud Island quando tiver tempo…",
  ui_story_5020_50201701_241_dialog_content = "Kaniya Ramen está aqui para atendê-lo!",
  ui_story_5020_50201701_242_dialog_content = "*Soluço*",
  ui_story_5020_50201701_243_dialog_content = "Hum... chefes...",
  ui_story_5020_50201701_244_dialog_content = "O novo prato que o Guerreiro Yao feito com certeza vai ser um grande sucesso...",
  ui_story_5020_50201701_245_dialog_content = "Não fique muito chateado…",
  ui_story_5020_50201701_246_dialog_content = "Tem razão!",
  ui_story_5020_50201701_247_dialog_content = "Yao...",
  ui_story_5020_50201701_248_dialog_content = "Viagens seguras...",
  ui_story_5020_50201701_249_dialog_content = "Não perca a cara da próxima vez.",
  ui_story_5020_50201701_250_dialog_content = "Ah...",
  ui_story_5020_50201701_251_dialog_content = "Vocês...",
  ui_story_5020_50201701_252_dialog_content = "Espero vê-lo em breve!",
  ui_story_5020_50201701_253_dialog_content = "Yao embarcou no barco. Rinne acenou sua despedida. Amemori ficou atrás dela, observando em silêncio.",
  ui_story_5020_50201701_254_dialog_content = "Acho que eles apreciariam cada segundo dessa despedida antes que o barco saísse de suas vistas.",
  ui_story_5020_50201701_255_dialog_content = "Dez anos atrás, a morte separou as três meninas.",
  ui_story_5020_50201701_256_dialog_content = "Hoje, a morte mais uma vez os envia por caminhos diferentes.",
  ui_story_5020_50201701_257_dialog_content = "A neve rosa pálida floresceu e caiu na Ilha Cloud ano após ano na última década, observando as garotas se unirem antes de se separarem.",
  ui_story_5020_50201701_258_dialog_content = "Também assistiu o falecido se reunir mais uma vez além da morte.",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>O fim</color>"
}
return config
